bool GameDataScript::IsEqualTo(const GameData *data) const
{
#if USE_PRECOMPILATION
  const ScriptVM *val1 = GetScript();
  const ScriptVM *val2 = static_cast<const GameDataScript *>(data)->GetScript();
#else
  const Script *val1 = GetScript();
  const Script *val2 = static_cast<const GameDataScript *>(data)->GetScript();
#endif
  return val1 == val2;
}

