bool GameDataText::IsEqualTo(const GameData *data) const
{
  const GameTextType val1 = GetValue();
  const GameTextType val2 = static_cast<const GameDataText *>(data)->GetValue();

  if (val1)
  {
    if (val2) return CompareText(val1, val2);
    else return false;
  }
  else return !val2;
}

