bool CheckSize(const GameState *state, GameArrayType array, int size)
{
  if (array.Size() == size) return true;
  state->SetError(EvalDim, array.Size(), size);
  return false;
}

bool CheckType(const GameState *state, GameValuePar oper, const GameType &type)
{
  if (oper.GetType() == type) return true;
  state->TypeError(type, oper.GetType());
  return false;
}

GameValue ObjNull(const GameState *state)
{
  return OBJECT_NULL;
}

GameValue ObjIsNull( const GameState *state, GameValuePar oper1 )
{
  if (oper1.GetType() == GameObject)
  {
    Object *obj = static_cast<GameDataObject *>(oper1.GetData())->GetObject();
    return !obj;
  }
  else return true;
}

/// convert game value to object
Object *GetObject( GameValuePar oper )
{
  if (oper.GetNil()) return NULL;
  if( oper.GetType()==GameObject )
  {
    return static_cast<GameDataObject *>(oper.GetData())->GetObject();
  }
  return NULL;
}

/// convert game value to target
static Target *GetTarget( GameValuePar oper )
{
  if (oper.GetNil()) return NULL;
  if( oper.GetType()==GameTarget )
  {
    return static_cast<GameDataTarget *>(oper.GetData())->GetTarget();
  }
  return NULL;
}


static bool GetVector(const GameState *state, Vector3 &ret, GameValuePar oper)
{
  if (oper.GetType()!=GameArray) return false;
  const GameArrayType &array = oper;
  if (array.Size() != 3)
  {
    if (state) state->SetError(EvalDim, array.Size(), 3);
    return false;
  }
  if (array[0].GetType() != GameScalar)
  {
    if (state) state->TypeError(GameScalar, array[0].GetType());
    return false;
  }
  if (array[1].GetType() != GameScalar)
  {
    if (state) state->TypeError(GameScalar, array[1].GetType());
    return false;
  }
  if (array[2].GetType() != GameScalar)
  {
    if (state) state->TypeError(GameScalar, array[2].GetType());
    return false;
  }

  float x = array[0];
  float z = array[1];
  float y = array[2];
  ret = Vector3(x, y, z);
  return true;  
}

static GameValue GetVectorValue(const GameState *state, Vector3Par pos)
{
  GameValue value = state->CreateGameValue(GameArray);
  GameArrayType &array = value;
  array.Resize(3);
  array[0] = pos[0];
  array[1] = pos[2];
  array[2] = pos[1];
  return value;
}


static GameValue VectorBinVV(const GameState *state, GameValuePar oper1, GameValuePar oper2, std::function<float (float, float)> func)
{
  GameValue ret = state->CreateGameValue(GameArray);
  GameArrayType &retArray = ret;
  const GameArrayType &o1 = oper1;
  const GameArrayType &o2 = oper2;
  if (!CheckSize(state,o2,o1.Size()))
  {
    return ret;
  }
  retArray.Resize(o1.Size());
  for (int i=0; i<o1.Size(); i++)
  {
    // TODO: consider using scripted overloads of +
    if (!CheckType(state,o1[i],GameScalar)) return ret;
    if (!CheckType(state,o2[i],GameScalar)) return ret;
    float o1v = o1[i], o2v = o2[i];
    retArray[i] = func(o1v,o2v);
  }
  return ret;

}

static GameValue VectorBinSV(const GameState *state, GameValuePar oper1, GameValuePar oper2, std::function<float (float, float)> func)
{
  GameValue ret = state->CreateGameValue(GameArray);
  GameArrayType &retArray = ret;
  float o1 = oper1;
  const GameArrayType &o2 = oper2;
  retArray.Resize(o2.Size());
  for (int i=0; i<o2.Size(); i++)
  {
    if (!CheckType(state,o2[i],GameScalar)) return ret;
    float o2v = o2[i];
    retArray[i] = func(o1,o2v);
  }
  return ret;
}

static GameValue VectorAdd(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  return VectorBinVV(state,oper1,oper2,[](float a, float b){return a+b;});
}

static GameValue VectorSub(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  return VectorBinVV(state,oper1,oper2,[](float a, float b){return a-b;});
}

static GameValue VectorMul(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  return VectorBinVV(state,oper1,oper2,[](float a, float b){return a*b;});
}
static GameValue VectorMulSV(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  return VectorBinSV(state,oper1,oper2,[](float a, float b){return a*b;});
}
static GameValue VectorMulVS(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  return VectorBinSV(state,oper2,oper1,[](float a, float b){return a*b;});
}

static Target *FindTargetReveal(AIBrain *unit, EntityAI *veh)
{
  Target *tgt = unit->FindTarget(veh);
  if (tgt) return tgt;
  // reveal target
  return unit->AddTarget(veh,1.1,0.3,3.0f);
}

