GameValue ObjSetFuel( const GameState *state, GameValuePar oper1, GameValuePar oper2 )
{
  Object *obj=GetObject(oper1);
  if( !obj ) return NOTHING;
  if (obj->IsDamageDestroyed()) return NOTHING;
  EntityAI *ai=dyn_cast<EntityAI>(obj);
  if( !ai ) return NOTHING;
  float maxFuel = ai->GetType()->GetFuelCapacity();
  float ammount = oper2;
  ai->Refuel(ammount*maxFuel-ai->GetFuel());
  return NOTHING;
}

GameValue ObjFuel( const GameState *state, GameValuePar oper1 )
{
  Object *obj=GetObject(oper1);
  if( !obj ) return 0.0f;
  EntityAI *ai=dyn_cast<EntityAI>(obj);
  if( !ai ) return 0.0f;
  float maxFuel=ai->GetType()->GetFuelCapacity();
  float fuel=maxFuel<=0 ? 1 : ai->GetFuel()/maxFuel;
  return fuel;
}

GameValue ObjEmptyPosns( const GameState *state, GameValuePar oper1, GameValuePar oper2 )
{
  Object *obj=GetObject(oper1);
  if( !obj ) return 0.0f;
  if (obj->IsDamageDestroyed()) return 0.0f;
  Transport *veh = dyn_cast<Transport>(obj);
  if (!veh) return 0.0f;
  if (oper2.GetType() != GameString)
  {
    state->TypeError(GameString, oper2.GetType());
    return 0.0f;
  }  
  RString posn = oper2;

  int nPos = 0;

  if (strcmpi(posn,"driver") == 0)
    nPos = !veh->QIsDriverIn() && veh->Type()->HasDriver();
  else if (strcmpi(posn,"gunner") == 0)
    nPos = !veh->QIsGunnerIn() && veh->Type()->HasGunner();
  else if (strcmpi(posn,"commander") == 0)
    nPos = !veh->QIsCommanderIn() && veh->Type()->HasObserver();
  else if (strcmpi(posn,"cargo") == 0)
    nPos = veh->GetFreeManCargo();

  return (float)nPos;
}

