/*!
\patch 5139 Date 3/13/2007 by Jirka
- Fixed: function "selectWeapon" now switches character pose when launcher is selected
*/

GameValue ObjSelectWeapon( const GameState *state, GameValuePar oper1, GameValuePar oper2 )
{
  Object *obj = GetObject(oper1);
  if (!obj) return NOTHING;
  if (obj->IsDamageDestroyed()) return NOTHING;
  EntityAIFull *veh = dyn_cast<EntityAIFull>(obj);
  if (!veh) return NOTHING;

  // TODO: which turret?
  TurretContext context;
  if (veh->GetPrimaryGunnerTurret(context))
  {
    RString name = oper2;
    context._weapons->ForEachMuzzle([&context, veh, name](const WeaponModePtr &ptr) -> bool
    {
      const MuzzleType *muzzle = ptr.GetMuzzleType();
      if (muzzle && stricmp(muzzle->GetName(), name) == 0)
      {
        context._weapons->SelectWeapon(veh, ptr);
        veh->OnWeaponSelected();
        return true; // done
      }
      return false; // continue
    });
  }
  return NOTHING;
}

GameValue VehGetCurrentWeapon(const GameState *state, GameValuePar oper1)
{
  Object *obj = GetObject(oper1);
  EntityAIFull *veh = dyn_cast<EntityAIFull>(obj);
  if (!veh) return RString();

  // TODO: which turret?
  TurretContext context;
  if (!veh->GetPrimaryGunnerTurret(context)) return RString();

  // Find the current slot
  WeaponModePtr index = context._weapons->ValidatedCurrentWeapon();
  if (!index.IsValid()) return RString();

  const WeaponType *weapon = index.GetWeaponType();
  if (!weapon) return RString();

  return weapon->GetName();
}

GameValue VehGetCurrentMagazine(const GameState *state, GameValuePar oper1)
{
  Object *obj = GetObject(oper1);
  EntityAIFull *veh = dyn_cast<EntityAIFull>(obj);
  if (!veh) return RString();

  // TODO: which turret?
  TurretContext context;
  if (!veh->GetPrimaryGunnerTurret(context)) return RString();

  // Find the current slot
  WeaponModePtr index = context._weapons->ValidatedCurrentWeapon();
  if (!index.IsValid()) return RString();

  const Magazine *magazine = index.GetMagazine();
  if (!magazine) return RString();

  const MagazineType *type = magazine->Type();
  if (!type) return RString();

  return type->GetName();
}

