GameValue ObjGetPrimaryWeapon( const GameState *state, GameValuePar oper1 )
{
  Object *obj=GetObject(oper1);
  if( !obj ) return "";
  EntityAIFull *ai=dyn_cast<EntityAIFull>(obj);
  if( !ai ) return "";

  RString name = "";
  // TODO: which turret?
  TurretContext context;
  if (ai->GetPrimaryGunnerTurret(context))
  {
    context._weapons->ForEachWeapon([&name](Weapon *weapon) -> bool
    {
      const WeaponType *type = weapon->Type();
      if (!type) return false; // continue
      if ((type->_weaponType & MaskSlotPrimary) != 0)
      {
        name = type->GetName();
        return true; // found
      }
      return false; // continue
    });
  }

  return name;
}

GameValue ObjGetSecondaryWeapon( const GameState *state, GameValuePar oper1 )
{
  Object *obj=GetObject(oper1);
  if( !obj ) return "";
  EntityAIFull *ai=dyn_cast<EntityAIFull>(obj);
  if( !ai ) return "";

  RString name = "";
  // TODO: which turret?
  TurretContext context;
  if (ai->GetPrimaryGunnerTurret(context))
  {
    context._weapons->ForEachWeapon([&name](Weapon *weapon) -> bool
    {
      const WeaponType *type = weapon->Type();
      if (!type) return false; // continue
      if
      (
        (type->_weaponType & MaskSlotSecondary) != 0 &&
        (type->_weaponType & MaskSlotPrimary) == 0
      )
      {
        name = type->GetName();
        return true; // found
      }
      return false; // continue
    });
  }

  return name;
}

static Turret *GetTurret(const GameState *state, Transport *veh, GameValuePar oper)
{
  // check the argument
  if (!CheckType(state, oper, GameArray)) return NULL;
  const GameArrayType &array = oper;
  int n = array.Size();
  for (int i=0; i<n; i++)
  {
    if (!CheckType(state, array[i], GameScalar)) return NULL;
  }
  // read the turret path
  TurretPath path;
  path.Resize(n);
  for (int i=0; i<n; i++) path[i] = toInt((float)array[i]);
  // find the turret
  return veh->GetTurret(path.Data(), path.Size());
}


GameValue ObjGetAllWeapons( const GameState *state, GameValuePar oper1 )
{
  GameValue value = state->CreateGameValue(GameArray);
  GameArrayType &array = value;

  Object *obj=GetObject(oper1);
  if( !obj ) return value;
  EntityAIFull *ai=dyn_cast<EntityAIFull>(obj);
  if( !ai ) return value;

  // TODO: which turret?
  TurretContext context;
  if (ai->GetPrimaryGunnerTurret(context))
  {
    context._weapons->ForEachWeapon([&array](Weapon *weapon) -> bool
    {
      const WeaponType *type = weapon->Type();
      if (!type) return false; // continue
      if (type->_weaponType == 0) return false; // continue
      array.Add(type->GetName());
      return false; // continue
    });
  }

  return value;
}

GameValue ObjWeaponsTurret( const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  GameValue value = state->CreateGameValue(GameArray);
  GameArrayType &arrayOut = value;

  Object *obj=GetObject(oper1);
  if( !obj ) return value;
  Transport *vehicle=dyn_cast<Transport>(obj);
  if( !vehicle ) return value;

  // check the argument
  if(oper2.GetType() != GameArray) return value;
  const GameArrayType &array = oper2;
  int n = array.Size();
  for (int i=0; i<n; i++)
  {
    if (!CheckType(state, array[i], GameScalar)) return value;
  }
  // read the turret path
  TurretPath path;
  path.Resize(n);
  for (int i=0; i<n; i++) path[i] = toInt((float)array[i]);

  Turret* turret = NULL;
  // find the turret
  if(n == 1 && path[0] == -1)
  {//driver turret
    TurretContext context;
    if(vehicle->GetDriverTurret(context))
    {
      context._weapons->ForEachWeapon([&arrayOut](Weapon *weapon) -> bool
      {
        const WeaponType *type = weapon->Type();
        if (!type) return false; // continue
        if (type == 0) return false; // continue
        arrayOut.Add(type->GetName());
        return false; // continue
      });
    }
  }
  else turret =  vehicle->GetTurret(path.Data(), path.Size());
  
  if (turret)
  {
    turret->GetWeapons().ForEachWeapon([&arrayOut](Weapon *weapon) -> bool
    {
      const WeaponType *type = weapon->Type();
      if (!type) return false; // continue
      if (type->_weaponType == 0) return false; // continue
      arrayOut.Add(type->GetName());
      return false; // continue
    });
  }

  return value;
}

