GameValue ObjIn( const GameState *state, GameValuePar oper1, GameValuePar oper2 )
{
  Object *obj1=GetObject(oper1);
  Object *obj2=GetObject(oper2);
  if( !obj1 || !obj2 ) return false;
  
  EntityAI *ai=dyn_cast<EntityAI>(obj1);
  EntityAI *trans=dyn_cast<EntityAI>(obj2);
  if( !ai || !trans ) return false;

  AIBrain *unit=ai->CommanderUnit();
  if( !unit ) return false; // unit is dead - cannot be in

  return ( unit->GetVehicle()==trans );
}

GameValue ObjAmmo( const GameState *state, GameValuePar oper1, GameValuePar oper2 )
{
  EntityAIFull *ai=dyn_cast<EntityAIFull>(GetObject(oper1));
  if( !ai ) return 0.0f;
  GameStringType weapon=oper2;

  Person *man = dyn_cast<Person>(ai); 
  if(man && man->Brain() && man->Brain()->GetVehicleIn())
  {
    AIBrain *unit = man->Brain();
    if (unit)
    {
      Transport *transport = unit->GetVehicleIn();
      if (transport)
      {
        // TODO: which turret?
        TurretContext context;
        if (transport->FindTurret(man, context))
        {
          // scan all weapons
          float ammo = 0;
          bool found = context._weapons->ForEachMuzzle([&ammo, weapon](const WeaponModePtr &ptr) -> bool
          {
            const Magazine *magazine = ptr.GetMagazine();
            if (!magazine) return false; // continue
            const MuzzleType *muzzle = ptr.GetMuzzleType();
            if (strcmpi(muzzle->GetName(), weapon) != 0) return false; // continue
            ammo = magazine->GetAmmo();
            return true; // done
          });
          if (found) return ammo;
        }
      }
    }
  }
  else
  {
    // TODO: which turret?
    TurretContext context;
    if (ai->GetPrimaryGunnerTurret(context))
    {
      // scan all weapons
      float ammo = 0;
      bool found = context._weapons->ForEachMuzzle([&ammo, weapon](const WeaponModePtr &ptr) -> bool
      {
        const Magazine *magazine = ptr.GetMagazine();
        if (!magazine) return false; // continue
        const MuzzleType *muzzle = ptr.GetMuzzleType();
        if (strcmpi(muzzle->GetName(), weapon) != 0) return false; // continue
        ammo = magazine->GetAmmo();
        return true; // done
      });
      if (found) return ammo;
    }
  }
  return 0.0f;
}

