GameValue SetStackedValue(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  Object *obj = GetObject(oper1);
  if (!obj) return NOTHING;

  if (!CheckType(state, oper2, GameScalar)) return NOTHING;

  obj->SetVariable("quantity",oper2);

  return NOTHING;
}

GameValue AddStackedValue(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{

  Object *obj = GetObject(oper1);
  if (!obj) return 0.0f;
  InventoryItem *item = dyn_cast<InventoryItem>(obj);
  if (!item) return 0.0f;
  if (!CheckType(state, oper2, GameScalar)) return NOTHING;
  
  GameVarSpace *vars = item->GetVars();
  GameValue val;
  vars->VarGet("quantity", val);

  float result = (float)oper2 + (float)val;
  float max = item->Type()->GetStackedMax();

  if (result > max)
  {
	  result = max;
  }
  if (result < 0)
  {
	  result = 0;
  }
  
  obj->SetVariable("quantity",result);

  return GameScalarType(result);
}


