GameValue ObjAddMagazineTurret( const GameState *state, GameValuePar oper1, GameValuePar oper2 )
{
  if (!GetNetworkManager().IsServerOwner())
  {
    state->AccessError("addMagazineTurret");
    return NOTHING;
  }

  Transport *vehicle = dyn_cast<Transport>(GetObject(oper1));
  if (!vehicle) return NOTHING;

  // check the argument
  if(oper2.GetType() != GameArray) return NOTHING;
  const GameArrayType &arrayIn = oper2;
  int n = arrayIn.Size();
  if(n !=2) return NOTHING;

  if (!CheckType(state, arrayIn[0], GameString)) return NOTHING;
  if (!CheckType(state, arrayIn[1], GameArray)) return NOTHING;

  RString magazine = arrayIn[0];
  const GameArrayType &array = arrayIn[1];

  // read the turret path
  TurretPath path;
  int size = array.Size();
  path.Resize(size);
  for (int i=0; i<size; i++) path[i] = toInt((float)array[i]);

  Turret* turret = NULL;
  // find the turret
  if(size == 1 && path[0] == -1)
  {//driver turret
    TurretContext context;
    if(vehicle->GetDriverTurret(context))
    {
      context._weapons->CreateMagazine(vehicle, magazine);
      vehicle->AutoReloadAll(false);
    }
  }
  else turret =  vehicle->GetTurret(path.Data(), path.Size());

  if(turret)
  {
    turret->GetWeapons().CreateMagazine(vehicle, magazine);
    vehicle->AutoReloadAll(false);
  }

  return NOTHING;
}

GameValue ObjRemoveMagazine( const GameState *state, GameValuePar oper1, GameValuePar oper2 )
{
  if (!GetNetworkManager().IsServerOwner())
  {
    state->AccessError("removeMagazine");
    return NOTHING;
  }

  EntityAIFull *veh = dyn_cast<EntityAIFull>(GetObject(oper1));
  if (!veh) return NOTHING;

  TurretContext context;
  if (veh->GetPrimaryGunnerTurret(context))
  {
#if _VBS3
    // Modified command to take, extra paramters, magazine name and ammo size
    if(oper2.GetType() == GameArray)
    {
      const GameArrayType &array = oper2;
      if(array.Size() != 2) return NOTHING;
      if(!CheckType(state,array[0],GameString)) return NOTHING;
      if(!CheckType(state,array[1],GameScalar)) return NOTHING;
      RString magName   = array[0];
      int     ammoCount = toInt((float)array[1]);

      for (int i=0; i<context._weapons->_magazines.Size(); i++)
      {
        Magazine* mag = context._weapons->_magazines[i];
        if(mag && mag->_type && (strcmpi(mag->_type->GetName(),magName)==0))
          if(mag->GetAmmo() == ammoCount)
          {
            context._weapons->RemoveMagazine(veh,mag);
            break;
          }
      }
    }
    else if(oper2.GetType() == GameString)
    {
    GameStringType magazine = oper2;
    context._weapons->RemoveMagazine(veh, magazine);
  }
#else
    GameStringType magazine = oper2;
    context._weapons->DeleteMagazine(veh, magazine);
#endif
  }

  return NOTHING;
}


