/// functor searching for muzzle in all weapon systems
class FireTurretWeapon : public ITurretFunc
{
protected:
  RString _muzzle;
  RString _mode;
  RString _magazine;
#if _VBS3
  Vector3 _position;
#endif
public:
#if _VBS3
  FireTurretWeapon(RString muzzle, RString mode, RString magazine, Vector3 position) 
    : _muzzle(muzzle), _mode(mode), _magazine(magazine), _position(position){}
#else
  FireTurretWeapon(RString muzzle, RString mode, RString magazine) : _muzzle(muzzle), _mode(mode), _magazine(magazine) {}
#endif
  bool operator () (EntityAIFull *entity, TurretContext &context)
  {
    // scan all muzzles
    context._weapons->ForEachWeaponMode([&context, entity, this](const WeaponModePtr &ptr) -> bool
    {
      // check muzzle
      const MuzzleType *muzzle = ptr.GetMuzzleType();
      if (stricmp(muzzle->GetName(), _muzzle) != 0) return false; // continue

      // check mode
      if (_mode.GetLength() > 0)
      {
        const WeaponModeType *modeType = ptr.GetWeaponModeType();
        Assert(modeType);
        if (stricmp(modeType->GetName(), _mode) != 0) return false; // continue
      }

      // muzzle found - return true
      if (_magazine.GetLength() > 0)
      {
        // reload the correct magazine
        Ref<MagazineType> type = dynamic_cast<MagazineType *>(VehicleTypes.New(_magazine));
        Magazine *best = context._weapons->FindBestMagazine(type, 0);
        if (best)
        {
          entity->AttachMagazine(context, muzzle, best);
        }
      }

      const Magazine *magazine = ptr.GetMagazine();
      if (!magazine) return true; // no magazine, done
      if (magazine->Type()->_maxAmmo > 0 && magazine->GetAmmo() == 0) return true; // empty magazine, done

      // fire
      context._weapons->_forceFireWeapon = ptr;
#if _VBS3
      context._weapons->_forceFirePosition = _position;
#endif
      return true; // done
    });

    // not found
    return false; // continue
  }
};

/*!
\patch 5128 Date 2/15/2007 by Jirka
- Fixed: "fire" command works for all turrets now
*/

GameValue ObjFire( const GameState *state, GameValuePar oper1, GameValuePar oper2 )
{
  if (!GetNetworkManager().IsServerOwner())
  {
    state->AccessError("fire");
    return NOTHING;
  }

  Object *obj = GetObject(oper1);
  if (!obj) return NOTHING;
  EntityAIFull *veh = dyn_cast<EntityAIFull>(obj);
  if (!veh) return NOTHING;

  GameStringType muzzle = oper2;
#if _VBS3 //ability to add a position to fire at
  FireTurretWeapon func(muzzle, RString(), RString(),Vector3(0,0,0));
#else
  FireTurretWeapon func(muzzle, RString(), RString());
#endif
  veh->ForEachTurret(func);
  return NOTHING;
}

GameValue ObjFireEx( const GameState *state, GameValuePar oper1, GameValuePar oper2 )
{
  if (!GetNetworkManager().IsServerOwner())
  {
    state->AccessError("fire");
    return NOTHING;
  }

  Object *obj = GetObject(oper1);
  if (!obj) return NOTHING;
  EntityAIFull *veh = dyn_cast<EntityAIFull>(obj);
  if (!veh) return NOTHING;

  const GameArrayType &array = oper2;
  GameStringType muzzle;
  GameStringType mode;
  GameStringType magazine;
#if _VBS3
  Vector3 position(0,0,0);
#endif
  switch (array.Size())
  {
#if _VBS3
  case 4:
    if (!CheckType(state, array[3], GameArray)) return NOTHING;
    {
      const GameArrayType &pos = array[3];
      if(pos.Size()==3)
      {
        position[0] = pos.Get(0); position[1] = pos.Get(2); position[2] = pos.Get(1);
      }     
    }
#endif
  case 3:
    if (!CheckType(state, array[2], GameString)) return NOTHING;
    magazine = array[2];
  case 2:
    if (!CheckType(state, array[1], GameString)) return NOTHING;
    mode = array[1];
  case 1:
    if (!CheckType(state, array[0], GameString)) return NOTHING;
    muzzle = array[0];
    break;
  default:
    state->SetError(EvalDim, array.Size(), 3);
    return NOTHING;
  }
#if _VBS3
  FireTurretWeapon func(muzzle, mode, magazine,position);
#else
  FireTurretWeapon func(muzzle, mode, magazine);
#endif
  veh->ForEachTurret(func);
  return NOTHING;
}

