GameValue CheckAIFeature(const GameState *state, GameValuePar oper1)
{
  RString featureName = oper1;
  AIFeature feature = GetEnumValue<AIFeature>(cc_cast(featureName));
  if (feature!=INT_MIN)
  {
    return Glob.header.CheckAIFeature(feature);
  }
  return false;
}

GameValue EnableAIFeature(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  RString featureName = oper1;
  bool featureState = oper2;
  AIFeature feature = GetEnumValue<AIFeature>(cc_cast(featureName));
  if (feature!=INT_MIN)
  {
    if (featureState)
      Glob.header.EnableAIFeature(feature);
    else
      Glob.header.DisableAIFeature(feature);
  }
  return NOTHING;
}

