GameValue ListPlayers(const GameState *state)
{
  GameValue value = state->CreateGameValue(GameArray);
  GameArrayType &result = value;
    
  if (!GetNetworkManager().IsServer())
  {
    Person *soldier=GWorld->PlayerOn();
    result.Add(GameValueExt(soldier));
    return value;
  }
  else
  {
    AutoArray<NetPlayerInfo> players;
    GetNetworkManager().GetPlayers(players);
    for (int i=0; i<players.Size(); i++)
    {
      if (players[i].person)
      {
        Object *person = dyn_cast<Object,NetworkObject>(players[i].person);
        if (person) result.Add(GameValueExt(person));
      }
    }
    return value;
  }
}



GameValue PlayerOnClient(const GameState *state, GameValuePar oper1)
{
  float clientId = oper1;
  if (GWorld->GetMode() != GModeNetware)
  {
    Person *soldier=GWorld->PlayerOn();
    return GameValueExt(soldier);
  }
  if (!GetNetworkManager().IsServer())
  {
    return GameValueExt(NULL,GameValExtObject);
  }

  const PlayerIdentity *identity = GetNetworkManager().FindIdentityByPlayerId(toInt(clientId));
  if (!identity) return GameValueExt(NULL,GameValExtObject);;

  int dpnid = identity->dpnid;

  NetworkId id = GetNetworkManager().GetPlayerPerson(dpnid);
  NetworkObject *playerNO = GetNetworkManager().GetObject(id);
  Person *playerObj = dyn_cast<Person>(playerNO);
  return GameValueExt(playerObj,GameValExtObject);
}


