GameValue PlayerTarget(const GameState *state, GameValuePar oper1)
{
  if (!GetNetworkManager().IsServer())
  {
    if (GetNetworkManager().IsClient())
    {
      state->AccessError("playerTarget id");
      return OBJECT_NULL;
    }
    else
    {
      // Singleplayer
      return GameValueExt(GWorld->UI()->GetCursorObject());
    }
  }

  int clientId = toInt(safe_cast<float>(oper1));
  const PlayerIdentity *identity = GetNetworkManager().FindIdentityByPlayerId(clientId);
  if (!identity) return OBJECT_NULL;

  int dpnid = identity->dpnid;
  return GameValueExt(GetNetworkManager().GetPlayerTarget(dpnid));
}

