int ListCountSideH( const GameArrayType &array, TargetSide side )
{
  int count=0;
  for( int i=0; i<array.Size(); i++ )
  {
    const GameValue &val=array[i];
    Object *obj=GetObject(val);
    if( !obj ) continue;
    EntityAI *ai=dyn_cast<EntityAI>(obj);
    if( !ai ) continue;
    if( ai->GetTargetSide()==side ) count++;
  }
  return count;
}

int ListCountTypeH( const GameArrayType &array, const EntityType *type )
{
  int count = 0;
  for( int i=0; i<array.Size(); i++ )
  {
    Object *obj = GetObject(array[i]);
    if( !obj ) continue;
    EntityAI *ai=dyn_cast<EntityAI>(obj);
    if( !ai ) continue;

    if( ai->GetType()->IsKindOf(type) ) count++;
  }
  return count;
}


GameValue ListCountSide( const GameState *state, GameValuePar oper1, GameValuePar oper2 )
{
  return (float)ListCountSideH(oper2,GetSide(oper1));
}

GameValue ListCountType( const GameState *state, GameValuePar oper1, GameValuePar oper2 )
{
  RString name=oper1;
  Ref<const EntityType> type=VehicleTypes.New(name);
  return (float)ListCountTypeH((const GameArrayType&)oper2,type);
}

GameValue ObjIsKindOf( const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  // access the type
  Object *obj = GetObject(oper1);
  ObjectTyped *objTyped = dyn_cast<ObjectTyped>(obj);
  if (!objTyped) return false;
  const EntityType *type = objTyped->Type();
  if (!type) return false;

  ConstParamEntryPtr entry = type->GetParamEntry();

  // check the chain of parents
  RString name = oper2;
  while (entry)
  {
    if (stricmp(entry->GetName(), name) == 0) return true; // found
    entry = entry->FindBase();
  }

  // not found
  return false; 
}

GameValue TypeIsKindOf(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  RString typeName1 = oper1;

  // find the config class
  ConstParamEntryPtr entry = (Pars >> "CfgVehicles").FindEntry(typeName1);
  if (!entry) entry = (Pars >> "CfgAmmo").FindEntry(typeName1);
  if (!entry) entry = (Pars >> "CfgNonAIVehicles").FindEntry(typeName1);

  // check the chain of parents
  RString typeName2 = oper2;
  while (entry)
  {
    if (stricmp(entry->GetName(), typeName2) == 0) return true; // found
    entry = entry->FindBase();
  }
  
  // not found
  return false; 
}

GameValue TypeSizeOf(const GameState *state, GameValuePar oper1)
{
  RString typeName = oper1;
  Ref<const EntityType> type = VehicleTypes.New(typeName);
  if (!type) return 0.0f;

  LODShape *shape = type->GetShape();
  if (!shape) return 0.0f;

  return 2.0f * shape->BoundingSphere();
}

