static bool GetPosATL(const GameState *state, Vector3 &ret, GameValuePar oper)
{
  const GameArrayType &array = oper;
  float x, y = 0, z;
  switch (array.Size())
  {
  case 3:
    if (array[2].GetType() != GameScalar)
    {
      if (state) state->TypeError(GameScalar, array[2].GetType());
      return false;
    }
    y = array[2];
    // continue;
  case 2:
    if (array[0].GetType() != GameScalar)
    {
      if (state) state->TypeError(GameScalar, array[0].GetType());
      return false;
    }
    if (array[1].GetType() != GameScalar)
    {
      if (state) state->TypeError(GameScalar, array[1].GetType());
      return false;
    }
    x = array[0];
    z = array[1];
    break;
  default:
    if (state) state->SetError(EvalDim, array.Size(), 3);
    return false;
  }

  ret = Vector3(x, y, z);
  ret[1] += GLandscape->SurfaceY(ret);

  return true;  
}


static bool GetRelPos( const GameState *state, Vector3 &ret, GameValuePar oper )
{
  Object *obj = GetObject(oper);
  if (obj)
  {
    ret = obj->FutureVisualState().Position();
    // convert to relative position?
    ret[1] -= GLandscape->SurfaceYAboveWater(ret.X(),ret.Z());
    return true;
  }
  if (!CheckType(state,oper,GameArray))
  {
    return false;
  }
  const GameArrayType &array = oper;
  if (array.Size() < 2 || array.Size() > 3)
  {
    if (state) state->SetError(EvalDim,array.Size(),3);
    return false;
  }
  if (array[0].GetType() != GameScalar)
  {
    if (state) state->TypeError(GameScalar,array[0].GetType());
    return false;
  }
  if (array[1].GetType() != GameScalar)
  {
    if (state) state->TypeError(GameScalar,array[1].GetType());
    return false;
  }

  float x = array[0];
  float z = array[1];
  float y = 0;
  if (array.Size()==3)
  {
    if (array[2].GetType() != GameScalar)
    {
      if (state) state->TypeError(GameScalar,array[2].GetType());
      return false;
    }
    y=array[2];
  }
  ret = Vector3(x,y,z);
  return true;
}

bool GetPos( const GameState *state, Vector3 &ret, GameValuePar oper )
{
  Vector3 rel;
  bool ok = GetRelPos(state,rel,oper);
  if (!ok) return ok;
  rel[1] += GLandscape->SurfaceYAboveWater(rel.X(),rel.Z());
  ret = rel;
  return true;  
}

bool GetPos(Vector3 &ret, GameValuePar oper)
{
  return GetPos(NULL,ret,oper);
}

GameValue FindEmptyAreaReady(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  // center
  Vector3 center;
  if (!GetPos(state, center, oper1)) return true;

  // [radius, maxDistance]
  const GameArrayType &array = oper2;
  if (!CheckSize(state, array, 2)) return true;
  // radius
  if (!CheckType(state, array[0], GameScalar)) return true;
  float radius = array[0];
  // maxDistance
  if (!CheckType(state, array[1], GameScalar)) return true;
  float maxDistance = array[1];

  return OperMap::FindEmptyAreaReady(center, radius, maxDistance);
}

GameValue FindEmptyArea(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  // value to return
  GameValue value = state->CreateGameValue(GameArray);

  // center
  Vector3 center;
  if (!GetPos(state, center, oper1)) return value;

  // [radius, maxDistance] or [radius, maxDistance, vehicleType]
  const GameArrayType &array = oper2;
  Ref<const EntityAIType> vehType;
  if (array.Size() == 3)
  {
    // vehicleType
    if (array[2].GetType() != GameString)
    {
      state->TypeError(GameString, array[2].GetType());
      return value;
    }
    RString typeName = array[2];
    vehType = dynamic_cast<const EntityAIType *>(VehicleTypes.New(typeName));
  }
  else if (array.Size() == 2)
  {
    // by default vehicleType == PaperCar
    vehType = GWorld->Preloaded(VTypePaperCar);
  }
  else
  {
    state->SetError(EvalDim, array.Size(), 3);
    return value;
  }
  if (!vehType) return value;
  // radius
  if (!CheckType(state, array[0], GameScalar)) return true;
  float radius = array[0];
  // maxDistance
  if (!CheckType(state, array[1], GameScalar)) return true;
  float maxDistance = array[1];

  if (!AIBrain::FindEmptyArea(center, radius, maxDistance, vehType)) return value;
  // area found
  GameArrayType &result = value;
  result.Realloc(3);
  result.Resize(3);
  result[0] = center.X();
  result[1] = center.Z();
  result[2] = 0.0f;
  return value;
}
 
class CollectNearTargets : public TargetFunctor
{
protected:
  const GameState *_state;
  GameArrayType &_result;
  AIBrain *_source;
  Vector3 _center;
  float _radius2;

public:
  CollectNearTargets(const GameState *state, GameArrayType &result, AIBrain *source, float radius)
    : _state(state), _result(result), _source(source), _radius2(Square(radius))
  {
    _center = _source->Position(_source->GetFutureVisualState());
  }
  // return true to break enumeration
  virtual bool operator ()(Target *target) const
  {
    // filter only interesting targets
    if (target->IsVanishedOrDestroyed()) return false; // continue
    if (!target->IsKnownBy(_source)) return false; // continue
    if (target->idExact == _source->GetVehicleIn() || target->idExact == _source->GetPerson()) return false; // continue
    Vector3 pos = target->LandAimingPosition(_source);
    float dist2 = _center.Distance2(pos);
    if (dist2 >= _radius2) return false; // continue

    // add the target as [position, type, side, subj. cost, object]
    GameArrayType &array = _result.Append(_state->CreateGameValue(GameArray));
    array.Realloc(6);
    array.Resize(6);
    // position
    array[0] = _state->CreateGameValue(GameArray);
    GameArrayType &position = array[0];
    position.Realloc(3);
    position.Resize(3);
    position[0] = pos.X();
    position[1] = pos.Z();
    position[2] = pos.Y() - GLandscape->SurfaceYAboveWater(pos.X(), pos.Z());
    // type
    const EntityAIType *type = target->GetType();
    array[1] = type ? type->GetName() : RString();
    // side
    array[2] = GameValueExt(target->GetSide());
    // subjective cost
    array[3] = target->GetSubjectiveCost();
    // object itself
    array[4] = GameValueExt(target->idExact, GameValExtObject);
    // position precision
    array[5] = target->FadingPosAccuracy();

    return false; // collect all
  }
};

GameValue ObjNearTargets(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  // value to return
  GameValue value = state->CreateGameValue(GameArray);

  // find the target list source
  Object *obj = GetObject(oper1);
  EntityAI *veh = dyn_cast<EntityAI>(obj);
  if (!veh) return value;
  AIBrain *unit = veh->CommanderUnit();
  if (!unit) return value;

  // collect targets
  CollectNearTargets func(state, value, unit, oper2);
  unit->ForEachTarget(func);
  return value;
}

static AIBrain *GetUnit( const GameState *state, GameValuePar oper1 )
{
  Object *obj = GetObject(oper1);
  EntityAI *veh = dyn_cast<EntityAI>(obj);
  if (!veh) return NULL;
  return veh->CommanderUnit();
}

GameValue VehReveal(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  AIBrain *brain = GetUnit(state, oper1);
  if (!brain) return NOTHING;
  EntityAI *veh = NULL;
  float accuracy = 1.0f;
  if (oper2.GetType() == GameObject)
  {
    veh = dyn_cast<EntityAI>(GetObject(oper2));
  }
  else if (oper2.GetType() == GameArray)
  {
    const GameArrayType &array = oper2;
    int n = array.Size();
    if (n != 2)
    {
      state->SetError(EvalDim, array.Size(), 2);
      return NOTHING;
    }

    // create action based on type
    if (!CheckType(state, array[0], GameObject)) return NOTHING;
    if (!CheckType(state, array[1], GameScalar)) return NOTHING;
    veh = dyn_cast<EntityAI>(GetObject(array[0]));
    accuracy = array[1];
    saturate(accuracy,0,4);
  }
  if (veh) brain->AddTarget(veh,accuracy,accuracy,0);
  return NOTHING;
}

/// cutscene style look or glance
static GameValue DoVehLook(const GameState *state, GameValuePar oper1, GameValuePar oper2, bool glanceOnly)
{
  Object *obj = static_cast<GameDataObject *>(oper1.GetData())->GetObject();
  EntityAI *vai = dyn_cast<EntityAI>(obj);
  if (!vai) return NOTHING;
  
  AIBrain *unit = vai->CommanderUnit();
  if (!unit) return NOTHING;

  Vector3 pos;
  Target *tgt = NULL;
  bool noTgt = false;
  if (oper2.GetType() == GameObject)
  {
    obj = GetObject(oper2);
    if (!obj) noTgt = true;
    else
    {
      EntityAI *veh = dyn_cast<EntityAI>(obj);
      if (!veh) pos = obj->FutureVisualState().Position();
      else
      {
        /// reveal target with maximum accuracy
        tgt = unit->AddTarget(veh,4.0f,4.0f,0);
        if (!tgt) pos = obj->FutureVisualState().Position();
      }
    }
  }
  else if (!GetPos(state,pos,oper2))
  {
    return NOTHING;
  }
  
  if (tgt || noTgt)
  {
    unit->SetWatchTarget(tgt, glanceOnly);
  }
  else
  {
    unit->SetWatchPosition(pos, glanceOnly);
  }
 
  return NOTHING;
}

static GameValue VehGlanceAt( const GameState *state, GameValuePar oper1, GameValuePar oper2 )
{
  return DoVehLook(state,oper1,oper2,true);
}

static GameValue VehLookAt( const GameState *state, GameValuePar oper1, GameValuePar oper2 )
{
  return DoVehLook(state,oper1,oper2,false);
}

GameValue VehProcessAction( const GameState *state, GameValuePar oper1, GameValuePar oper2 )
{
  EntityAI *veh = dyn_cast<EntityAI>(GetObject(oper1));
  if (!veh) return NOTHING;
  AIBrain *agent = veh->CommanderUnit();
  if (!agent) return NOTHING;

  const GameArrayType &array = oper2;
  int n = array.Size();
  if (n == 1)
  {
    state->SetError(EvalDim, array.Size(), 2);
    return NOTHING;
  }

  // create action based on type
  if (!CheckType(state, array[0], GameString)) return NOTHING;
  RString typeName = array[0];
  UIActionType type = GetEnumValue<UIActionType>(cc_cast(typeName));
  if (type == INT_MIN) return NOTHING;
  Ref<Action> action = CreateAction(type);
  if (!action) return NOTHING;

  // target
  if (n == 1)
    action->SetTarget(veh);
  else
    action->SetTarget(dyn_cast<TargetType>(GetObject(array[1])));

  // additional parameters
  if (n > 2)
  {
    if (!action->SetParams(state, oper2)) return NOTHING;
  }

  veh->StartActionProcessing(action, agent);
  return NOTHING;
}

GameValue VehAddUserAction( const GameState *state, GameValuePar oper1, GameValuePar oper2 )
{
  EntityAI *veh = dyn_cast<EntityAI>(GetObject(oper1));
  if (!veh) return -1.0f;

  const GameArrayType &array = oper2;
  GameValue param;

  // read the default values
  const UIActionTypeDesc &desc = UIActions::actionTypes[ATUser];
  float priority = desc.priority;
  bool showWindow = desc.showWindow;
  bool hideOnUse = desc.hideOnUse;
  UserAction shortcut = desc.shortcut;
  RString condition;

#if _HELISIM_PRECISE_INTERACTION
  RString positionInModel;
  float radius = -1;
  float radiusView = -1;
  int showIn3D = 0; 
  int available  = 0;
  RString textDefault;
  RString textToolTip;
#endif

  switch (array.Size())
  {
#if _HELISIM_PRECISE_INTERACTION
  case 15:
    if (!CheckType(state, array[14], GameString)) return -1.0f;
    textToolTip = array[14];
  case 14:
    if (!CheckType(state, array[13], GameString)) return -1.0f;
    textDefault = array[13];
  case 13:
    if (!CheckType(state, array[12], GameScalar)) return -1.0f;
    available = toInt((float)array[12]);
  case 12:
    if (!CheckType(state, array[11], GameScalar)) return -1.0f;
    showIn3D = toInt((float)array[11]);
  case 11:
    if (!CheckType(state, array[10], GameScalar)) return -1.0f;
    radiusView = array[10];
  case 10:
    if (!CheckType(state, array[9], GameScalar)) return -1.0f;
    radius = array[9];
  case 9:
    if (!CheckType(state, array[8], GameString)) return -1.0f;
    positionInModel = array[8];
#endif
  case 8:
    if (!CheckType(state, array[7], GameString)) return -1.0f;
    condition = array[7];
    // continue
  case 7:
    if (!CheckType(state, array[6], GameString)) return -1.0f;
    {
      RString name = array[6];
      if (name.GetLength() > 0) 
      {
        for (int i=0; i<UAN; i++)
        {
          if (stricmp(name, Input::userActionDesc[i].name) == 0)
          {
            shortcut = (UserAction)i;
            break;
          }
        }
      }
    }
    // continue
  case 6:
    if (!CheckType(state, array[5], GameBool)) return -1.0f;
    hideOnUse = array[5];
    // continuetrue
  case 5:
    if (!CheckType(state, array[4], GameBool)) return -1.0f;
    showWindow = array[4];
    // continue
  case 4:
    if (!CheckType(state, array[3], GameScalar)) return -1.0f;
    priority = array[3];
    // continue
  case 3:
    param = array[2];
    // continue
  case 2:
    if (array[0].GetType() != GameString)
    {
      state->TypeError(GameString, array[0].GetType());
      return -1.0f;
    }
    if (array[1].GetType() != GameString)
    {
      state->TypeError(GameString, array[1].GetType());
      return -1.0f;
    }
    break;
  default:
    state->SetError(EvalDim,array.Size(),3);
    return -1.0f;
  }

#if _HELISIM_PRECISE_INTERACTION
  if(textDefault.GetLength() <=0) textDefault = array[0];

  return (float)veh->AddUserAction(array[0], array[1], param, priority, showWindow, hideOnUse, shortcut, condition,
    positionInModel, radius, radiusView, showIn3D, available,  textDefault, textToolTip);
#else
  return (float)veh->AddUserAction(array[0], array[1], param, priority, showWindow, hideOnUse, shortcut, condition);
#endif
}

GameValue VehSetUserActionText( const GameState *state, GameValuePar oper1, GameValuePar oper2 )
{

  EntityAI *veh = dyn_cast<EntityAI>(GetObject(oper1));
  if (!veh) return -1.0f;

  const GameArrayType &array = oper2;
  GameValue param;

  if (array.Size() < 2)
  {
    state->SetError(EvalDim,array.Size(),2);
    return NOTHING;
  }
  if (array[0].GetType() != GameScalar)
  {
    state->TypeError(GameString, array[0].GetType());
    return NOTHING;
  }
  if (array[1].GetType() != GameString)
  {
    state->TypeError(GameString, array[1].GetType());
    return NOTHING;
  }

  int actionIndex = toInt((float)array[0]);
  RString text = array[1];

#if _HELISIM_PRECISE_INTERACTION
  RString textDefault = text;
  RString textToolTip = text;

  if (array.Size() > 2)
  {
    if (array[2].GetType() != GameString)
    {
      state->TypeError(GameString, array[2].GetType());
      return NOTHING;
    }
    textDefault = array[2];
  }

  if (array.Size() > 3)
  {
    if (array[3].GetType() != GameString)
    {
      state->TypeError(GameString, array[3].GetType());
      return NOTHING;
    }
    textToolTip = array[3];
  }

  veh->SetUserActionText(actionIndex, text, textDefault, textToolTip);
#else
  veh->SetUserActionText(actionIndex, text);
#endif

  return NOTHING;
}

