GameValue ObjGetProxyFromSelection( const GameState *state, GameValuePar oper1, GameValuePar oper2 )
{
  GameValue value = state->CreateGameValue(GameArray);
  GameArrayType &retArray = value;
  Object *obj1 = GetObject(oper1);
  if (!obj1) return value;
  GameStringType selName = oper2;
  LODShape *lShape = obj1->GetShape();
  if (!lShape) return value;
  const Shape *memory = lShape->MemoryLevel();
  if (!memory) return value;
  int selIndex = memory->FindNamedSel(selName);
  if (selIndex < 0) return value;
  // grab the selection and find a proxy in it
  const NamedSelection::Access &sel = memory->NamedSel(selIndex,lShape);
  for (int fi=0; fi<sel.Faces().Size(); fi++)
  {
    VertexIndex fSel = sel.Faces()[fi];
    // find a proxy containing this particular face
    for (int pi=0; pi<memory->NProxies(); pi++)
    {
      const ProxyObject &proxy = memory->Proxy(pi);
      const NamedSelection::Access &proxySel = memory->NamedSel(proxy.selection,lShape);
      if (proxySel.Faces().Size()==1) // proxy should always be one face
      {
        VertexIndex pSel = proxySel.Faces()[0];
        if (fSel==pSel)
        {
          GameValue value = state->CreateGameValue(GameArray);
          GameArrayType &array = value;

          array.Resize(5);
          array[0] = proxy.name;
          array[1] = safe_cast<float>(proxy.id);
          Matrix4 worldTrans = obj1->FutureVisualState().ModelToWorld()*proxy.GetTransform();
          array[2] = CreateGameVectorXZY(state,worldTrans.Position());
          array[3] = CreateGameVectorXZY(state,worldTrans.Direction());
          array[4] = CreateGameVectorXZY(state,worldTrans.DirectionUp());
          retArray.Add(array);
        }
      }
    }
  }

  return value;
}

