GameValue ObjRequestDamage(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  /*
  ExplosionDamageEffectsMessage:
  XX(MessageName, OLinkPermO(EntityAI), owner, NDTRef, NetworkId,  NCTNone, DEFVALUENULL, DOC_MSG("Shot owner (who is responsible for explosion)"), TRANSF_REF) \
  XX(MessageName, OLink(Object), directHit, NDTRef, NetworkId,  NCTNone, DEFVALUENULL, DOC_MSG("Hit object"), TRANSF_REF) \
  XX(MessageName, int, componentIndex, NDTInteger, int, NCTNone, DEFVALUE(int, -1), DOC_MSG("Index of hit convex component"), TRANSF) \
  XX(MessageName, RString, type, NDTString, RString, NCTDefault, DEFVALUE(RString, ""), DOC_MSG("Ammunition type"), TRANSF) \
  XX(MessageName, Vector3, pos, NDTVector, Vector3, NCTNone, DEFVALUE(Vector3, VZero), DOC_MSG("Explosion position"), TRANSF) \
  XX(MessageName, Vector3, surfNormal, NDTVector, Vector3, NCTNone, DEFVALUE(Vector3, VUp), DOC_MSG("Surface normal at the explosion"), TRANSF) \
  XX(MessageName, Vector3, inSpeed, NDTVector, Vector3, NCTNone, DEFVALUE(Vector3, VZero), DOC_MSG("Speed of the corresponding bullet/shell/missile"), TRANSF) \
  XX(MessageName, Vector3, outSpeed, NDTVector, Vector3, NCTNone, DEFVALUE(Vector3, VZero), DOC_MSG("Result speed (if any)"), TRANSF) \
  XX(MessageName, bool, enemyDamage, NDTBool, bool, NCTNone, DEFVALUE(bool, false), DOC_MSG("Some enemy was damaged"), TRANSF) \
  XX(MessageName, float, energyFactor, NDTFloat, float, NCTFloatMostly0To1, DEFVALUE(float, 1), DOC_MSG("Energy coefficient for distant hits"), TRANSF) \
  XX(MessageName, float, explosionFactor, NDTFloat, float, NCTFloat0To1, DEFVALUE(float, 0), DOC_MSG("How large explosion is"), TRANSF)
  */
  Object *directHit = GetObject(oper1);

  const GameArrayType &array = oper2;
  if (!CheckSize(state,array,4)) return NOTHING;

  if (!CheckType(state,array[0],GameObject)) return NOTHING;
  EntityAI *owner = dyn_cast<EntityAI>(GetObject(array[0]));

  Vector3 pos;
  if (!GetVector(state,pos,array[1])) return NOTHING;

  if (!CheckType(state,array[2],GameString)) return NOTHING;
  Ref<EntityType> type = VehicleTypes.New(array[2]);
  AmmoType *ammo = dynamic_cast<AmmoType *>(type.GetRef());
  if (!ammo) return NOTHING;

  if (!CheckType(state,array[3],GameScalar)) return NOTHING;
  int component = toInt(array[3]);
  int componentIndex = -1;
  if (directHit)
  {

    LODShape *hitShape = directHit->GetShape();
    if (hitShape)
    {
      const Shape *fireGeom = hitShape->FireGeometryLevel();
      if (fireGeom)
      {
        const ConvexComponents &fireCc = hitShape->GetFireComponents();
        componentIndex = fireCc.FindNameIndex(component);
      }
    }
  }

  HitInfo hitInfo(ammo,pos,VUp,VZero);

  // provide reasonable default values where we do not expect the script to be interested in them
  float energyFactor = 1.0f;
  float explosionFactor = 1.0f;
  Vector3 originDir = VZero;

  Vector3 directHitModelPos = directHit ? directHit->RenderVisualState().GetInvTransform().FastTransform(pos) : VZero;
  // TODO: more direct interface to create ExplosionDamageEffectsMessage
  GLandscape->ExplosionDamage(owner,originDir,directHit,directHitModelPos,hitInfo,directHit,componentIndex,energyFactor,explosionFactor);
  return NOTHING;
}


GameValue ObjSetHit(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  Object *obj = GetObject(oper1);
  EntityAI *veh = dyn_cast<EntityAI>(obj);
  if (!veh) return NOTHING;

  const GameArrayType &array = oper2;
  if (array.Size() != 2)
  {
    state->SetError(EvalDim, array.Size(), 2);
    return NOTHING;
  }
  if (array[0].GetType() != GameString)
  {
    state->TypeError(GameString, array[0].GetType());
    return NOTHING;
  }
  if (array[1].GetType() != GameScalar)
  {
    state->TypeError(GameScalar, array[1].GetType());
    return NOTHING;
  }

  RString part = array[0];
  const HitPointList &list = veh->GetType()->GetHitPoints();
  const Shape *shape = veh->GetShape()->HitpointsLevel();
  if (!shape) return NOTHING;
  int sel = veh->GetShape()->FindNamedSel(shape,part, NULL);
  if (sel < 0) return NOTHING;

  int index = -1;
  for (int i=0; i<list.Size(); i++)
  {
    if (list[i].GetSelection() == sel)
    {
      index = i;
      break;
    }
  }
  if (index < 0) return NOTHING;

  bool oldDestroyed = veh->IsDamageDestroyed();

  // similar to EntityAI::ApplyDoDamageLocal
  float damage = array[1];
  veh->ChangeHit(NULL, index, damage);

  // give opportunity to set isDead flag
  veh->ReactToDamage();

  // check if we died meanwhile  
  if( !oldDestroyed && veh->IsDamageDestroyed() )
  {
    // can be never destroy
    //Assert( !!IsDestroyed() );
    veh->Destroy(veh,veh->GetRawTotalDamage(),0.05,0.1);
  }

  return NOTHING;
}

GameValue ObjSetHitPointDamage(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  Object *obj = GetObject(oper1);
  EntityAI *veh = dyn_cast<EntityAI>(obj);
  if (!veh) return NOTHING;

  const GameArrayType &array = oper2;
  if (array.Size() != 2)
  {
    state->SetError(EvalDim, array.Size(), 2);
    return NOTHING;
  }
  if (array[0].GetType() != GameString)
  {
    state->TypeError(GameString, array[0].GetType());
    return NOTHING;
  }
  if (array[1].GetType() != GameScalar)
  {
    state->TypeError(GameScalar, array[1].GetType());
    return NOTHING;
  }

  RString part = array[0];
  const HitPointList &list = veh->GetType()->GetHitPoints();

  int index = -1;
  for (int i=0; i<list.Size(); i++)
  {
    if (strcmpi(list[i].GetName(), part) == 0)
    {
      index = i;
      break;
    }
  }
  if (index < 0) return NOTHING;

  bool oldDestroyed = veh->IsDamageDestroyed();

  // similar to EntityAI::ApplyDoDamageLocal
  float damage = array[1];
  veh->ChangeHit(NULL, index, damage);

  // give opportunity to set isDead flag
  veh->ReactToDamage();

  // check if we died meanwhile  
  if( !oldDestroyed && veh->IsDamageDestroyed() )
  {
    // can be never destroy
    //Assert( !!IsDestroyed() );
    veh->Destroy(veh,veh->GetRawTotalDamage(),0.05,0.1);
  }

  return NOTHING;
}

