ConstParamEntryPtr FindIdentity(RString name)
{
  // find in mission
  ConstParamEntryPtr cls = ExtParsMission.FindEntry("CfgIdentities");
  ConstParamEntryPtr entry = cls ? ConstParamEntryPtr(cls->FindEntry(name)) : ConstParamEntryPtr();
  if (entry) return entry;
  
  // find in the config
  cls = Pars.FindEntry("CfgIdentities");
  entry = cls ? ConstParamEntryPtr(cls->FindEntry(name)) : ConstParamEntryPtr();
  return entry;
}

GameValue ObjSetIdentity( const GameState *state, GameValuePar oper1, GameValuePar oper2 )
{
  Object *obj = GetObject(oper1);
  if (!obj) return NOTHING;

  VehicleWithBrain *person = dyn_cast<VehicleWithBrain>(obj);
  if (!person) return NOTHING;

  GameStringType name = oper2;
  ConstParamEntryPtr entry = FindIdentity(name);
  if (entry)
  {
    // avoid identity overwrite when delay EH processed
    if (person->Brain()) person->Brain()->LoadIdentityDelayed();

    AIUnitInfo &info = person->GetInfo();
    info._fullName = (*entry) >> "name";
    info._face = (*entry) >> "face";
    info._glasses = (*entry) >> "glasses";
    info._speaker = (*entry) >> "speaker";
    info._pitch = (*entry) >> "pitch";

    person->SetFace(info._face);
    person->SetGlasses(info._glasses);
    if (person->Brain()) person->Brain()->SetSpeaker(info._speaker, info._pitch);
  }
  
  return NOTHING;
}

