static GameValue ObjSay2D3D( const GameState *state, GameValuePar oper1, GameValuePar oper2, bool pos3D)
{
  // left side argument(s)
  Object *from = NULL;
  Object *to = NULL;
  if (oper1.GetType() == GameObject)
  {
    from = GetObject(oper1);
  }
  else
  {
    Assert(oper1.GetType() == GameArray);
    const GameArrayType &array = oper1;
    if (!CheckSize(state, array, 2)) return NOTHING;
    if (!CheckType(state, array[0], GameObject)) return NOTHING;
    if (!CheckType(state, array[1], GameObject)) return NOTHING;
    from = GetObject(array[0]);
    to = GetObject(array[1]);
  }

  // right side argument(s)
  GameStringType voice;
  float distance = 100.0f;
  float speed = 1.0f;
  if (oper2.GetType() == GameString)
    voice = oper2;
  else
  {
    Assert(oper2.GetType() == GameArray);
    const GameArrayType &array = oper2;

    switch (array.Size())
    {
    case 3:
      if (array[2].GetType() != GameScalar)
      {
        state->TypeError(GameScalar, array[2].GetType());
        return NOTHING;
      }
      speed = array[2];

    case 2:
      if (array[1].GetType() != GameScalar)
      {
        state->TypeError(GameScalar, array[1].GetType());
        return NOTHING;
      }
      distance = array[1];

      if (array[0].GetType() != GameString)
      {
        state->TypeError(GameString, array[0].GetType());
        return NOTHING;
      }
      voice = array[0];
      break;
    default:
      state->SetError(EvalDim, array.Size(), 2);
      return NOTHING;
    }

  }

  if (!from) return NOTHING;
  if (from->IsDamageDestroyed()) return NOTHING;

  //LogF("%s: Say %s",cc_cast(obj1->GetDebugName()),cc_cast(voice));
  Vehicle *veh = new SoundOnVehicle(voice, from, pos3D, distance, speed, to);
  veh->SetPosition(from->FutureVisualState().Position());
  GWorld->AddSlowVehicle(veh);
  if (pos3D)
  {
    GetNetworkManager().CreateVehicle(veh, VLTSlowVehicle, RString(), -1);
  }

  return NOTHING;
}

