GameValue WeaponReloadingTime(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  bool done = false;

  EntityAIFull *veh = NULL;
  RString muzzleName;
  float reloadTime = 0;

  //vehicle
  if (oper1.GetType() != GameObject)
  {
    if (state) state->TypeError(GameObject,oper1.GetType());
    return done;
  }
  Object *obj = GetObject(oper1);
  veh = dyn_cast<EntityAIFull>(obj);
  if(!veh) return done;

  //gunner, weapon, time
  if (oper2.GetType() != GameArray)
  {
    if (state) state->TypeError(GameArray,oper2.GetType());
    return done;
  }

  const GameArrayType &inArray = oper2;
  if ((inArray.Size() != 3))
  {
    if (state) state->SetError(EvalDim,inArray.Size(),3);
    return done;
  }

  // gunner 
  if (inArray[0].GetType() != GameObject)
  {
    if (state) state->TypeError(GameObject,inArray[0].GetType());
    return done;
  }
  Person *gunner = dyn_cast<Person>(GetObject(inArray[0]));
  if(!gunner) return done;

  //weapon
  if (inArray[1].GetType() != GameString)
  {
    if (state) state->TypeError(GameString,inArray[1].GetType());
    return done;
  }
  muzzleName = inArray[1];

  //reload time
  if (inArray[2].GetType() != GameScalar)
  {
    if (state) state->TypeError(GameScalar,inArray[2].GetType());
    return done;
  }
  reloadTime = inArray[2];

  if (veh)
  {
    done = veh->SetWeaponReloadTime(gunner, muzzleName, reloadTime);
  }

  return done;
}

GameValue ObjGetWeaponState(const GameState *state, GameValuePar oper1)
{
  // We can probably query a empty gunner seat turret.
  Person *person = NULL;
  Turret *turret = NULL;
  Transport *veh = NULL;


  if (oper1.GetType()==GameObject)
  {
    Object *object = GetObject(oper1);
    if (!object) return NOTHING;

    person = dyn_cast<Person>(object);
    if (!person) return NOTHING;
  }
  else if (oper1.GetType()==GameArray)
  {
    // Need the vehicle and the turret path
    if (!CheckSize(state,oper1,2)) return NOTHING;

    const GameArrayType &array = oper1;
    if (!CheckType(state,array[0],GameObject)) return NOTHING;
    if (!CheckType(state,array[1],GameArray)) return NOTHING;

    veh = dyn_cast<Transport>(GetObject(array[0]));
    if (!veh) return NOTHING;

    const GameArrayType &turretPath = array[1];
    for(int i=0; i<turretPath.Size(); i++)
      if (!CheckType(state, turretPath[i], GameScalar)) return NOTHING;

    // Get the path
    TurretPath path;
    path.Resize(turretPath.Size());
    for (int i=0; i<turretPath.Size(); i++) path[i] = toInt((float)turretPath[i]);

    turret = veh->GetTurret(path.Data(), path.Size());
    if (!turret) return NOTHING;
  }
  else
  {
    state->TypeError(GameArray, oper1.GetType());
    return NOTHING;
  }


  TurretContext context;
  memset(&context,0,sizeof(context));

  bool allOk = false;
  if (person) allOk = person->GetPrimaryGunnerTurret(context);
  else if(turret) allOk = veh->FindTurret(turret,context);

  if (allOk && context._weapons)
  {
    RString weaponName;
    RString muzzleName;
    RString modeName;
    RString magazineName;
    int magazineAmmo = 0;
#if 0//_VBS3_WEAPONSTATE_CMD_NEXTROUND
    //name of magazine of the round that will be loaded after currently loaded round is fired
    RString nextRoundName;
#endif

    WeaponModePtr ptr = context._weapons->ValidatedCurrentWeapon();
    if (ptr.IsValid())
    {          
      const WeaponType *weapon = ptr.GetWeaponType();
      if (weapon) weaponName = weapon->GetName();
      const MuzzleType *muzzle = ptr.GetMuzzleType();
      if (muzzle) muzzleName = muzzle->GetName();
      const WeaponModeType *mode = ptr.GetWeaponModeType();
      if (mode) modeName = mode->GetName();
      const Magazine *magazine = ptr.GetMagazine();
      if (magazine && magazine->Type()) magazineName = magazine->Type()->GetName();
      if (magazine) magazineAmmo = magazine->GetAmmo();
#if 0 //_VBS3_WEAPONSTATE_CMD_NEXTROUND
      if (slot._preparedMagazine != -1)
      {
        const Ref<Magazine> magazine = context._weapons->_magazines[slot._preparedMagazine]; 
        if (magazine && magazine->Type())
          nextRoundName = magazine->Type()->GetName();
      }
      else
        nextRoundName = magazineName;
#endif
    }

    GameArrayType retArray;
    retArray.Add(weaponName);
    retArray.Add(muzzleName);
    retArray.Add(modeName);
    retArray.Add(magazineName);
    retArray.Add(float(magazineAmmo));
#if 0 //_VBS3_WEAPONSTATE_CMD_NEXTROUND
    retArray.Add(nextRoundName);
#endif

    return retArray;     
  }

  return NOTHING;
}

GameValue LoadMag( const GameState *state, GameValuePar oper1, GameValuePar oper2 )
{
  Object* obj = GetObject(oper1);
  Transport *tran = dyn_cast<Transport>(obj);
  if(!tran) return NOTHING;

  const GameArrayType &array = oper2;
  if(array.Size() == 3)
  {
    const GameArrayType &turretPath = array[0];
    int n = turretPath.Size();
    RString muzzleName = array[1];
    RString magazineName = array[2];
    if(!n || !muzzleName.GetLength()) return NOTHING;
    for (int i=0; i<n; i++)
      if (!CheckType(state, turretPath[i], GameScalar)) return NOTHING;
    TurretPath path;
    path.Resize(n);
    for (int i=0; i<n; i++) path[i] = toInt((float)turretPath[i]);
    Turret *turret = tran->GetTurret(path.Data(), path.Size());
    if (!turret) return NOTHING;
    TurretContext context;
    tran->FindTurret(turret,context);

    context._weapons->ForEachMuzzle([&context, tran, muzzleName, magazineName](const WeaponModePtr &ptr) -> bool
    {
      const MuzzleType *muzzle = ptr.GetMuzzleType();
      if (muzzle && stricmp(muzzle->GetName(), muzzleName) == 0)
      {
        // in nested lambdas, recapture is needed (to avoid error C3480)
        TurretContext &contextNested = context;
        Transport *tranNested = tran;
        RString magazineNameNested = magazineName;
        return context._weapons->ForEachMagazine([&contextNested, tranNested, magazineNameNested, &ptr](Magazine *mag) -> bool
        {
          if (mag->Type() && stricmp(mag->Type()->GetName(), magazineNameNested) == 0)
          {
            if (contextNested._gunner)
            {
              tranNested->ReloadMagazine(*contextNested._weapons, ptr, mag);
            }
            return true; // done
          }
          return false; // continue
        });
      }
      return false; // continue
    });
  }
  return NOTHING;
}


