static bool SendRadio(RadioChannel &channel, GameValuePar oper1, GameValuePar oper2)
{
  GameStringType wave = oper2;
  Object *obj = GetObject(oper1);
  EntityAI *veh = dyn_cast<EntityAI>(obj);
  AIBrain *unit = veh ? veh->CommanderUnit() : NULL;
  channel.Transmit(new RadioMessageText(wave, unit));
  return true;
}

/*
\patch 1.50 Date 4/15/2002 by Jirka
- Fixed: HQ names in radio messages
*/
static bool SendRadio(RadioChannel &channel, RString identity, GameValuePar oper2)
{
  GameStringType wave = oper2;
  if (!(Pars >> "CfgHQIdentities").FindEntry(identity)) return false;
  // send class name, translate in RadioChannel::Say
  channel.Transmit(new RadioMessageText(wave, identity));
  return true;
}

GameValue ObjGlobalRadio( const GameState *state, GameValuePar oper1, GameValuePar oper2 )
{
  if (!SendRadio(GWorld->GetRadio(), oper1, oper2)) state->SetError(EvalGen);
  return NOTHING;
}

GameValue ObjVehicleRadio( const GameState *state, GameValuePar oper1, GameValuePar oper2 )
{
  AIBrain *unit = GetUnit(state, oper1);
  if (!unit) return NOTHING;
  Transport *veh = unit->GetVehicleIn();
  if (!veh) return NOTHING;
  if (!SendRadio(veh->GetRadio(), oper1, oper2)) state->SetError(EvalGen);
  return NOTHING;
}

GameValue ObjCustomRadio( const GameState *state, GameValuePar oper1, GameValuePar oper2 )
{
  AIBrain *unit = GetUnit(state, oper1);
  if (!unit) return NOTHING;
  if (oper2.GetType() != GameArray) return NOTHING;
  const GameArrayType &array = oper2;
  if (array.Size()!=2 || array[0].GetType()!=GameScalar || array[1].GetType()!=GameString) return NOTHING;
  int ix = toInt((float)array[0]);
  if (ix<1 || ix>CCCustomN) return NOTHING;
  CustomChannelInfo &info = GCustomChannels.GetCustomChannelInfo(ix+CCCustom1-1);
  // the unit must be inside the channel unit list (only listed units are allowed to speak)
  if (!info.active || !info.CheckUnit(unit->GetPerson())) return NOTHING;
  // the player must be inside the channel unit list (only listed units are allowed to listen)
  if (!info.CheckUnit(GWorld->PlayerOn())) return NOTHING;
  if (!SendRadio(GWorld->GetCustomRadio(ix-1), oper1, array[1])) state->SetError(EvalGen);
  return NOTHING;
}

GameValue ObjDirectRadio( const GameState *state, GameValuePar oper1, GameValuePar oper2 )
{
  AIBrain *unit = GetUnit(state, oper1);
  if (!unit) return NOTHING;
  Person *man = unit->GetPerson();
  if (!man) return NOTHING;
  RadioChannel *radio = man->GetRadio();
  if (!radio) return NOTHING;
  if (!SendRadio(*radio, oper1, oper2)) state->SetError(EvalGen);
  return NOTHING;
}

