{
  if (audible) GChatList.AddUC(channel, sender, message, false, true);
// Do not send over network - used as title effects etc.
// - activated on each client
/*
  RefArray<NetworkObject> units;
  WhatUnits(units, channel, object);
  GetNetworkManager().Chat(channel, sender, units, message);
*/
  return true;
}

/*
\patch 1.50 Date 4/15/2002 by Jirka
- Fixed: HQ names in chat messages
*/
static bool SendChat(ChatChannel channel, NetworkObject *object, RString identity, RString message, bool audible)
{
  ConstParamEntryPtr cfg = (Pars >> "CfgHQIdentities").FindEntry(identity);
  if (!cfg) return false;
  
  // used only in GChatList.Add - write directly display name
  RString sender = *cfg >> "name";

  if (audible) GChatList.AddUC(channel, sender, message, false, true);
// Do not send over network - used as title effects etc.
// - activated on each client
/*
  RefArray<NetworkObject> units;
  WhatUnits(units, channel, object);
  GetNetworkManager().Chat(channel, sender, units, message);
*/
  return true;
}

GameValue ObjCustomChat( const GameState *state, GameValuePar oper1, GameValuePar oper2 )
{
  AIBrain *unit = GetUnit(state, oper1);
  if (!unit) return NOTHING;
  if (oper2.GetType() != GameArray) return NOTHING;
  const GameArrayType &array = oper2;
  if (array.Size()!=2 || array[0].GetType()!=GameScalar || array[1].GetType()!=GameString) return NOTHING;
  int ix = toInt((float)array[0]);
  if (ix<1 || ix>CCCustomN) return NOTHING;
  CustomChannelInfo &info = GCustomChannels.GetCustomChannelInfo(ix+CCCustom1-1);
  // the unit must be inside the channel unit list (only listed units are allowed to speak)
  if (!info.active || !info.CheckUnit(unit->GetPerson())) return NOTHING;
  // the player must be inside the channel unit list (only listed units are allowed to listen)
  if (!info.CheckUnit(GWorld->PlayerOn())) return NOTHING;
  bool audible = GWorld->GetCustomRadio(ix-1).IsAudible();
  RString msg1 = array[1];
  if (!SendChat(ChatChannel(CCCustom1+ix-1), NULL, unit, msg1, audible)) state->SetError(EvalGen);
  return NOTHING;
}

