__forceinline static int GetMemoryPointIndex(Object* obj, RString memoryPoint)
{
  int memIdx = -1;

  if (memoryPoint.GetLength() > 0)
  {
    const LODShape *shape = obj->GetShape();
    if (shape)
    {
      const Shape *memory = shape->MemoryLevel();
      if (memory)
        memIdx = shape->PointIndex(memory, memoryPoint);
    }
  }

  return memIdx;
}

static GameValue ObjAttachTo( const GameState *state, GameValuePar oper1, GameValuePar oper2 )
{
#if _ENABLE_ATTACHED_OBJECTS
  if (!GetNetworkManager().IsServerOwner())
  {
    state->AccessError("attachTo");
    return NOTHING;
  }

  // check and load the parameters
  Object *obj = GetObject(oper1);
  if (!obj) return NOTHING;

  const GameArrayType &array = oper2;
  if (array.Size() < 1)
  {
    state->SetError(EvalDim, array.Size(), 3);
    return NOTHING;
  }

  Object *objTo = GetObject(array[0]);
  if (!objTo) return NOTHING;

  Vector3 offset;
  if (array.Size() > 1)
  {
    if (!GetVector(state, offset, array[1])) return NOTHING;
  }
  else
  {
    // attach where we are
    offset = Vector3(VFastTransform, objTo->FutureVisualState().GetInvTransform(), obj->FutureVisualState().Position());
  }

  RString memoryPoint;
  if (array.Size() == 3)
  {
    if (!CheckType(state, array[2], GameString)) return NOTHING;
    memoryPoint = array[2];
  }

  // find the memory point
  int memoryPointIndex = -1;
  if (memoryPoint.GetLength() > 0)
  {
    const LODShape *shape = objTo->GetShape();
    if (shape)
    {
      const Shape *memory = shape->MemoryLevel();
      if (memory) memoryPointIndex = shape->PointIndex(memory, memoryPoint);
    }
  }

  int flags = 0;
  if ( obj->AttachTo(objTo, offset, memoryPointIndex, flags) && !obj->GetNetworkId().IsNull() && !objTo->GetNetworkId().IsNull() )
  { // networking possible only for attachto with both obj and objTo having NetworkIds
    GetNetworkManager().AttachObject(obj, objTo, memoryPointIndex, offset, flags);
  }
#endif

  return NOTHING;
}

GameValue ObjDetach(const GameState *state, GameValuePar oper1)
{
#if _ENABLE_ATTACHED_OBJECTS
  if (!GetNetworkManager().IsServerOwner())
  {
    state->AccessError("detach");
    return NOTHING;
  }

  Object *obj = GetObject(oper1);
  if (!obj) return NOTHING;

  obj->Detach();
  GetNetworkManager().DetachObject(obj);
#endif

  return NOTHING;
}

