GameValue GetHUDMovementLevels(const GameState *state)
{
  Vector3 oldMin = GWorld->GetMoveMinBordersHUD();
  Vector3 oldMax = GWorld->GetMoveMaxBordersHUD();
  Vector3 oldPos = GWorld->GetMovePositionHUD();
  Entity *target = GWorld->GetMoveTargetHUD();

  GameValue value = state->CreateGameValue(GameArray);
  GameArrayType &result = value;

  result.Add(oldMin[0]);
  result.Add(oldMax[0]);
  result.Add(oldMin[1]);
  result.Add(oldMax[1]);  
  result.Add((oldMin[2] / H_PI) * 180);
  result.Add((oldMax[2] / H_PI) * 180);

  if(target)
  {
    result.Add(GameValueExt(target));
  }
  else
  {
    GameValue valuePos = state->CreateGameValue(GameArray);
    GameArrayType &resultPos = valuePos;

    resultPos.Add(oldPos[0]);
    resultPos.Add(oldPos[2]);
    resultPos.Add(oldPos[1]);
    result.Add(valuePos);
  }
  return value;
}

GameValue SetHUDMovementLevels(const GameState *state, GameValuePar oper1)
{
  const GameArrayType &array = oper1;
  if (!CheckSize(state, array, 7)) return NOTHING;
  if (!CheckType(state, array[0], GameScalar)) return NOTHING;
  if (!CheckType(state, array[1], GameScalar)) return NOTHING;
  if (!CheckType(state, array[2], GameScalar)) return NOTHING;
  if (!CheckType(state, array[3], GameScalar)) return NOTHING;
  if (!CheckType(state, array[4], GameScalar)) return NOTHING;
  if (!CheckType(state, array[5], GameScalar)) return NOTHING;

  Vector3 oldMin = GWorld->GetMoveMinBordersHUD();
  Vector3 oldMax = GWorld->GetMoveMaxBordersHUD();
  Vector3 oldPos = GWorld->GetMovePositionHUD();

  Vector3 min = Vector3(
    ((float)(array[0]) < 0.0)? oldMin[0] : (float)array[0],
    ((float)(array[2]) < 0.0)? oldMin[1] : (float)array[2],
    ((float)(array[4]) < 0.0)? oldMin[2] : ((float)array[4] / 180) * H_PI );

  Vector3 max = Vector3(
    ((float)(array[1]) < 0.0)? oldMax[0] : (float)array[1],
    ((float)(array[3]) < 0.0)? oldMax[1] : (float)array[3],
    ((float)(array[5]) < 0.0)? oldMax[2] : ((float)array[5] / 180) * H_PI);

  Vector3 pos = VZero;
  Entity *target = NULL;
  if(array[6].GetType() == GameArray)
  {
    const GameArrayType &arrayPos = array[6];
    if (!CheckSize(state, arrayPos, 3)) return NOTHING;
    if (!CheckType(state, arrayPos[0], GameScalar)) return NOTHING;
    if (!CheckType(state, arrayPos[1], GameScalar)) return NOTHING;
    if (!CheckType(state, arrayPos[2], GameScalar)) return NOTHING;

    pos[0] = arrayPos[0];
    pos[1] = arrayPos[2];
    pos[2] = arrayPos[1];
    if(pos[0] < 0 && pos[1] < 0 && pos[2] < 0) pos = oldPos;

  }
  else if(array[6].GetType() == GameObject)
  {
    Object *obj = GetObject(array[6]);
    if (!obj) return NOTHING;
    target = dyn_cast<Entity>(obj);
    pos = oldPos;
  }


  GWorld->SetMoveMinBordersHUD(min);
  GWorld->SetMoveMaxBordersHUD(max);
  GWorld->SetMovePositionHUD(pos);
  GWorld->SetMoveTargetHUD(target);

  return NOTHING;
}

