GameValue CamConstructParams( const GameState *state, GameValuePar oper1,  GameValuePar oper2 )
{
  CameraConstruct *cam = dyn_cast<CameraConstruct>(GetObject(oper1));
  if( !cam ) return NOTHING;

  const GameArrayType &array = oper2;
  if(array.Size() != 3)
  {
    state->SetError(EvalDim,array.Size(),3);
    return NOTHING;
  }
  if (array[0].GetType() != GameArray)
  {
    state->TypeError(GameArray,array[0].GetType());
    return NOTHING;
  }
  if (array[1].GetType() != GameScalar)
  {  
    state->TypeError(GameScalar,array[1].GetType());
    return NOTHING;
  }
  if (array[2].GetType() != GameScalar)
  {  
    state->TypeError(GameScalar,array[2].GetType());   
    return NOTHING;
  }

  const GameArrayType &arrayPos = array[0];
  if(arrayPos.Size() != 3 || 
    arrayPos[0].GetType()!=GameScalar || arrayPos[1].GetType()!=GameScalar || arrayPos[2].GetType()!=GameScalar)
    return NOTHING;

  Vector3 pos = Vector3(arrayPos[0],arrayPos[2],arrayPos[1]);

  cam->SetParams(pos, array[1],array[2]);

  return NOTHING;
}

