GameValue SkipDayTime( const GameState *state, GameValuePar oper1 )
{
  float time=oper1;

  // change time
  // TODO: implement smooth change in world

  if (Glob.clockWeather.AdvanceTime(time * OneHour))
  {
    // Recalculate needs to be called before and after RecalculateLighting  for proper shadow direction
    // see also World::InitGeneral
    GScene->MainLight()->Recalculate();
    GScene->RecalculateLighting(1,GLandscape);
    GScene->MainLight()->Recalculate();
    GScene->MainLightChanged();
    // calculate sunOrMoon
	}    

	if (Glob.clock.AdvanceTime(time * OneHour))
	{
		float timeSec = time*(60*60);
    GLandscape->Simulate(timeSec);
    GLandscape->OnTimeSkipped();
    // if time changed a lot, recalculate lighting
    GWorld->OnTimeSkipped(timeSec);
  }

  return NOTHING;
}


