GameValue SetWind(const GameState *state, GameValuePar oper1)
{
  // Check input parameters
  const GameArrayType &array = oper1;
  if (array.Size() != 3) return NOTHING;

  // Check types of members
  if (!CheckType(state, array[0], GameScalar)) return NOTHING; 
  if (!CheckType(state, array[1], GameScalar)) return NOTHING; 
  if (!CheckType(state, array[2], GameBool)) return NOTHING; 

  // Init direction of the wind
  Vector3 windDirection(array[0], 0, array[1]);
  bool forced = array[2];

  // Set direction of the wind
  GLandscape->SetWindSpeed(windDirection, forced);

  return NOTHING;
}

