class BuildVehicleList
{
  GameArrayType &_vehicles;
public:
  BuildVehicleList(GameArrayType &array):_vehicles(array){}
  __forceinline bool operator () (Entity *veh) const
  {
    EntityAI *ai=dyn_cast<EntityAI>(veh);
    if (ai)
    {
      Person *person = dyn_cast<Person>(veh);
      if (!person)
      {
        _vehicles.Add(CreateGameObject(ai));
      }
    }
    return false;
  }
};

GameValue GetVehicles(const GameState *state)
{
  GameValue value = state->CreateGameValue(GameArray);
  GameArrayType &array = value;

  BuildVehicleList build(array);
  GWorld->ForEachVehicle(build);

  array.Compact();
  return value;
}

class BuildDeadVehiclesList
{
  GameArrayType &_vehicles;
public:
  BuildDeadVehiclesList(GameArrayType &array):_vehicles(array){}
  __forceinline bool operator () (Object *veh) const
  {
    if (veh)
    {
      Person *person = dyn_cast<Person>(veh);
      if (person && person->IsDeadSet()) _vehicles.Add(GameValueExt(veh));
      else
      {
        Transport *transport = dyn_cast<Transport>(veh);
        if (transport && transport->IsDestroyed()) _vehicles.Add(GameValueExt(veh));
      }
    }
    return false;
  }
};

GameValue GetAllDead(const GameState *state)
{
  GameValue value = state->CreateGameValue(GameArray);

  if (GWorld)
  {
    GameArrayType &array = value;

    BuildDeadVehiclesList dead(array);
    GWorld->ForEachVehicle(dead);
    GWorld->ForEachSlowVehicle(dead);
    GWorld->ForEachOutVehicle(dead);

    array.Compact();
    return value;
  }

  return value;
}


GameValue GetAllMissionObjects(const GameState *state, GameValuePar oper1)
{
  GameValue value = state->CreateGameValue(GameArray);
  RString typeName = oper1;

  if (GWorld)
  {
    GameArrayType &array = value;

    // repair all objects, remove any non-primaries
    for( int x=0; x< GLandscape->GetLandRange(); x++ ) for( int z=0; z< GLandscape->GetLandRange(); z++ )
    {
      const ObjectList &list=GLandscape->GetObjects(x,z);
      for (int i = 0; i < list.Size(); i++)
      {
        Object *obj=list[i];
        if( obj->GetType() != Primary && obj->GetType() != Network)
        {
          if (typeName.GetLength() > 0)
          {
            const EntityType *type = obj->GetEntityType();
            if (!type->IsKindOf(typeName)) continue;
          }
          array.Add(GameValueExt(obj));
        }
      }
    }

    array.Compact();
    return value;
  }

  return value;
}

class BuildVehicleListByType
{
  GameArrayType &_vehicles;
  RString _typeName;

public:
  BuildVehicleListByType(GameArrayType &array, RString typeName) : _vehicles(array), _typeName(typeName) {}
  __forceinline bool operator () (Entity *veh) const
  {
    if (_typeName.GetLength() > 0)
    {
      const EntityType *type = veh->GetEntityType();
      if (!type->IsKindOf(_typeName)) return false;
    }
    _vehicles.Add(GameValueExt(veh));
    return false;
  }
};

GameValue GetEntities(const GameState *state, GameValuePar oper1)
{
  GameValue value = state->CreateGameValue(GameArray);
  if (!GWorld) return value;

  GameArrayType &array = value;

  BuildVehicleListByType build(array, oper1);
  GWorld->ForEachVehicle(build);

  array.Compact();
  return value;
}

static ControlsContainer *GetUserDialog()
{
  ControlsContainer *dlg = dynamic_cast<ControlsContainer *>(GWorld->UserDialog());
  if (dlg)
  {
    while (dlg->Child()) dlg = dlg->Child();
  }
  return dlg;
}

GameValue SetObjectiveStatus(const GameState *state, GameValuePar oper1,  GameValuePar oper2)
{
  GameStringType name = GameStringType("OBJ_") + oper1;
  GameStringType str = oper2;
  ObjectiveStatus status = OSActive;  // avoid warning
  const EnumName *names = GetEnumNames(status);
  for (int i=0; names[i].IsValid(); i++)
  {
    if (stricmp(names[i].name, str) == 0)
    {
      status = (ObjectiveStatus)names[i].value;
      break;
    }
  }
  int value = status;
  int oldValue = toInt((float)state->VarGet(name, false, GWorld->GetMissionNamespace())); // mission namespace
  if (oldValue == value) return NOTHING;
  RString message = status == OSDone ? LocalizeString(IDS_OBJECTIVE_DONE) : LocalizeString(IDS_OBJECTIVE_UPDATED);
  if (Glob.config.ShowCadetHints() && status != OSHidden) GWorld->UI()->ShowHint(message, true);
  const_cast<GameState *>(state)->VarSet(name, GameValue((float)value), true, false, GWorld->GetMissionNamespace()); // mission namespace
  DisplayMap *map = dynamic_cast<DisplayMap *>(GWorld->Map());
  if (map)
  {
    GameVarSpace local(false);
    int gshandle = state->BeginContext(&local);
    map->AskForUpdatePlan();
    state->EndContext(gshandle);
  }
  return NOTHING;
}

