static bool ReadColor(const GameState *state, PackedColor &color, GameValuePar value)
{
  const GameArrayType &array = value;
  if (!CheckSize(state, array, 4)) return false;
  for (int i=0; i<4; i++)
  {
    if (!CheckType(state, array[i], GameScalar)) return false;
  }
  color = PackedColor(Color(array[0], array[1], array[2], array[3]));
  return true;
}

GameValue ShowTaskHint( const GameState *state, GameValuePar oper1 )
{
  Ref<Texture> texture =NULL;
  PackedColor color;
  RString text;
  const GameArrayType &arrayInput = oper1;

  switch(arrayInput.Size()) 
  {
  case 3:
    {//load task icon
      if(CheckType(state, arrayInput[2], GameString))
      {
        //read texture
        RString taskIcon = arrayInput[2];
        ParamEntryVal cfg = Pars >> "CfgDiary" >> "TaskIcons";
        texture = GLOB_ENGINE->TextBank()->Load
          (
          GetPictureName(cfg >> taskIcon)
          );
      }
    }
  case 2:
    {//message color
      if(arrayInput[1].GetType() == GameArray)
      {
        const GameArrayType &colorArray = arrayInput[1];
        if(!colorArray.Size()==0) //if array is empty, white color is used by default
        {
          ReadColor(state, color, arrayInput[1]);
        }
      }
    }
  case 1:
    {//task message
      if(arrayInput[0].GetType() == GameString)
      {
        text = arrayInput[0];
      }
      else
      {
        return NOTHING;
      }
      break;
    }
  default:
    return NOTHING;
  }

  GWorld->UI()->ShowTaskHint(text,color,texture);

  return NOTHING;
}

