static GameValue GetFirst( const GameState *state, GameValuePar oper1)
{
  if (oper1.GetType()!=GameArray) return oper1;
  const GameArrayType &callWithArgs = oper1;
  if (callWithArgs.Size()<1)
  {
    state->SetError(EvalDim,callWithArgs.Size(),1);
    return NOTHING;
  }
  return callWithArgs[0];
}

GameValue SpawnForPlayerHelper( const GameState *state, GameValuePar oper1, GameValuePar oper2, const GameType &type)
{
  if (!GetNetworkManager().IsServerOwner())
  {
    state->AccessError("spawnForPlayer");
    return NOTHING;
  }

  GameDataCode *code = code = static_cast<GameDataCode *>(oper2.GetData());;

  GameValue operPlayer = GetFirst(state,oper1);
  if (!CheckType(state,operPlayer,type)) return NOTHING;

  if (GetNetworkManager().IsServer())
  {
    int clientId = 0;
    if (type==GameObject)
    {
      Object *obj = GetObject(operPlayer);
      if (!obj) return NOTHING;
      NetworkId id = obj->GetNetworkId();
      if (id.IsNull()) return NOTHING;
      clientId = GetNetworkManager().GetOwner(id);
    }
    else
    {
      clientId = toInt(float(operPlayer));
    }

    const PlayerIdentity *identity = GetNetworkManager().FindIdentityByPlayerId(clientId);
    if (!identity) return NOTHING;

    // TODO: sign the code
    GetNetworkManager().SpawnForPlayer(identity->dpnid,code,oper1);
  }
  else
  {
    // enable also in SP to simplify shared code
    ScriptVM *script = new ScriptVM(ScriptVMDirect, *code, oper1, GWorld->GetGameState()->GetGlobalVariables());
    GWorld->AddScriptVM(script, false);
  }
  return NOTHING;
}

GameValue SpawnForPlayer( const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  if (!GetNetworkManager().IsServerOwner())
  {
    state->AccessError("spawnForPlayer");
    return NOTHING;
  }
  return SpawnForPlayerHelper(state,oper1,oper2,GameObject);
}

/*
	created based on SpawnForPlayer, where player object does not yet exist
*/
GameValue SpawnForClient( const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  if (!GetNetworkManager().IsServerOwner())
  {
    state->AccessError("spawnForClient");
    return NOTHING;
  }

  return SpawnForPlayerHelper(state,oper1,oper2,GameScalar);
}

