GameValue ObjMoveInTurret(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  if (!GetNetworkManager().IsServerOwner())
  {
    state->AccessError("moveInTurret");
    return NOTHING;
  }

  // first argument - unit
  Object *obj = GetObject(oper1);
  if (!obj) return NOTHING;
  Person *soldier = dyn_cast<Person>(obj);
  if (!soldier) return NOTHING;
  AIBrain *unit = soldier->Brain();
  if (!unit) return NOTHING;

  const GameArrayType &array = oper2;
  if (!CheckSize(state, array, 2)) return NOTHING;

  // second argument - vehicle
  obj = GetObject(array[0]);
  if (!obj) return NOTHING;
  Transport *veh = dyn_cast<Transport>(obj);
  if (!veh) return NOTHING;

  // third argument - turret
  Turret *turret = GetTurret(state, veh, array[1]);
  if (!turret) return NOTHING;

#if _VBS3
  return MoveInTurret(unit, soldier, veh, turret);

#else
  if (!PrepareMoveIn(unit, veh)) return NOTHING;
  if (veh->QCanIGetInTurret(turret, soldier))
  {
    veh->GetInTurret(turret, soldier, false, true);

    if (GWorld->FocusOn() == unit)
      GWorld->SwitchCameraTo(veh, ValidateCamera(GWorld->GetCameraType()), false);
  }
  return NOTHING;
#endif
}

/*!
\patch 1.08 Date 07/26/2001 by Jirka
- Fixed: procedure "moveInCargo" is now MP safe

\patch 5163 Date 6/1/2007 by Ondra
- Fixed: Scripting function soldier moveInCargo [vehicle,position] was not implemented.
*/
GameValue ObjMoveInCargo( const GameState *state, GameValuePar oper1, GameValuePar oper2 )
{
  if (!GetNetworkManager().IsServerOwner())
  {
    state->AccessError("moveInCargo");
    return NOTHING;
  }

  // first argument - unit
  Object *obj1 = GetObject(oper1);
  if (!obj1) return NOTHING;
  Person *soldier = dyn_cast<Person>(obj1);
  if (!soldier) return NOTHING;
  AIBrain *unit = soldier->Brain();
  if (!unit) return NOTHING;

	Object *obj2 = NULL;
	int cargoIndex = -1;

  // Accept array as second parameter [vahicle, Index]
  if (oper2.GetType() == GameArray)
	{
		const GameArrayType &array = oper2;
		if(array.Size() != 2)
		{
			state->SetError(EvalDim,array.Size(),2);
			return NOTHING;
		}
		if (array[0].GetType() != GameObject)
		{
			state->TypeError(GameObject,array[0].GetType());
			return NOTHING;
		}
		if (array[1].GetType() != GameScalar)
		{
			state->TypeError(GameScalar,array[1].GetType());
			return NOTHING;
		}
		obj2 = GetObject(array[0]);
		cargoIndex = float((float)array[1]);
	}
	else
	{
    // second argument - vehicle
		obj2 = GetObject(oper2);
  }
  if (!obj2) return NOTHING;

  Transport *veh = dyn_cast<Transport>(obj2);
  if (!veh) return NOTHING;
  if (!PrepareMoveIn(unit,veh)) return NOTHING;

  const ManCargo &cargo = veh->GetManCargo();
  if(cargoIndex < -1 || cargoIndex >= cargo.Size())
    return NOTHING;
  cargoIndex = veh->QCanIGetInCargo(soldier, cargoIndex);
  if (cargoIndex >= 0)
  {
    veh->GetInCargo(soldier,false,cargoIndex,true);
    unit->SetInCargo(true);

    if (GWorld->FocusOn() == unit)
      GWorld->SwitchCameraTo(veh, ValidateCamera(GWorld->GetCameraType()), false);
  }
  return NOTHING;
}
static inline GameValue ObjMoveInCargo2(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  return ObjMoveInCargo(state, oper1, oper2);
}

#if _ENABLE_CHEATS
#include <El/Speech/vonCodec.hpp>
#include <El/Speech/vonApp.hpp>

// it should be always reset to default when MP mission starts
int GNextPersonDpnid = 100; //such low integers cannot collide with existing real players dpnid
GameValue ObjVoNSay(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  // first argument - AI
  Object *obj = GetObject(oper1);
  if (!obj) return NOTHING;
  Person *soldier = dyn_cast<Person>(obj);
  if (!soldier) return NOTHING;
  //if (!soldier->IsLocal()) return NOTHING;

  // defaults
  int vonChannel=0;
  int vonFrequency = 440; //Middle A (in Hz)
  int vonSeconds = 1;     //One second as default

  const GameArrayType &array = oper2;
  switch (array.Size())
  {
  case 4: 
    {
      if (!CheckType(state, array[3], GameScalar)) return NOTHING;
      vonSeconds = toInt((float)array[3]);
    }
  case 3:
    {
      if (!CheckType(state, array[2], GameScalar)) return NOTHING;
      vonFrequency = toInt((float)array[2]);
    }
  case 2:
    {
      if (!CheckType(state, array[1], GameScalar)) return NOTHING;
      // XOR of 1..2D, 2..3D
      int say2D3D = toInt((float)array[1]);
      if (say2D3D & 1) vonChannel |= TTChan2D;
      if (say2D3D & 2) vonChannel |= TTChan3D;
    }
  case 1:
    {
      if (!CheckType(state, array[0], GameScalar)) return NOTHING;
      vonChannel |= toInt((float)array[0]);
      // data are prepared, so create the packet and add it into VoN System
      // Obtain the person's dpnid. If there is no such, assign first available
      int dpnid;soldier->GetVoNSayDpnid();
      if (!soldier->IsLocal())
        dpnid = soldier->GetRemotePlayer();
      else
        dpnid = soldier->GetVoNSayDpnid();
      if (!dpnid) 
      {
        dpnid=GNextPersonDpnid++;
        soldier->SetVoNSayDpnid(dpnid);
      }
      //GetNetworkManager().VoNSay should create VoNReplayer and other structures if it does not exist yet
      GetNetworkManager().VoNSay(dpnid, vonChannel, vonFrequency, vonSeconds);
    }
    break;
  default: // no action
    break;
  }

  return NOTHING;
}
#endif

