GameValue PosIsOnRoad(const GameState *state, GameValuePar oper1)
{
  Vector3 pos;
  if (!GetPos(state, pos, oper1)) return false;
  // check what precision for y we need
  float sizeY = 0.5f;
  if (oper1.GetType() == GameObject)
  {
    Object *obj = GetObject(oper1);
    Assert(obj); // already passed GetPos
    if (obj->GetShape()) sizeY = obj->GetShape()->GeometrySphere();
  }

  const RoadNet *roadNet = GLandscape->GetRoadNet();
  if (!roadNet) return false;
  bool onRoad = roadNet->IsOnRoad(pos, 0.01f, sizeY) != NULL; 
  return onRoad;
}

