static inline float ObjOffset(Object *proxy, Vector3Par pos = VZero)
{
  float objOffset = 0;
  if (proxy)
  {
    EntityAI *veh = dyn_cast<EntityAI>(proxy);    
    if (veh)
    {
      LODShape *shape = veh->GetShape();
      if (!veh->Static() && shape)
      {
        const Shape *geom = shape->LandContactLevel();
        if (!geom) geom = shape->GeometryLevel();
        if (geom)
        {
          objOffset = -geom->Min().Y();
        }
        else if (shape->NLevels()>0)
        {
          ShapeUsed level0 = shape->Level(0);
          objOffset = -level0->Min().Y();
        }
        else
        {
          objOffset = -shape->Min().Y();
        }
      }
      else
      {
        Matrix4 trans = proxy->FutureVisualState().Transform();
        Vector3 objPos = pos == VZero ? trans.Position() : pos;
        float surfaceHgt = GLandscape->SurfaceYAboveWater(objPos[0],objPos[2]);
        trans.SetPosition(Vector3(objPos[0],surfaceHgt,objPos[2]));
        veh->PlaceOnSurface(trans);
        objOffset = trans.Position()[1] - surfaceHgt;
      }
    }
  }
  return objOffset;
}

/*!
\patch 5136 Date 2/28/2007 by Jirka
- Fixed: MP - dynamically created helicopters handle "FLY" flag correctly now
*/

Entity *CreateVehicle(Vector3 &pos, RString type, bool local, bool init = true, ArcadeUnitSpecial special = ASpNone, bool expectedEmpty = false, bool keepHeight = false, Vector3 forward = VForward, Vector3 up = VUp)
{
  float height = 0;
  if (keepHeight) height = pos[1] - GLandscape->SurfaceYAboveWater(pos[0], pos[2]);

  Ref<Entity> veh = GWorld->NewNonAIVehicleWithID(type,RString());
  if (!veh) return NULL;

  // do not create vehicles not fully loaded
  if (dyn_cast<Transport>(veh.GetRef()))
  {
    // some special entities without model are OK (#particlesource etc.), but transports are causing crashes
    if (!veh->GetShape()) return NULL;
    if (veh->GetShape()->NLevels() == 0) return NULL;
  }

  EntityAI *vehAI = dyn_cast<EntityAI>(veh.GetRef());
  // FIX: Prevent CreateVehicle call for vehicles with Brain
  if (expectedEmpty && vehAI && vehAI->CommanderUnit())
  {
    RptF("UnExpected call of CreateVehicle for '%s', pos(%f.2,%f.2,%f.2). Vehicles with brain cannot be created using 'createVehicle'!",
         cc_cast(type), pos.X(),pos.Y(),pos.Z() );
    return NULL;
  }

  if (vehAI && special != ASpCanCollide)
  {
    bool isSoldier = dyn_cast<Person>(vehAI) != NULL;
    if (AIBrain::FindFreePosition(pos, up, isSoldier, vehAI->GetType()))
    {
      // PlaceOnSurface will do this
/*
      float dx,dz;
      pos[1] = isSoldier ? GLandscape->RoadSurfaceYAboveWater(pos[0], pos[2], &dx, &dz) : GLandscape->SurfaceYAboveWater(pos[0], pos[2], &dx, &dz);
      up = Vector3(-dx,1,-dz);
*/
    }
  }

  Matrix3 dir;
  Matrix4 transform;

  transform.SetPosition(pos);
  dir.SetUpAndDirection(up, forward);
  transform.SetOrientation(dir);

  if (vehAI && !dynamic_cast<PoweredItem*>(veh.GetRef()))
  {
    veh->PlaceOnSurface(transform, !veh->CanFloat());
  }

  if (keepHeight) 
  {
    Vector3 position = transform.Position();
    position[1] += height;
    transform.SetPosition(position);
  }

  veh->SetTransform(transform);

  // TODO: special == ASpForm
  if (special == ASpFlying)
  {
    if (vehAI && vehAI->GetType()->IsKindOf(GWorld->Preloaded(VTypeAir)))
    {
      pos[1] += vehAI->MakeAirborne(transform.Orientation().Direction(), false);
      transform.SetPosition(pos);
      veh->SetTransform(transform);
    }
  }

  if (init)
  {
    veh->Init(transform, true);
    if (vehAI) vehAI->OnEvent(EEInit);
  }

  // if vehicle is static, add it to building list
  if (vehAI)
  {
    const EntityAIType *type = vehAI->GetType();
    if (type->IsSlow())
    {
      // to prevent any problems we will insert all user created objects into slow vehicle list
      // no building list exists any more
      GWorld->AddSlowVehicle(veh);
      if (!local && GWorld->GetMode() == GModeNetware)
        GetNetworkManager().CreateVehicle(veh, VLTSlowVehicle, "", -1);
    }
    else
    {
      GWorld->AddVehicle(veh);
      if (!local && GWorld->GetMode() == GModeNetware)
        GetNetworkManager().CreateVehicle(veh, VLTVehicle, "", -1);
    }
  }
  else if (dyn_cast<Shot>(veh.GetRef()))
  {
    GWorld->AddFastVehicle(veh);
    GWorld->AddSupersonicSource(veh);
    if (!local && GWorld->GetMode() == GModeNetware)
      GetNetworkManager().CreateObject(veh);
  }
  else
  {
    GWorld->AddAnimal(veh);
    if (!local && GWorld->GetMode() == GModeNetware)
      GetNetworkManager().CreateVehicle(veh, VLTAnimal, "", -1);
  }

  // when creating buildings or other static objects, invalidate the rasterized fields in the cache
  LODShape *shape = veh->GetShape();
  if (shape && veh->HasGeometry() && veh->Static())
  {
    Entity::ProtectedVisualState<const EntityVisualState> vs = veh->FutureVisualStateScope();
    
    // what fields this object can belong to
    int xMin, xMax, zMin, zMax;
    ObjRadiusRectangle(xMin, xMax, zMin, zMax, vs->Position(), shape->BoundingSphere() * vs->Scale());
    for (int x=xMin; x<=xMax; x++)
      for (int z=zMin; z<=zMax; z++)
        GLandscape->OperationalCache()->RemoveField(LandIndex(x), LandIndex(z));
  }

  return veh;
}

void PositionToAA11(Vector3Val pos, char *buffer);
//Return position or object's position as a map grid coord.
GameValue MapGridPosition (const GameState *state,GameValuePar oper1)
{
  Vector3 position;

  if (oper1.GetType() == GameObject)
  {
    Object *object = GetObject(oper1);
    if (!object) return RString("");

    position = object->WorldPosition(object->FutureVisualState());
  }
  else if (!GetPos(state,position,oper1)) return RString("");

  char buffer[32] = {0};
  PositionToAA11(position,buffer);

  return RString(buffer);
}

/*!
\patch 1.90 Date 10/25/2002 by Ondra
- Fixed: createVehicle may be used to create shells and other non-ai vehicles.
*/

GameValue VehCreate( const GameState *state, GameValuePar oper1, GameValuePar oper2 )
{
  if (!GetNetworkManager().IsServerOwner())
  {
    state->AccessError("createVehicle");
    return GameValueExt(nullptr,GameValExtObject);
  }

  GameStringType type = oper1;
  Vector3 pos;
  if (!GetPos(state, pos, oper2))
  {
    //state->SetError(EvalGen);
    return OBJECT_NULL;
  }
  Entity *veh = CreateVehicle(pos, type, false, true, ASpNone, /*expectedEmpty*/ true);

  // we need other entities nearby to be notified of our presence
  EntityAI *ai = dyn_cast<EntityAI>(veh);
  if (ai)
  {
    GWorld->OnEntityMovedFar(ai);
  }

  return GameValueExt(veh);
}

GameValue VehCreateLocal(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  GameStringType type = oper1;
  Vector3 pos;
  if (!GetPos(state, pos, oper2))
  {
    //state->SetError(EvalGen);
    return OBJECT_NULL;
  }
  return GameValueExt(CreateVehicle(pos, type, true));
}

