GameValue ExportBuildingProxy(const GameState *state, GameValuePar oper1)
{
	if( GetWResource() )
		DestroyWResource();

	WRLoot* loot = CreateWResource()->GetWRLoot();

	DWORD start = GetTickCount();

	loot->RegisterLoot(true);

#if USER_Ondra
#else
	loot->RegisterSetup();
	loot->RegisterGroups();
#endif

	const GameArrayType& array = oper1;
	if( array.Size() != 2 )
	{
		state->SetError(EvalDim,array.Size(),2);
		return NOTHING;
	}

	// get position
	Vector3 pos;
	if( !GetPos(state,pos,array[0]) )
		return NOTHING;
    

	WRStringPool* groupNames = loot->GetGroupNames();
	RptF("[&] Exporting types (%d):", groupNames->GetCount() );

	// types that will be searched in maps
	RefArray<const EntityType> types;
	for( int c = 0; c < groupNames->GetCount(); c++ )
	{
		types.Add(VehicleTypes.New( *groupNames->GetString(c) ));
		RptF("  %s", groupNames->GetString(c)->Data() );
	};

	int nTypes = types.Size();

	float limit = array[1];

	int xMin, xMax, zMin, zMax;
	ObjRadiusRectangle(xMin, xMax, zMin, zMax, pos, pos, limit);
	float minDist2 = Square(limit);

	// parse through map and seek for required type of object
	for( int x=xMin; x<=xMax; x++ ) 
	{
		for( int z=zMin; z<=zMax; z++ )
		{
			const ObjectListUsed &list = GLandscape->UseObjects(x,z);
			int n = list.Size();    
			for( int i = 0; i < n; i++ )
			{
				Object* obj = list[i];

				if( obj->FutureVisualState().Position().Distance2(pos) > minDist2 )
					continue;

				EntityAI* ai = dyn_cast<EntityAI>(obj);
				if( !ai )
					continue;


				// check if required type
				for( int j = 0; j < nTypes; j++ )
				{
					if( ai->GetType() == types[j] )
					{
						loot->InsertGroup(groupNames->GetString(j)->Data(),obj);
						break;
					};
				};
			};
		};

		FreeOnDemandGarbageCollectMain(512*1024,128*1024);
		FreeOnDemandFrame();

		RptF("  Exporting %0.1f %%", ((xMax-xMin)>0) ? ((100.0f*(float)(x-xMin))/(float)(xMax-xMin)) : 0.0f );

	};

	// export binary
	loot->SaveToFile("proxyexport.bin");

	// just for record
	loot->ListToConsole();


	DWORD end = GetTickCount();
	RptF("PROXY_EXPORT: %d (sec)", (end-start)/1000 );

	return NOTHING;
}

void ItemPlaceOnSurfacePoint( WRClassHierarchy* pClass, Entity* pEntity, Matrix4 &trans, Vector3Val surfPos, float dx, float dz )
{
  int rotationFlags = InventoryItem::RF_RANDOMIZE;

  //populate class
  if (pClass)
  {
    if (!pClass->CheckFlags(WRClassHierarchy::ECH_ROTATENEVER))
    {
      rotationFlags |= (pClass->CheckFlags(WRClassHierarchy::ECH_ROTATEALWAYS) ? InventoryItem::RF_MASTER : 0) |
                       (pClass->CheckFlags(WRClassHierarchy::ECH_ROTATEINVERT) ? InventoryItem::RF_INVERT : 0) |
                       (pClass->CheckFlags(WRClassHierarchy::ECH_ROTATEDROPPEDZ) ? InventoryItem::RF_ZAXIS : 0);
    };
  };
  
  const LODShape *shape = pEntity->GetShape();
  const Shape *memory = shape->MemoryLevel();

  //generate bounding box
	Vector3 boundingBox[2];
  InventoryItemType::ComputeBoundingBox(shape, memory, boundingBox);

  InventoryItem* item = dyn_cast<InventoryItem>(pEntity);
  if( item )
    item->ItemPlaceOnSurfacePoint(rotationFlags, trans, surfPos, dx, dz, boundingBox);
}


void ItemDropToPoint( WRClassHierarchy* pClass, Entity* pEntity, Vector3Par pos, Vector3Par dir, Vector3Par up, bool bTrace )
{

	// default transformation
	Matrix4 transform;
	transform.SetUpAndDirection( up, dir );
	transform.SetPosition(pos);

  if (pEntity->GetShape())
  {
    Vector3 result = pos;

    float dx = 0, dz = 0;
    if( bTrace )
    {
      InventoryItem* item = dyn_cast<InventoryItem>(pEntity);
      if( item )
        result[1] = item->FindMaxElevation(NULL, pos, true, &dx, &dz);
    }

		ItemPlaceOnSurfacePoint(pClass,pEntity,transform,result,dx,dz);
	};

	// set final transformationn
	pEntity->SetTransform(transform);

}

void ItemDropToProxy( WRClassHierarchy* pClass, Entity* pEntity, Vector3Par pos, Vector3Par dir, Vector3Par up )
{

	// default transformation
	Matrix4 transform;
	transform.SetUpAndDirection( up, dir );
	transform.SetPosition(pos);

	// set final transformationn
	pEntity->SetTransform(transform);

}


InventoryItem* SpawnLootObjectInInventory( Entity* pEntity, const char* sAttachment )
{
	InventoryItem* item = NULL;

	Person* person = dyn_cast<Person>(pEntity);
	if( person )
	{
		item = person->CreateItem(sAttachment);
	}
	else
	{
		InventoryItem* container = dyn_cast<InventoryItem>(pEntity);
		if( container )
			item = container->CreateAttachment(sAttachment);
	};

	if( item )
	{
		item->DisableSimulation(true);

		const InventoryItemType *type = item->Type();
		if (type)
		{
			//set random damage
			float _damage = type->GetSpawnDamageMax();
			if (_damage > 0)
			{
				float _rnd = GRandGen.RandomValue();
				_damage = floatMin(_rnd,_damage);
				item->SetDamage(_damage,true);
			};
		};
	};

	return item;
}

InventoryItem* SpawnLootObjectInCargo( Entity* pEntity, const char* sAttachment )
{
	InventoryItem* item = NULL;

	EntityAI* entity = dyn_cast<EntityAI>(pEntity);
	if( entity && entity->GetSupply() )
		item = entity->GetSupply()->GetItemsCargo().CreateItem(entity,sAttachment);

	if( item )
	{
		item->SetTargetCategory("loot");
		item->DisableSimulation(true);
	};

	//set some default values
	if (item)
	{
		const InventoryItemType *type = item->Type();
		if (type)
		{
			int _quantity = 0;

			//spawn with quantity of whatever it is
			int _max = type->GetStackedMax();
			if( _max > 0 )
			{
				if( _max > 1 )
					_quantity = (GRandGen.RandomValue() * _max) + 1;
				else
					_quantity = 1;
			};

			GameVarSpace* vars = item->GetVars();
			if( vars )
				vars->VarSet("quantity",(float)_quantity);


			//set random damage
			float _damage = type->GetSpawnDamageMax();
			if (_damage > 0)
			{
				float _rnd = GRandGen.RandomValue();
				_damage = floatMin(_rnd,_damage);
				item->SetDamage(_damage,true);
			};
		};
	};

	return item;
}


Entity* SpawnLootObject( WRClassHierarchy* pClass, const char* sName, WRLoot_Point* pProxy, Vector3Par vPosOverride )
{
	Vector3 pos(pProxy?pProxy->GetOrigin():vPosOverride);

	// spawn entity
	Entity* veh = CreateVehicle( pos, sName, false, true, ASpCanCollide, true, true );
	if( veh == NULL )
	{
		// TODO: Bad endclass, solve it!
		return NULL;
	};
	//int _quantity = veh->GetVars();
	
	//set some default values
	InventoryItem *item = dyn_cast<InventoryItem>(veh);
	if (item)
	{
		const InventoryItemType *type = item->Type();
		if (type)
		{
			//game variables
			GameVarSpace *vars = item->GetVars();

			//spawn with quantity of whatever it is
			int _max = type->GetStackedMax();
			if (_max > 0)
			{
				int _quantity = 1;
				if (_max > 1)
				{
					_quantity = (GRandGen.RandomValue() * _max) + 1;
				};
				
				vars->VarSet("quantity", (float)_quantity);
			};

			//set random damage
			float _damage = type->GetSpawnDamageMax();
			if (_damage > 0)
			{
				float _rnd = GRandGen.RandomValue();
				_damage = floatMin(_rnd,_damage);
				item->SetDamage(_damage,true);
			};

			//set default resources
			ConstParamEntryPtr cls = (Pars >> "CfgVehicles").FindEntry(item->GetName());
			if (cls && cls->IsClass())
			{
				ParamEntryPtr entry = cls->FindEntry("tooltipResources");
				ParamEntryPtr resources = cls->FindEntry("Resources");
				if (entry && entry->IsArray())
				{
					if (resources && resources->IsClass())
					{
						int n = entry->GetSize();
						for (int i=0; i<n; i++) 
						{
							if ((*entry)[i].IsTextValue())
							{
								//get the resource
								RString resourceName = (*entry)[i].GetValue();
								//get value
								ParamEntryVal v = resources->FindEntry(resourceName);
								if (v.IsIntValue() )
									vars->VarSet(resourceName, (float)v.GetInt());
							};
						};
					};
				};
			};
		};
	};

	// we need other entities nearby to be notified of our presence
	EntityAI* ai = dyn_cast<EntityAI>(veh);
	if( ai )
		GWorld->OnEntityMovedFar(ai);

	Matrix4 trans = veh->FutureVisualState().Transform();
	Vector3 placingPoint(0,veh->PlacingPoint().Y(),0);

	if( pClass )
	{
		// default attachments
		AutoArray<RString*>& at = pClass->GetAttachments();
		if( at.Size() > 0 )
		{
			for( int atSize = 0; atSize < at.Size(); atSize++ )
				SpawnLootObjectInInventory(veh,at[atSize]->Data());
		};

		// default cargo
		AutoArray<RString*>& ct = pClass->GetCargo();
		if( ct.Size() > 0 )
		{
			for( int ctSize = 0; ctSize < ct.Size(); ctSize++ )
				SpawnLootObjectInCargo(veh,ct[ctSize]->Data());
		};

	};

	// process surface alignment
	if( pProxy && !pProxy->IsPoint() )
		ItemDropToProxy(pClass,veh,pos,pProxy->GetDirection(),pProxy->GetDirUp());
	else
		ItemDropToPoint(pClass,veh,pos,VForward,VUp,pProxy==NULL);

/*	
	if( veh->IsAttached() )
		veh->SetAttachMatrix( Matrix3(MDirection,dir,up) );
	else
		veh->SetDirectionAndUp(dir,up);
*/

	if( ai )
		ai->OnMoved();

	ai->SetTargetCategory("loot");
	
	veh->DisableSimulation(true);
	veh->SetInvisible(false);

	return veh;
}


GameValue SpawnBuildingProxy(const GameState *state, GameValuePar oper1)
{
	if( !GetWResource() )
		return NOTHING;

	WRLoot* loot = GetWResource()->GetWRLoot();
	if( !loot )
		return NOTHING;

	DWORD start = GetTickCount();

	// parse setup config
	loot->RegisterSetup();

	// check classes
	if( !loot->GetHierarchy() )
	{
		RptF("!!! No class hierarchy available" );
		return NOTHING;
	};

	const GameArrayType& array = oper1;
	if( array.Size() != 3 )
	{
		state->SetError(EvalDim,array.Size(),3);
		return NOTHING;
	}

	// get position
	Vector3 pos;
	if( !GetPos(state,pos,array[0]) )
		return NOTHING;

	  if( !CheckType(state, array[1], GameScalar) )
		  return NOTHING;
	
	int spawnCount = toInt((float)array[1]);
	if( spawnCount <= 0 )
	{
		RptF("!!! Cannot spawn this count of items: %d", spawnCount );
		return NOTHING;
	};

	float radius = (float)array[2];
	if( radius < 1.0f )
		return NOTHING;

	int totalCount = loot->GetTotalCount();
	int withinCount = loot->GetProxyCountWithingRange(pos,radius);

	int step = (withinCount<spawnCount) ? 0 : (withinCount/spawnCount);
	int miss = 0;

	int spawnSuccess = 0;
	int spawnFail = 0;

	// process proxy data
	for( int gCount = 0; gCount < loot->GetCount(); gCount++ )
	{
		WRLoot_Group* g = loot->GetGroup(gCount);
		if( !g->Distance(pos,radius) )
			continue;

		// get proper class definition
		WRSpawnClass* spawnClass = loot->GetSetup()->FindByName(g->GetName());
		if( spawnClass == NULL )
			continue;

		for( int sCount = 0; sCount < spawnClass->GetCount(); sCount++ )
		{
			WRContainer* spawn = spawnClass->Get(sCount);

			// what should be spawned
			for( int lCount = 0; lCount < spawn->GetLocationCount(); lCount++ )
			{
				WRSpawnLocation* loc = spawn->GetLocation(lCount);

				// find container data
				WRLoot_Container* container = g->FindSelection(loc->GetName());
				if( container == NULL )
					continue;

				// item count
				for( int iCount = 0; iCount < container->GetTotalCount(); iCount++ )
				{
					// limit count of spawned items
					if( step > 0 )
					{
						if( (++miss) < step )
							continue;
	
						miss = 0;
					};

//	#ifdef USER_raist
//					WRSpawnItem* item = loot->GetSetup()->GetItem("Tool_FireExtinguisher");
//	#else
					WRSpawnItem* item = spawn->GetRandomItem();
//	#endif
					if( item == NULL )
						continue;

					// select proxy
					WRLoot_Point* p = container->GetRandomProxy(WRLoot_Proxy::EPROXY_FREE);
					if( p == NULL )
						continue;

					p->SetFlags(WRLoot_Proxy::EPROXY_OCCUPIED);

					// spawn entity
					Entity* veh = SpawnLootObject( item->GetClass(), item->GetName(), p, p->GetOrigin() );
					if( veh == NULL )
					{
						spawnFail++;
						continue;
					};

					// limit item count
					if( (++spawnSuccess) >= spawnCount )
						break;
				};
			
				// limit item count
				if( spawnSuccess >= spawnCount )
					break;
			};
	

		};

		// limit item count
		if( spawnSuccess >= spawnCount )
			break;
	};

	DWORD end = GetTickCount();
	RptF("PROXY_SPAWN: %d (sec)", (end-start)/1000 );
	RptF("  total on map: %d", totalCount );
	RptF("  within range: %d", withinCount );
	RptF("  spawn success: %d", spawnSuccess );
	RptF("  spawn failed: %d", spawnFail );
	
	return NOTHING;
}


GameValue SpawnConfiguredProxy(const GameState *state, GameValuePar oper1)
{
	if( !GetWResource() )
		return NOTHING;

	WRLoot* loot = GetWResource()->GetWRLoot();
	if( !loot )
		return NOTHING;

#ifdef USER_raist
//	GetWResource()->GetWRDebug()->Clear();
	GetWResource()->GetWRDebug()->SetBoundaries(0.0f,0.0f,15000.0f,15000.0f);
#endif

	DWORD start = GetTickCount();

	// parse setup config
	loot->RegisterSetup();

	// check classes
	if( !loot->GetHierarchy() )
	{
		RptF("!!! No class hierarchy available" );
		return NOTHING;
	};

	const GameArrayType& array = oper1;
	if( array.Size() != 3 )
	{
		state->SetError(EvalDim,array.Size(),3);
		return NOTHING;
	}

	// get position
	Vector3 pos;
	if( !GetPos(state,pos,array[0]) )
		return NOTHING;

	if( !CheckType(state, array[1], GameScalar) )
		return NOTHING;
	
	int spawnCount = toInt((float)array[1]);
	if( spawnCount <= 0 )
	{
		RptF("!!! Cannot spawn this count of items: %d", spawnCount );
		return NOTHING;
	};

	float radius = (float)array[2];
	if( radius < 1.0f )
		return NOTHING;

	int totalCount = loot->GetTotalCount();
	int withinCount = loot->GetProxyCountWithingRange(pos,radius);

	if( withinCount <= 0 )
	{
		RptF("!!! No spawnable point/ proxies inside defined area." );
		return NOTHING;
	};

	// how many percent of point within we want to use
	float percentual = (withinCount<=spawnCount) ? 1.0f : ((float)spawnCount/(float)withinCount);

	int spawnAttempt = 0;
	int spawnSuccess = 0;
	int spawnFail = 0;

	float adjustProbability = 1.0f;
	float spawnRatio = 0.0f;

	int populatedHouses = 0;
	int totalHouses = loot->GetCount();

	// process proxy data
	for( int gCount = 0; gCount < loot->GetCount(); gCount++ )
	{
		WRLoot_Group* g = loot->GetGroup(gCount);
		WRLoot_Group* groupPopulated = g;
		if( !g->Distance(pos,radius) )
			continue;

		// actual count
		int current = g->GetTotalCount();
		// how many items should be spawned inside this building
		int required = (int)((float)current*percentual);
		if( required < 1 )
			continue;

		// get proper class definition
		WRSpawnClass* spawnClass = loot->GetSetup()->FindByName(g->GetName());
		if( spawnClass == NULL )
			continue;

		// reset "old" population numbers
		spawnClass->OnReset();

		int classIdx = 0;
		int maxTests = required*10; // todo: define much more smaller number once solved
		int curTests = 0;

		if( spawnSuccess > 0 )
			spawnRatio = (float)spawnSuccess / (float)spawnAttempt;
		else
			spawnRatio = 1.0f;

		if( spawnRatio < 1.0f && adjustProbability > 0.11f )
			adjustProbability *= 0.85f;
		else if( spawnRatio > 1.0f && adjustProbability < 1.0f )
			adjustProbability *= 1.15f;

		float cr = (float)required*((1.0f-spawnRatio)*3.0f);
		int carry = (int)cr;

		int itemLimit = spawnClass->GetTotalItemLimit();

		// spawn exact number of items
		for( int rCount = 0; rCount < maxTests; rCount++ )
		{
			// real number of attempts
			++spawnAttempt;

			// first item
			WRContainer* spawn = spawnClass->Get(classIdx);
			classIdx = spawnClass->NextIndex(classIdx);

//#ifdef USER_raist
//			WRSpawnItem* item = loot->GetSetup()->GetItem("Tool_FireExtinguisher");
//#else
			WRSpawnItem* item = spawn->GetItemByProbability(adjustProbability);
//#endif
			if( item == NULL )
				continue;

			WRSpawnLocation* loc = spawn->GetRandomLocation();
			if( loc == NULL )
			{
				classIdx = spawnClass->NextIndex(classIdx);
				continue;
			};

			// find container data
			WRLoot_Container* container = g->FindSelection(loc->GetName());
			if( container == NULL )
				continue;

			float minimalHeight = 0.0f;//item->GetClass()->GetBSphere();

			// select proxy
			WRLoot_Point* p = container->GetRandomProxy(WRLoot_Proxy::EPROXY_FREE,minimalHeight);
			if( p == NULL )
				continue;

			p->SetFlags(WRLoot_Proxy::EPROXY_OCCUPIED);

#ifdef USER_raist
			static int counter = 0;
			RptF("__spawn__[%06d] \"%s\", \"%s\"", counter++, item->GetName(), item->GetClass()->GetParent()->GetName() );

			GetWResource()->GetWRDebug()->Project( p->GetOrigin().X(), p->GetOrigin().Z(), 1.0f );
#endif

			// spawn entity
			Entity* veh = SpawnLootObject( item->GetClass(), item->GetName(), p, p->GetOrigin() );
			if( veh == NULL )
			{
				spawnFail++;
				continue;
			};

			GetWResource()->OnAddObject(veh,item);

			loc->OnSpawn();

			// count populated houses
			if( groupPopulated != NULL )
			{
				populatedHouses++;
				groupPopulated = NULL;
			};

			// limit item count
			if( (++spawnSuccess) >= spawnCount )
				break;

			// current group limit
			if( (++curTests) >= (required+carry) )
				break;

			// current item limit
			if( curTests >= itemLimit )
				break;

		};

		// limit item count
		if( spawnSuccess >= spawnCount )
			break;
	};

	GetWResource()->GetWRSpawn()->SetInitialSpawnCount(spawnSuccess);
	GetWResource()->GetWRSpawn()->SetLowSpawnCount(spawnSuccess-1); /*TEST*/

	DWORD end = GetTickCount();
	RptF("LOOT_SPAWN: %d (sec)", (end-start)/1000 );
	RptF("  total on map: %d", totalCount );
	RptF("  within range: %d", withinCount );
	RptF("  spawn requested: %d", spawnCount );
	RptF("  spawn attempts: %d", spawnAttempt );
	RptF("  spawn success: %d", spawnSuccess );
	RptF("  spawn failed: %d", spawnFail );
	RptF("  populated: %d of %d", populatedHouses, totalHouses );

#ifdef USER_raist  
//	GetWResource()->GetWRDebug()->Output("loot.tga");
#endif

	return NOTHING;
}


GameValue SpawnTestProxy(const GameState *state, GameValuePar oper1)
{
	if( !GetWResource() )
		return NOTHING;

	WRLoot* loot = GetWResource()->GetWRLoot();
	if( !loot )
		return NOTHING;

	DWORD start = GetTickCount();

	// parse setup config
	loot->RegisterSetup();

	// check classes
	if( !loot->GetHierarchy() )
	{
		RptF("!!! No class hierarchy available" );
		return NOTHING;
	};

	const GameArrayType& array = oper1;
	if( array.Size() != 2 )
	{
		state->SetError(EvalDim,array.Size(),2);
		return NOTHING;
	}

	// get position
	Vector3 pStart;
	if( !GetPos(state,pStart,array[0]) )
		return NOTHING;

	Vector3 pEnd;
	if( !GetPos(state,pEnd,array[1]) )
		return NOTHING;

	int spawnSuccess = 0;
	int spawnFail = 0;
	int spawnCounter = 0;

	int classCount = loot->GetHierarchy()->GetEndClassCount();

	Vector3 pDir = pEnd-pStart;
	pDir.Normalize(); // let it be 1 meter
	Vector3 pSide = Vector3(pDir.Z(),pDir.Y(),pDir.X());

	Vector3 pCurrent = pStart;

	float offset = 0.0f;

	// process proxy data
	for( int c = 0; c < classCount; c++ )
	{
		WRClassHierarchy* cl = loot->GetHierarchy()->GetEndClass(c);

		Entity* veh = SpawnLootObject( cl, cl->GetName(), NULL, pCurrent );
		if( veh == NULL )
		{
			spawnFail++;
			continue;
		};

		pCurrent += pDir;

		++spawnSuccess;
		if( (++spawnCounter) > 80 )
		{
			pCurrent = pStart;

			static float nextOffset = 5.0f;
			offset += nextOffset;
			pCurrent += (pSide * offset);

			spawnCounter = 0;
		};
	};

	DWORD end = GetTickCount();
	RptF("TEST_SPAWN: %d (sec)", (end-start)/1000 );
	RptF("  spawn success: %d", spawnSuccess );
	RptF("  spawn failed: %d", spawnFail );
	
	return NOTHING;
}



GameValue GetRealSystemTime( const GameState* state )
{
	GameValue retVal = state->CreateGameValue(GameArray);
	GameArrayType& objs = retVal;

	SYSTEMTIME st;
    
    GetSystemTime(&st);
    
//    printf("The system time is: %02d:%02d\n", st.wHour, st.wMinute);

	objs.Add(GameValue((GameScalarType)st.wYear));
	objs.Add(GameValue((GameScalarType)st.wMonth));
	objs.Add(GameValue((GameScalarType)st.wDay));
//	objs.Add(GameValue((GameScalarType)st.wDayOfWeek));
	objs.Add(GameValue((GameScalarType)st.wHour));
	objs.Add(GameValue((GameScalarType)st.wMinute));
//	objs.Add(GameValue((GameScalarType)st.wSecond));

	objs.Compact();
	return retVal;
}

