ConstParamEntryPtr FindSound(RString name, SoundPars &pars);

GameValue SoundPreload(const GameState *state, GameValuePar oper1)
{
  RString name = oper1;
  // make sure given sound file is preloaded (including corresponding .lip file)
  SoundPars pars;
  if (!FindSound(name,pars))
    return true;
  RefAbstractWave snd = GSoundsys->CreateWave(pars.name);
  if (!snd)
    return true;
  if (!snd->PreparePlaying())
    return false;
  
  // if there is any lip file, preload it as well
  #if _ENABLE_NEWHEAD
  return LipSyncInfo::AttachWaveReady(pars.name);
  #else
  return ManLipInfo::AttachWaveReady(pars.name);
  #endif
}

#if _ENABLE_DEDICATED_SERVER
bool IsDedicatedServer();
#endif
bool IsDedicatedClient();

/*!
  \patch 5111 Date 1/2/2007 by Ondra
  - Fixed: preloadCamera and preloadObject always return true on dedicated server.
*/
GameValue CamPreload(const GameState *state, GameValuePar oper1)
{
  Vector3 pos;
  if (!GetPos(state,pos,oper1))
    return false;

#if _ENABLE_DEDICATED_SERVER
  // on a dedicated server we want all preloads to be assumed done
  if (IsDedicatedServer()) return true;
#endif

  //@{ _DEDICATED_CLIENT
  if ( IsDedicatedClient() )
  return true;
  //@}

  //LogF("preloadCamera [%.1f,%.1f,%.1f]",pos.X(),pos.Y(),pos.Z());
  float maxObjDist = floatMin(GScene->GetFogMaxRange(),Glob.config.objectsZ);
  float maxPreloadDist = floatMax(200,maxObjDist*0.66f);
  float timeout = 15;
  bool ret = GLandscape->PreloadData(pos,maxPreloadDist,0.008f,0,NULL,false,timeout);
  if (ret)
  {
    //LogF("Preload finished on (%.1f,%.1f,%.1f)",pos.X(),pos.Y(),pos.Z());
  }
  return ret;
}

/*!
\patch 5161 Date 5/25/2007 by Ondra
- Fixed: MP: Crash when ammo created via createVehicle killed the player.
*/
GameValue VehPreload(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
#if _ENABLE_DEDICATED_SERVER
  // on a dedicated server we want all preloads to be assumed done
  if (IsDedicatedServer()) return true;
#endif
  //@{ _DEDICATED_CLIENT
  if ( IsDedicatedClient() )
  return true;
  //@}

  float distance = oper1;
  if (distance<0.1f) distance = 0.1f;
  FileRequestPriority prior=FileRequestPriority(500);
  Ref<LODShape> shape;
  if (oper2.GetType()==GameObject)
  {
    GameObjectType obj = GetObject(oper2);
    if (!obj) return true;
    shape = obj->GetShape();
    
    Object::ProtectedVisualState<const ObjectVisualState> vs = obj->FutureVisualStateScope();
    
    float scale = vs->Scale();

    float dist2 = Square(distance);
    // shape is initialized now - preload textures
    int level = GScene->PreloadLevelFromDistance2(shape,dist2,scale);
    if (level<0) return false;
    if (level==LOD_INVISIBLE) return true;
    // we need to apply textures ...
    ShapeUsed shapeLevel = shape->Level(level);

    AnimationContextStorageGeom storage;
    AnimationContext animContext(*vs, storage);
    shapeLevel->InitAnimationContext(animContext, shape->GetConvexComponents(level), false);

    obj->Animate(animContext, level, true, obj, -FLT_MAX);

    bool ret = (
      shape->PreloadVBuffer(level,dist2) &&
      shapeLevel->PreloadTextures(dist2, &animContext) &&
      obj->PreloadProxies(level,dist2)
    );

    obj->Deanimate(level,true);
    return ret;
  }
  else if (oper2.GetType()==GameString)
  {
    RString typeName = oper2;

    // check object type based on the shape name
    Ref<EntityType> type = VehicleTypes.New(typeName);
    if (!type)
    {
      return true;
    }
    return type->PreloadData(prior,distance);
  }
  // if arguments are bad, always pretend we are done
  return true;
}

