GameValue SurfaceIsWater(const GameState *state, GameValuePar oper1)
{
  const GameArrayType &array = oper1;
  if (array.Size() != 2 && array.Size() != 3)
  {
    state->SetError(EvalDim, array.Size(), 2);
    return false;
  }
  if (!CheckType(state, array[0], GameScalar)) return false;
  if (!CheckType(state, array[1], GameScalar)) return false;
  // ignore the third parameter

  return GLandscape->SurfaceY(array[0], array[1]) < GLandscape->GetSeaLevel();
}

GameValue SurfaceGetType(const GameState *state, GameValuePar oper1)
{
  const GameArrayType &array = oper1;
  if (array.Size() != 2 && array.Size() != 3)
  {
    state->SetError(EvalDim, array.Size(), 2);
    return RString();
  }
  if (!CheckType(state, array[0], GameScalar)) return RString();
  if (!CheckType(state, array[1], GameScalar)) return RString();
  // ignore the third parameter

  Texture *texture = NULL;
  GLandscape->RoadSurfaceY(array[0], array[1], NULL, NULL, &texture);
  if (!texture) return RString();
  return texture->GetSurfaceInfo()._surfaceType;
}

GameValue SurfaceGetNormal(const GameState *state, GameValuePar oper1)
{
  const GameArrayType &arrayIn = oper1;

  GameValue value = state->CreateGameValue(GameArray);
  GameArrayType &arrayOut = value;
  arrayOut.Resize(3);

  arrayOut[0] = 0.0f;
  arrayOut[1] = 0.0f; 
  arrayOut[2] = 0.0f;

  if (arrayIn.Size() != 2 && arrayIn.Size() != 3)
  {
    state->SetError(EvalDim, arrayIn.Size(), 2);
    return value;
  }
  if (!CheckType(state, arrayIn[0], GameScalar)) return value;
  if (!CheckType(state, arrayIn[1], GameScalar)) return value;
  // ignore the third parameter


  Vector3 normal = GLandscape->SurfaceNormal(arrayIn[0], arrayIn[1]);
  arrayOut[0] = normal.X();
  arrayOut[1] = normal.Z(); 
  arrayOut[2] = normal.Y();

  return value;
}

static bool LoadKey(const FileItem &file, AutoArray<DSKey> &keys)
{
  int index = keys.Add();
  keys[index].Load(file.path + file.filename);
  return false;
}

GameValue SignatureVerify(const GameState *state, GameValuePar oper1)
{
  RString filename = oper1;

  // load all accepted keys
  AutoArray<DSKey> keys;
  // core keys
  ForMaskedFile("Keys\\", "*.bikey", LoadKey, keys);
  // user keys
  RString GetUserDirectory();
  ForMaskedFile(GetUserDirectory() + RString("Keys\\"), "*.bikey", LoadKey, keys);
  ForMaskedFile(RString("Expansion\\Keys\\"), "*.bikey", LoadKey, keys);

LogF("verifySignature for %s (%d accepted keys)", cc_cast(filename), keys.Size());

  // find signature for some accepted key
  DSSignature signature;
  if (!DataSignatures::FindSignature(signature, filename, keys.Data(), keys.Size()))
  {
LogF(" - false - signature not found)", cc_cast(filename), keys.Size());
    return false; // not found
  }
LogF(" - signature found - key %s)", cc_cast(signature._key._name));

  // create hash of tested file
  DSHash hash;
  if (!DataSignatures::GetHash(hash, filename))
  {
LogF(" - false - get hash failed)");
    return false; // error occurred
  }

  // verify signature
  bool ok = DataSignatures::VerifySignature(hash, signature);
if (ok)
  LogF(" - true - signature confirmed");
else
  LogF(" - false - signature not confirmed");

  return ok;
}

static void Eject(Person *man, Transport *trans)
{
  if (!man) return;

  AIBrain *unit = man->Brain();
  if (!unit)
  {
    // SetDelete has no effect for _outVehicles, we need to delete the entity directly
    // man->SetDelete();
    GWorld->RemoveOutVehicle(man);
    return;
  }
  unit->DoGetOut(trans, true, false);
}

/*!
\patch 5153 Date 4/26/2007 by Jirka
- Fixed: MP crash sometimes happened after deleteVehicle on some person
*/

/// Functor ejecting crew member from vehicle
class EjectCrew : public ICrewFunc
{
protected:
  Transport *_vehicle;

public:
  EjectCrew(Transport *vehicle) : _vehicle(vehicle) {}
  bool operator () (Person *person)
  {
    Eject(person, _vehicle);
    return false; // continue
  }
};

void DeleteVehicle(Entity *veh)
{
  // only regular entities may be deleted
  if (veh->Object::GetType()!=TypeVehicle) return;

  if (InventoryItem *item = dyn_cast<InventoryItem>(veh))
  {
    Person* owner = item->GetPersonOwner();

    // remove from the container
    Entity *parent = item->GetHierarchyParent();
    if (parent) parent->RemoveOwnedItem(item);

    // remove shortcut
	  if( owner )
		  owner->RemoveItemShortcut(item);

    // remove from the world
    item->ItemDestroy();
  }
  else if (Person *man = dyn_cast<Person>(veh))
  {
    man->ForEachItem([](InventoryItem *item)->bool
    {
      DoAssert(!item->GetList());
      if (item->GetList())
      {
        item->SetDelete();
      }
      else
      {
        GWorld->RemoveOutVehicle(item);
      }
      NetworkId netId = item->GetNetworkId();
      GetNetworkManager().DeleteObject(netId);
      return false;
    });
    veh->SetDelete();

    //we need to delete the network object so the clients also know that this vehicle does not exist anymore
    NetworkId netId = veh->GetNetworkId();
    GetNetworkManager().DeleteObject(netId);
  }
  else
  {
    // Eject all crew from all turrets, even no local ones
    if (Transport *transport = dyn_cast<Transport>(veh))
    {
      EjectCrew func(transport);
      transport->ForEachCrew(func);
    }
    veh->SetDelete();

    //we need to delete the network object so the clients also know that this vehicle does not exist anymore
    NetworkId netId = veh->GetNetworkId();
    GetNetworkManager().DeleteObject(netId);
  }
}

GameValue VehDelete( const GameState *state, GameValuePar oper1 )
{

  Object *obj = GetObject(oper1);
  if (!obj) return NOTHING;

  if (!obj->GetNetworkId().IsNull() && !GetNetworkManager().IsServerOwner())
  {
    state->AccessError("deleteVehicle");
    return NOTHING;
  }
  Entity *veh = dyn_cast<Entity>(obj);
  if (!veh) return NOTHING;

  DeleteVehicle(veh);
  
  return NOTHING;
}

