GameValue GetFaction(const GameState *state, GameValuePar oper1)
{//returns faction of given unit, empty string if faction isnot defined
  RString faction;
  Object *obj = GetObject(oper1);
  ObjectTyped *ent = dyn_cast<ObjectTyped>(obj);
  if(!ent) return faction;
  //get unit type
  RString type = ent->GetName();
  //faction is defined only for playable sides
  int side =  Pars >> "CfgVehicles" >> type >> "side";
  if(side == TWest || side == TEast || side == TGuerrila || side == TCivilian)
    faction = Pars >> "CfgVehicles" >> type >> "faction";
  
  return faction;
}

GameValue ObjGetOwner(const GameState *state, GameValuePar oper1)
{
  if (!GetNetworkManager().IsServerOwner())
  {
    state->AccessError("owner");
    return NOTHING;
  }

  Object *obj = GetObject(oper1);
  if (!obj) return 0.0f;
  NetworkId id = obj->GetNetworkId();
  if (id.IsNull()) return 0.0f;
  return (float)GetNetworkManager().GetOwner(id);
}

GameValue ObjSetOwner(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  if (!GetNetworkManager().IsServerOwner())
  {
    state->AccessError("setOwner");
    return NOTHING;
  }

  Object *obj = GetObject(oper1);
  if (!obj) return false;
  NetworkId id = obj->GetNetworkId();
  if (id.IsNull()) return false;
  float clientId = oper2;
  return GetNetworkManager().SetOwner(id, toInt(clientId));
}

GameValue SetTargetCategory(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  Object *obj = GetObject(oper1);
  if (!obj) return NOTHING;
  RString cat = oper2;
  EntityAI *veh = dyn_cast<EntityAI>(obj);
  if (!veh) return NOTHING;
  veh->SetTargetCategory(cat);
  return NOTHING;
}

GameValue SetTargetDistanceLimit(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  if (oper1.GetType()==GameString)
  {
    RString catFrom = oper1;
    float distance = oper2;
    GWorld->GetTargetCategories().SetRangeLimit(catFrom,distance);
  }
  else
  {
    const GameArrayType &array = oper1;
    if (!CheckSize(state,array,2)) return NOTHING;
    if (!CheckType(state,array[0],GameString)) return NOTHING;
    if (!CheckType(state,array[1],GameString)) return NOTHING;
    RString catFrom = array[0];
    RString catTgt = array[1];
    float distance = oper2;
    GWorld->GetTargetCategories().SetRangeLimit(catFrom,catTgt,distance);
  }
  return NOTHING;
}



// Get unique player ID derived from CD key. 
// It is supposed to be used by server admins to kick teamKillers more effectively (see news:h17pga$38t$2@new-server.localdomain)
GameValue GetPlayerUID(const GameState *state, GameValuePar oper1)
{
  Object *obj=GetObject(oper1);
  if( !obj ) return RString();
  EntityAI *ai=dyn_cast<EntityAI>(obj);
  if( !ai ) return RString();
  AIBrain *unit=ai->CommanderUnit();
  if( !unit ) return RString();
  Person *person = unit->GetPerson();
  if( !person ) return RString();

  // find PlayerIdentity
  int dpid = -1;
  if ( person->IsRemotePlayer() )
	  dpid = person->GetRemotePlayer();
  else if (person->IsLocal() && unit->IsPlayer())
	  dpid = GetNetworkManager().GetPlayer();
  if (dpid!=-1)
  {
    const PlayerIdentity *identity = GetNetworkManager().FindIdentity(dpid);
    if (identity)
      return identity->id;
  }
  return RString();
}

// Get unique player ID derived from CD key.
GameValue GetClientUID(const GameState *state, GameValuePar oper1)
{
  if (!GetNetworkManager().IsServerOwner())
  {
    state->AccessError("getClientUID");
    return NOTHING;
  }

  if (!CheckType(state,oper1,GameScalar)) return NOTHING;

  int clientId = toInt(float(oper1));

  if (clientId!=-1)
  {
	const PlayerIdentity *identity = GetNetworkManager().FindIdentityByPlayerId(clientId);
    if (identity)
      return identity->id;
  }
  return RString();
};

