GameValue LBSetCurSel( const GameState *state, GameValuePar oper1 )
{
  const GameArrayType &array = oper1;
  if
  (
    array.Size() != 2 ||
    array[0].GetType() != GameScalar ||
    array[1].GetType() != GameScalar
  ) return NOTHING;

  IControl *ctrl = GetCtrl(state, array[0]);
  if (!ctrl) return NOTHING;
  
  int sel = toInt((float)array[1]);
#if !_VBS3 //List box allows to deselect using -1 in VBS3
  // engine can use the special value -1 to make no selection, but we should avoid it in designers level
  if ( sel<0 ) sel=0;
#endif
  int type = ctrl->GetType();
  switch (type)
  {
    case CT_COMBO:
      {
        CCombo *lb = static_cast<CCombo *>(ctrl);
        lb->SetCurSel(sel);
        break;
      }
    case CT_LISTBOX:
      {
        CListBox *lb = static_cast<CListBox *>(ctrl);
        lb->SetCurSel(sel);
        break;
      }
  }
  return NOTHING;
}

