GameValue LNBAddRow( const GameState *state, GameValuePar oper1 )
{
  const GameArrayType &array = oper1;
  if
    (
    array.Size() < 1 ||
    array[0].GetType() != GameScalar
    ) return -1.0f;


  IControl *ctrl = GetCtrl(state, array[0]);
  if (!ctrl) return -1.0f;
  int type = ctrl->GetType();
  if(type != CT_LISTNBOX) return -1.0f;
  CListNBox *lnb = static_cast<CListNBox *>(ctrl);
  if(!lnb) return -1.0f;

  AutoArray<RString> text;
  if(array[1].GetType() == GameArray)
  {
    const GameArrayType &arrayText = array[1];
    for(int i=0; i< arrayText.Size(); i++)
    {
      text.Add(arrayText[i]);
    }
  }
  lnb->AddRow(text);
  return (float)(lnb->RowsCount()-1);
}


GameValue LNBAddArray( const GameState *state, GameValuePar oper1 )
{
  const GameArrayType &arrayIn = oper1;
  if
    (
    arrayIn.Size() < 1 ||
    arrayIn[0].GetType() != GameScalar
    ) return -1.0f;


  IControl *ctrl = GetCtrl(state, arrayIn[0]);
  if (!ctrl) return -1.0f;
  int type = ctrl->GetType();
  if(type != CT_LISTNBOX) return -1.0f;
  CListNBox *lnb = static_cast<CListNBox *>(ctrl);
  if(!lnb) return -1.0f;

  if (!CheckType(state, arrayIn[1], GameArray)) return -1.0f;
  const GameArrayType &array = arrayIn[1];
 
  for(int i=0; i< array.Size(); i++)
  {
    if (!CheckType(state, array[i], GameArray)) return -1.0f;
    const GameArrayType &arrayRow = array[i];

    //read text
    if(arrayRow.Size()>0 && arrayRow[0].GetType() == GameArray)
    {
      AutoArray<RString> text;
      const GameArrayType &arrayText = arrayRow[0];
      for(int i=0; i< arrayText.Size(); i++)
      {
        if (!CheckType(state, arrayText[i], GameString)) return -1.0f;
        text.Add(arrayText[i]);
      }
      lnb->AddRow(text);
    }
    else continue;

    //read values
    if(arrayRow.Size()>1 && arrayRow[1].GetType() == GameArray)
    {
      const GameArrayType &arrayValue = arrayRow[1];
      for(int i=0; i< arrayValue.Size(); i++)
      {
        if (!CheckType(state, arrayValue[i], GameScalar)) return -1.0f;
        float val = arrayValue[i];
        if(i<lnb->NColumns()) lnb->SetValue(lnb->RowsCount()-1,i,val);
      }
    }

    //read data
    if(arrayRow.Size()>2 && arrayRow[2].GetType() == GameArray)
    {
      const GameArrayType &arrayData = arrayRow[2];
      for(int i=0; i< arrayData.Size(); i++)
      {
        if (!CheckType(state, arrayData[i], GameString)) return -1.0f;
        RString data = arrayData[i];
        if(i<lnb->NColumns()) lnb->SetData(lnb->RowsCount()-1,i,data);
      }
    }

  }
  return (float)(lnb->RowsCount()-1);
}


