void ResetPlayerEventHandlers()
{
  GNetworkPlayerDisconnected = GameValue();
  GNetworkPlayerConnected = GameValue();
  GNetworkPlayerConnecting.Clear();
}

struct OnPlayerConnectingContext: private NoCopy
{
  int gshandle;
  GameVarSpace vars;
  OnPlayerConnectingContext(RString uid, int playerId, RString name):vars(false)
  {
    GameState *state = GWorld->GetGameState();
    gshandle = state->BeginContext(&vars);
    state->VarSetLocal("_id", float(playerId), true);
    state->VarSetLocal("_uid", uid, true);
    state->VarSetLocal("_name", name, true);
  }
  ~OnPlayerConnectingContext()
  {
    GameState *state = GWorld->GetGameState();
    state->EndContext(gshandle);
  }

  void Execute(GameValuePar codeValue)
  {
#if USE_PRECOMPILATION
    GameState *state = GWorld->GetGameState();
    DoAssert (codeValue.GetType() == GameCode);
    if (codeValue.GetType() == GameCode)
    {
      GameDataCode *code = static_cast<GameDataCode *>(codeValue.GetData());
      if (code->IsCompiled() && code->GetCode().Size() > 0)
        state->Evaluate(code->GetString(), code->GetCode(), GameState::EvalContext::_default, GWorld->GetMissionNamespace());
    }
#endif
  }
};

void OnPlayerConnecting(int dpnid, RString uid, int playerId, RString name)
{
  if (GWorld->GetGameState() && GNetworkPlayerConnecting.Size()>0)
  {
    OnPlayerConnectingContext ctx(uid,playerId,name);

    for (int i=0; i<GNetworkPlayerConnecting.Size(); i++)
    {
      ctx.Execute(GNetworkPlayerConnecting[i]);
    }
  }
}

void OnPlayerConnecting(int dpnid, RString uid, int playerId, RString name, GameValuePar codeValue)
{
  if (GWorld->GetGameState() && GNetworkPlayerConnecting.Size()>0)
  {
    OnPlayerConnectingContext ctx(uid,playerId,name);
    ctx.Execute(codeValue);
  }
}


