#include <Es/Common/win.h>
GameValue Diag_ExportKB(const GameState *state)
{
  RString dir("KB");

  ::CreateDirectory(dir, NULL);

  {
    // common (shared) informations
    RString filename = dir + RString("\\common.cfg");
    ParamFile out;

    // time
    ParamClassPtr dst = out.AddClass("Times");
    ParamClassPtr cls = dst->AddClass("Now");
    cls->Add("year", Glob.clock.GetYear());
    cls->Add("dayOfYear", toIntFloor(Glob.clock.GetTimeInYear() * 365));
    float tod = 24.0 * Glob.clock.GetTimeOfDay();
    int hour = toIntFloor(tod);
    int minute = toIntFloor(60.0 * (tod - hour));
    if (minute >= 60)
    {
      hour++;
      minute -= 60;
    }
    cls->Add("hour", hour);
    cls->Add("minute", minute);

    // places
    dst = out.AddClass("Places");
    ConstParamEntryPtr src = (Pars >> "CfgWorlds" >> Glob.header.worldname).FindEntry("Names");
    if (src)
    {
      int m = src->GetEntryCount();
      for (int j=0; j<m; j++)
      {
        ParamEntryVal item = src->GetEntry(j);
        float x = (item >> "position")[0];
        float z = (item >> "position")[1];
        RString name = item >> "name";

        ParamClassPtr cls = dst->AddClass(item.GetName());
        cls->Add("name", name);
        ParamEntryPtr array = cls->AddArray("position");
        array->AddValue(x);
        array->AddValue(z);
        array->AddValue(0);
      }
    }

    // entity types
    dst = out.AddClass("EntityTypes");
    src = Pars.FindEntry("CfgVehicles");
    for (int i=0; i<src->GetEntryCount(); i++)
    {
      ParamEntryVal vehEntry = src->GetEntry(i);
      const ParamClass *vehCls = vehEntry.GetClassInterface();
      if (!vehCls) continue;
      RString type = vehEntry >> "vehicleClass";
      if
      (
        stricmp(type, "sounds") == 0 ||
        stricmp(type, "mines") == 0
      ) continue;

      ParamClassPtr cls = dst->AddClass(vehEntry.GetName());
      RString base = vehCls->GetBaseName();
      if (base.GetLength() > 0)
        cls->Add("base", base);
      int scope = vehEntry >> "scope";
      cls->Add("scope", scope);
      RString name = vehEntry >> "displayName";
      cls->Add("name", name);
      int vehSide = vehEntry >> "side";
      RString side = FindEnumName((TargetSide)vehSide);
      cls->Add("side", side);
    }

    out.Save(filename);
  }
  return NOTHING;
}

