template <typename Type>
class DebugQuadTreeWindow: public DebugWindow
{
protected:
  const Type &_quadTree;

public:
  DebugQuadTreeWindow(const char *title, const Type &quadTree);
  virtual void OnPaint(const OnPaintContext &context);
};

template <typename Type>
DebugQuadTreeWindow<Type>::DebugQuadTreeWindow(const char *title, const Type &quadTree)
: DebugWindow(title), _quadTree(quadTree)
{
}

class SelectAll
{
public:
  bool operator ()(int x, int y, int w, int h) const {return true;}
};

class DrawItem
{
protected:
  HDC _dc;

public:
  DrawItem(HDC dc) {_dc = dc;}
  void operator ()(unsigned short value, int x, int y, int w, int h) const;
};

void DrawItem::operator ()(unsigned short value, int x, int y, int w, int h) const
{
  const int size = 3;

  y = LandRange - y - h;
  MoveToEx(_dc, size * x, size * y, NULL);
  LineTo(_dc, size * x, size * (y + h));
  LineTo(_dc, size * (x + w), size * (y + h));
  LineTo(_dc, size * (x + w), size * y);
  LineTo(_dc, size * x, size * y);
}

template <typename Type>
void DebugQuadTreeWindow<Type>::OnPaint(const OnPaintContext &context)
{
  HDC dc = context.dc;
  HWND hwnd = GetWindowHandle(this);
  RECT clientRect;
  GetClientRect(hwnd, &clientRect);

  // erase window
  HBRUSH hbrush = (HBRUSH)GetStockObject(WHITE_BRUSH);
  FillRect(dc, &clientRect, hbrush);

  HPEN oldPen = (HPEN)SelectObject(dc, GetStockObject(BLACK_PEN));

  SelectAll detect;
  DrawItem func(dc);
  _quadTree.ForSomeItem(detect, func);

  SelectObject(dc, oldPen);
}

template <typename Type>
static DebugQuadTreeWindow<Type> *CreateDebugQuadTreeWindow(const char *title, const Type &quadTree)
{
  return new DebugQuadTreeWindow<Type>(title, quadTree);
}

