#define OBJ_AVOID           8.0
#define ROAD_SPACE          1.0
#define OBJ_HEIGHT          2.5
#define OBJ_SPACE_SOLDIER   0.2
#define OBJ_AVOID_SOLDIER   2.0
#define ROAD_SPACE_SOLDIER  0.0
