class DebugOperFieldWindow: public DebugWindow
{
protected:
  LandIndex _x, _z;  
  bool _soldier;

public:
  DebugOperFieldWindow(const char *title, LandIndex x, LandIndex z, bool soldier);
  virtual void OnPaint(const OnPaintContext &context);
};

DebugOperFieldWindow::DebugOperFieldWindow(const char *title, LandIndex x, LandIndex z, bool soldier)
: DebugWindow(title), _x(x), _z(z)
{
  _soldier = soldier;
}

void DebugOperFieldWindow::OnPaint(const OnPaintContext &context)
{
  const int itemSize = 30;
  const int fieldSize = OperItemRange * itemSize;
  const int offset = fieldSize + 30;

  HDC dc = context.dc;
  HWND hwnd = GetWindowHandle(this);
  RECT clientRect;
  GetClientRect(hwnd, &clientRect);

  // erase window
  HBRUSH hbrush = (HBRUSH)GetStockObject(WHITE_BRUSH);
  FillRect(dc, &clientRect, hbrush);

  static const COLORREF typeColor[NOperItemType]=
  {
    RGB(255, 255, 255),     // OITNormal,
    RGB(0, 127, 127), // OITAvoidBush,
    RGB(0, 127, 0),   // OITAvoidTree,
    RGB(127, 0, 0),   // OITAvoid,
    RGB(0, 0, 255),     // OITWater,
    RGB(0, 0, 0),     // OITSpaceRoad,
    RGB(127, 127, 127),     // OITRoad,
    RGB(0, 255, 255),     // OITSpaceBush,
    RGB(0, 255, 127),     // OITSpaceHardBush,
    RGB(0, 255, 0),     // OITSpaceTree,
    RGB(255, 0, 0),     // OITSpace
    RGB(255, 255, 0),     // OITRoadForced
  };

  HPEN oldPen = (HPEN)SelectObject(dc, GetStockObject(NULL_PEN));

  // convex components
  AutoArray<DrawConvexComponentsInfo> result;
  DrawConvexComponents f(_soldier, result);
  ForEachConvexComponent(_x, _z, f, ForComponent<DrawConvexComponents>());
  QSort(result.Data(), result.Size(), CmpConvexComponents);
  for (int i=0; i<result.Size(); i++)
  {
    const DrawConvexComponentsInfo &info = result[i];
    POINT pts[4];
    for (int i=0; i<4; i++)
    {
      pts[i].x = toInt(info.rect[i][0] * itemSize);
      pts[i].y = toInt(fieldSize - info.rect[i][2] * itemSize);
    }

    COLORREF color = typeColor[info.type];
    HBRUSH hbrush = CreateSolidBrush(color);
    HBRUSH oldBrush = (HBRUSH)SelectObject(dc, hbrush);

    Polygon(dc, pts, 4);

    SelectObject(dc, oldBrush);
    DeleteObject(hbrush);
  }

  // rasterized field
  // map will contain one field only, however we have no direct access to the field without the map interface
  OperMap map;
  const OperMapField &field = map.CreateField(_x, _z, MASK_AVOID_OBJECTS | MASK_PREFER_ROADS, NULL, CMSafe, _soldier);
  for (OperFieldIndex j(0); j<OperItemRange; j++)
    for (OperFieldIndex i(0); i<OperItemRange; i++)
    {
      OperItem item = field._operField->GetItem(i, j);
      int type = _soldier ? item.GetTypeSoldier() : item.GetType();
      COLORREF color = typeColor[type];
      RECT rect;
      rect.left = offset + itemSize * i;
      rect.top = itemSize * (OperItemRange - j - 1);
      rect.right = rect.left + itemSize;
      rect.bottom = rect.top + itemSize;
      HBRUSH hbrush = CreateSolidBrush(color);
      FillRect(dc, &rect, hbrush);
      DeleteObject(hbrush);
    }
  
  // grid
  SelectObject(dc, GetStockObject(BLACK_PEN));
  for (int i=0; i<=OperItemRange; i++)
  {
    MoveToEx(dc, itemSize * i, 0, NULL);
    LineTo(dc, itemSize * i, fieldSize);
    MoveToEx(dc, 0, itemSize * i, NULL);
    LineTo(dc, fieldSize, itemSize * i);

    MoveToEx(dc, offset + itemSize * i, 0, NULL);
    LineTo(dc, offset + itemSize * i, fieldSize);
    MoveToEx(dc, offset, itemSize * i, NULL);
    LineTo(dc, offset + fieldSize, itemSize * i);
  }
  SelectObject(dc, oldPen);
}

