#include <fcntl.h>
#include <process.h>
enum {READ_FD, WRITE_FD};
static char BisMapViewerPath[] = "c:\\bis\\mapViewer\\mapViewer.exe";
char * MapViewerargv[] = {NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL};
GameValue Diag_OperFieldSoldierTrap(const GameState *state, GameValuePar oper1)
{
  const GameArrayType &array = oper1;
  if (!CheckSize(state, array, 2)) return NOTHING;
  if (!CheckType(state, array[0], GameScalar)) return NOTHING;
  if (!CheckType(state, array[1], GameScalar)) return NOTHING;
  int _x = toInt((float)array[0]), _z = toInt((float)array[1]);
  // convex components
  AutoArray<TrapConvexComponentsInfo> result;
  TrapConvexComponents f(true, result);
  ForEachConvexComponent(_x, _z, f, ForComponentTrap<TrapConvexComponents>());

  //fdStdInPipe is used to send data to mapViewer, which reads it using stdin
  int fdStdIn;
  //1. save current STDIN
  fdStdIn = _dup(0);
  //2. create anonymous pipe to be STDIN for child process NOINHERITABLE
  //   as write handle must be noinheritable
  int fdStdInPipe[2];
  if(_pipe(fdStdInPipe, 32768, O_TEXT | O_NOINHERIT) == -1) return NOTHING;
  //3. set STDIN of the parent to be the read handle to the pipe, so it is INHERITED
  //   by the child process
  if(_dup2(fdStdInPipe[READ_FD], 0) != 0) return NOTHING;
  //4. close the inheritable read handle
  close(fdStdInPipe[READ_FD]);

  //fill in the commandline parameters for fsmCompiler
  MapViewerargv[0]=BisMapViewerPath;
  MapViewerargv[1]="-stdin";
  //MapViewerargv[2]="-d";
  MapViewerargv[2]=NULL;

  //run MapViewer.exe -stdin
  int hProcess = spawnvp(P_NOWAIT, MapViewerargv[0], MapViewerargv);
  if (hProcess==-1) return NOTHING;
  //feed it with our data
  const char _versionStr[] = "version=1;\nclass ConvexComponents\n{";
  write(fdStdInPipe[WRITE_FD],_versionStr,strlen(_versionStr));
  char _items[256]; sprintf(_items, "\titems=%d;",result.Size());
  write(fdStdInPipe[WRITE_FD],_items,strlen(_items));
  for (int i=0; i<result.Size(); i++)
  {
    char outstr[1204]; sprintf(outstr, "\tclass Item%d\n\t{\n\t\tcolor=%d;\n\t\tpolygon[]={",i,result[i].type);
    for (int j=0; j<result[i].size; j++)
    {
      char newstr[256];
      sprintf(newstr, "%f,%f", result[i].polygon[j][0]*OperItemGrid,result[i].polygon[j][1]*OperItemGrid);
      strcat(outstr,newstr);
      if (j!=result[i].size-1) strcat(outstr, ",");
    }
    strcat(outstr, "};\n\t};");
    write(fdStdInPipe[WRITE_FD],outstr,strlen(outstr));
  }
  const char _endStr[] = "};\n";
  write(fdStdInPipe[WRITE_FD], _endStr, strlen(_endStr));
  //
  close(fdStdInPipe[WRITE_FD]);
  if(_dup2(fdStdIn, 0) == 0) close(fdStdIn);

  return NOTHING;
}

