GameValue Diag_StartVideo(const GameState *state, GameValuePar oper1)
{
  // Ge the array of arguments
  const GameArrayType &array = oper1;

  // Validate argument types
  if (!CheckSize(state, array, 4)) return NOTHING;
  if (!CheckType(state, array[0], GameString)) return NOTHING;
  if (!CheckType(state, array[1], GameString)) return NOTHING;
  if (!CheckType(state, array[2], GameScalar)) return NOTHING;
  if (!CheckType(state, array[3], GameScalar)) return NOTHING;

  // Retrieve the arguments
  RString folderName = array[0];
  RString filePrefix = array[1];
  float frameDuration = array[2];
  float timeToReadResources = array[3];

  // Start video capturing mode
  GWorld->StartVideo(folderName, filePrefix, frameDuration, timeToReadResources);

  return NOTHING;
}

