GameValue GetDate(const GameState *state)
{
  int year, month, day, hour, minute;
  GWorld->GetDate(year, month, day, hour, minute);

  GameValue value = state->CreateGameValue(GameArray);
  GameArrayType &array = value;
  array.Realloc(5);
  array.Resize(5);
  array[0] = (float)year;
  array[1] = (float)month;
  array[2] = (float)day;
  array[3] = (float)hour;
  array[4] = (float)minute;

  return value;
}

GameValue SetDate(const GameState *state, GameValuePar oper1)
{
  const GameArrayType &array = oper1;
  if (!CheckSize(state, array, 5)) return NOTHING;
  for (int i=0; i<5; i++)
    if (!CheckType(state, array[i], GameScalar)) return NOTHING;

  GWorld->SetDate(toInt(safe_cast<float>(array[0])), toInt(safe_cast<float>(array[1])), toInt(safe_cast<float>(array[2])), toInt(safe_cast<float>(array[3])), toInt(safe_cast<float>(array[4])));
  GLandscape->ResetWeather();
#if _VBS3
  // Date change done, update clients
  if(GWorld->GetMode() == GModeNetware) GLandscape->UpdateRemote();
#endif

  return NOTHING;
}

