GameValue DBSaveInt(const GameState *state, GameValuePar oper1)
{
  const GameArrayType &array = oper1;
  if( array.Size() != 3 ) 
  { 
    state->SetError(EvalDim,array.Size(),3);
    return false;
  }

  //if (CheckType(state, array[0], GameString)) return false;
  //if (CheckType(state, array[1], GameString)) return false;
  //if (CheckType(state, array[2], GameScalar)) return false;
  
    RString uid = array[0];
    RString column = array[1];
    GameScalarType no = toInt((float)array[2]);
	int value = (int)no;

///**/	RptF( "DBSaveInt uid: %s, %s == %d", uid.Data(), column, value );
	RString url, attrib;
	BuildServerRequest(ESERVLET_CHARACTER,url,"wint");
	BuildPlayerUID(attrib,uid);

	Person *player = GWorld->PlayerOn();
	if( !player )
		return false;

	JSONDocument document;
	document.SetObject();
	JSONAllocator& allocator = document.GetAllocator();

	// keep some members outside to be consistent with Load
	document.AddMember( "col", cc_cast(column), allocator );
	document.AddMember( "val", value, allocator );

	JSONBuffer buffer;
	JSONWriter writer(buffer);
	document.Accept(writer);

	RString postData = buffer.GetString();

	RString result;

	int err = GetResponse(EHTTPREQ_POST,result,url,attrib,postData);
	if (err >= 400)
	{
		LogF("HTTP Error: %d", err);
		LogF(result);
		return false;
	}
  
	return true;
}


GameValue DBLoadInt(const GameState *state, GameValuePar oper1)
{
  const GameArrayType &array = oper1;
  if( array.Size() != 2 ) 
  { 
    state->SetError(EvalDim,array.Size(),2);
    return 0.0f;
  }

  //if (CheckType(state, array[0], GameString)) return false;
  //if (CheckType(state, array[1], GameString)) return false;
  
    RString uid = array[0];
    RString column = array[1];

///**/	RptF( "DBSaveInt uid: %s, %s == %d", uid.Data(), column, value );

	RString url, attrib;
	BuildServerRequest(ESERVLET_CHARACTER,url,"rint");
	BuildPlayerUID(attrib,uid);

	Person *player = GWorld->PlayerOn();
	if( !player )
		return 0.0f;

	JSONDocument document;
	document.SetObject();
	JSONAllocator& allocator = document.GetAllocator();

	// keep some members outside to be consistent with Load
	document.AddMember( "col", cc_cast(column), allocator );

	JSONBuffer buffer;
	JSONWriter writer(buffer);
	document.Accept(writer);

	RString postData = buffer.GetString();

	RString result;
	int err = GetResponse(EHTTPREQ_POST,result,url,attrib,postData);
	if( err >= 400 || result.IsEmpty() )
	{
		LogF("HTTP Error: %d", err);
		LogF(result);
		return 0.0f;
	}

	// parse
	document.Parse<rapidjson::kParseDefaultFlags>(result);
	if( !document.Empty() )
	{
		JSONValue& value = document["int"];
		if( !value.IsDouble() )
		{
			float f = value.GetInt();
			return f;
		};
	};
  
	return 0.0f;
}


