GameValue DBServerSaveCharacter(const GameState *state, GameValuePar oper1)
{
  if (!GetNetworkManager().IsServerOwner())
  {
    state->AccessError("dbServerSaveCharacter");
    return false;
  }

  if (oper1.GetType() == GameObject)
  {
    Object *obj = GetObject(oper1);
    Person *person = dyn_cast<Person>(obj);
    if (!person) return false;

    int dpnid;
    if (GetNetworkManager().IsServer())
    {
      dpnid = person->GetRemotePlayer();
      if (dpnid == AI_PLAYER) return false;
    }
    else
    {
      dpnid = 2; // BOT_CLIENT
      if (person != GWorld->PlayerOn()) return false;
    }

    JSONDocument document;
    document.SetObject();
    JSONAllocator& allocator = document.GetAllocator();

    // keep some members outside to be consistent with Load
    document.AddMember("model", cc_cast(person->GetType()->GetName()), allocator);
    document.AddMember("alive", person->Brain() && person->Brain()->LSIsAlive() ? 1 : 0, allocator);
    person->JSONSave(document, allocator);

    JSONBuffer buffer;
    JSONWriter writer(buffer);
    document.Accept(writer);

    RString request = buffer.GetString();

	RString url/*, attrib*/;
	BuildServerRequest(ESERVLET_CHARACTER,url,"save");
//	BuildPlayerUID(attrib,uid);

	return GetNetworkManager().DBSave(url.Data(), dpnid, request);
  }
  else
  {
    DoAssert(oper1.GetType() == GameArray);
    const GameArrayType &array = oper1;
    if (!CheckSize(state, array, 2)) return false;
    if (!CheckType(state, array[0], GameString)) return false;
    if (!CheckType(state, array[1], GameObject)) return false;

    RString uid = array[0];
    Person *person = dyn_cast<Person>(GetObject(array[1]));
    if (!person) return false;

    JSONDocument document;
    document.SetObject();
    JSONAllocator& allocator = document.GetAllocator();

    // keep some members outside to be consistent with Load
    document.AddMember("model", cc_cast(person->GetType()->GetName()), allocator);
    document.AddMember("alive", person->Brain() && person->Brain()->LSIsAlive() ? 1 : 0, allocator);
    person->JSONSave(document, allocator);

    JSONBuffer buffer;
    JSONWriter writer(buffer);
    document.Accept(writer);

    RString request = buffer.GetString();

	RString url, attrib;
	BuildServerRequest(ESERVLET_CHARACTER,url,"save");
	BuildPlayerUID(attrib,uid);

    return GetNetworkManager().DBSave(url.Data(),attrib,request);
  }
}


GameValue DBGetServerConfig(const GameState *state)
{
	RptF( "DBGetServerConfig" );

	RString url;
	BuildServerRequest(ESERVLET_WORLD,url,"sys");

	int stateCurrent = 200;
	int stateNext = 400;
	int stateTimeout = 0;

	float timeOffset = 0.0f;
	float timeScale = 0.0f;

	RString result;
	int err = GetResponse(EHTTPREQ_POST,result,url,NULL,NULL);
	if( err >= 400 )
	{
		LogF("HTTP Error: %d", err);
		LogF(result);

		stateCurrent = 400;
	};

	if( stateCurrent != 400 )
	{

		// parse
		JSONDocument document;
		document.Parse<rapidjson::kParseDefaultFlags>(result);

		if( result.IsEmpty() || document.Empty() )
		{
			stateCurrent = 400;
		}
		else
		{
			JSONValue& valueSCurrent = document["scurr"];
			if( valueSCurrent.IsInt() )
			{
				stateCurrent = valueSCurrent.GetInt();

				JSONValue& valueSNext = document["snext"];
				if( valueSNext.IsInt() )
				{
					stateNext = valueSNext.GetInt();

					JSONValue& valueSTime = document["stime"];
					if( valueSTime.IsInt() )
					{
						stateTimeout = valueSTime.GetInt();

						JSONValue& valueTOffset = document["toffset"];
						if( valueTOffset.IsDouble() )
						{
							timeOffset = valueTOffset.GetDouble();

							JSONValue& valueTScale = document["tscale"];
							if( valueTScale.IsDouble() )
							{
								timeScale = valueTScale.GetDouble();
							};

						};
					};
				};
			};
		};

	};

	// return data
	GameValue retVal = state->CreateGameValue(GameArray);
	GameArrayType& objs = retVal;

	objs.Add(GameValue((GameScalarType)stateCurrent));
	objs.Add(GameValue((GameScalarType)stateNext));
	objs.Add(GameValue((GameScalarType)stateTimeout));
	objs.Add(GameValue((GameScalarType)timeOffset));
	objs.Add(GameValue((GameScalarType)timeScale));
	//	objs.Compact();

	return retVal;
}


GameValue DBFindCharacter(const GameState *state, GameValuePar oper1)
{
    GameStringType uid = oper1;
/**/	RptF( "DBFindCharacter uid: %s", uid.Data() );

	RString url, attrib;
	BuildServerRequest(ESERVLET_CHARACTER,url,"find");
	BuildPlayerUID(attrib,uid);

	bool isAlive = true;
	bool isOnline = true;

	int queueTag = 0;

	float x = 0.0f;
	float y = 0.0f;
	float z = 0.0f;

	RString result;
	int err = GetResponse(EHTTPREQ_POST,result,url,attrib,NULL);
	if( err >= 400 )
	{
		LogF("HTTP Error: %d", err);
		LogF(result);
		
		isAlive =
			isOnline = false;
	};

	if( isAlive && isOnline )
	{

		// parse
		JSONDocument document;
		document.Parse<rapidjson::kParseDefaultFlags>(result);

		if( result.IsEmpty() || document.Empty() )
		{
			isAlive = false;
		}
		else
		{
			JSONValue& value = document["model"];
			if( !value.IsString() )
			{
				isAlive = false;
			}
			else
			{
				RString model = value.GetString();

				rapidjson::Value &arr = document["pos"];
				if( !arr.IsArray() || arr.Size() != 3 )
				{
					isAlive = false;
				}
				else
				{
					x = arr[rapidjson::SizeType(0)].GetDouble();
					y = arr[rapidjson::SizeType(1)].GetDouble();
					z = arr[rapidjson::SizeType(2)].GetDouble();

					//rapidjson::Value &arr = document["dir"];
					//if( !arr.IsArray() || arr.Size() != 3 )
					//{
					//	isAlive = false;
					//}
					//else
					//{
					//	x = arr[rapidjson::SizeType(0)].GetDouble();
					//	y = arr[rapidjson::SizeType(1)].GetDouble();
					//	z = arr[rapidjson::SizeType(2)].GetDouble();
					//};

				};

				JSONValue& value = document["queue"];
				if( value.IsInt() )
				{
					queueTag = value.GetInt();
				}

			};
		};

	};

	// return data
	GameValue retVal = state->CreateGameValue(GameArray);
	GameArrayType& objs = retVal;

	objs.Add(GameValue((GameBoolType)isAlive));
	objs.Add(GameValue((GameBoolType)isOnline));
	objs.Add(GameValue((GameScalarType)x));
	objs.Add(GameValue((GameScalarType)y));
	objs.Add(GameValue((GameScalarType)z));
	objs.Add(GameValue((GameScalarType)queueTag));
//	objs.Compact();

	return retVal;
}


