GameValue DBServerLoadCharacter(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  if (!GetNetworkManager().IsServerOwner())
  {
    state->AccessError("dbServerLoadCharacter");
    return NOTHING;
  }

  int playerID = toInt(oper1);

  GameDataCode *code = static_cast<GameDataCode *>(oper2.GetData());

  RString url;
  BuildServerRequest(ESERVLET_CHARACTER,url,"load");

  GetNetworkManager().DBLoad(url.Data(), playerID, code);

  return NOTHING;
}


GameValue DBLoadCharacter(const GameState *state, GameValuePar oper1)
{

	GameStringType uid = oper1;
///**/	RptF( "DBLoadCharacter uid: %s", uid.Data() );

	RString url, attrib;
	BuildServerRequest(ESERVLET_CHARACTER,url);
	BuildPlayerUID(attrib,uid);

#if _ENABLE_INDEPENDENT_AGENTS

  RString result;
  int err = GetResponse(EHTTPREQ_GET,result,url,attrib,NULL);
  if (err >= 400)
  {
    LogF("HTTP Error: %d", err);
    LogF(result);
    return false;
  }

  JSONDocument document;
  document.Parse<rapidjson::kParseDefaultFlags>(result);

  if (document.HasParseError() || document.Empty())
	  return false;

  JSONValue &value = document["model"];
  if (!value.IsString())
	  return false;

  RString model = value.GetString();

  // simplified vehicle creation
  Ref<Entity> veh = GWorld->NewNonAIVehicleWithID(model, RString());
  Person *person = dyn_cast<Person>(veh.GetRef());
  if (!person)
	  return false;

  if (!person->JSONLoad(document))
	  return false;

  GWorld->AddVehicle(person);
  GetNetworkManager().CreateVehicle(person, VLTVehicle, "", -1);
  person->Init(person->FutureVisualState().Transform(), true);

  person->UpdateSubobjects();
  GetNetworkManager().UpdateObject(person);

  return true;
#endif

//  return false;
}

GameValue Diag_LoadCharacter(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{

#if _ENABLE_INDEPENDENT_AGENTS
  if (!CheckType(state,oper1,GameArray)) return OBJECT_NULL;

  const GameArrayType &array = oper1;
  if (!CheckSize(state,array,3)) return OBJECT_NULL;

  Vector3 pos;
  if (!FindObjectPosition(state, pos, array[0], array[1], array[2])) return OBJECT_NULL;

  JSONDocument document;
  RString source = oper2;

  document.Parse<rapidjson::kParseDefaultFlags>(source);

  if (document.HasParseError() || document.Empty())
	  return OBJECT_NULL;

  JSONValue &value = document["model"];
  if (!value.IsString())
	  return OBJECT_NULL;

  RString model = value.GetString();

  // simplified vehicle creation
  Ref<Entity> veh = GWorld->NewNonAIVehicleWithID(model, RString());
  Person *person = dyn_cast<Person>(veh.GetRef());
  if (!person)
	  return OBJECT_NULL;

  person->SetPosition(pos);

  if (!person->JSONLoad(document,false))
	  return OBJECT_NULL;

  GWorld->AddVehicle(person);
  GetNetworkManager().CreateVehicle(person, VLTVehicle, "", -1);
  person->Init(person->FutureVisualState().Transform(), true);

  //person->UpdateSubobjects();
  //GetNetworkManager().UpdateObject(person);

  return GameValueExt(person);
#else
  return OBJECT_NULL;
#endif
}

