GameValue FireAtTarget(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  if (!GetNetworkManager().IsServerOwner())
  {
    state->AccessError("fireAtTarget");
    return false;
  }

  Object *obj = GetObject(oper1);
  if (!obj) return false;
  EntityAIFull *vehicle = dyn_cast<EntityAIFull>(obj);
  if (!vehicle) return false;
  AIBrain *brain = vehicle->CommanderUnit();
  if (!brain || !brain->GetVehicleIn()) return false;
  Transport *vehicleIn = brain->GetVehicleIn();

  TurretContextV fireContext;
  if(!vehicleIn->GetPrimaryGunnerTurret(unconst_cast(vehicleIn->FutureVisualState()), fireContext)) return false;

  EntityAI *target = NULL; 
  WeaponModePtr selected;
  // check the right argument - array of vehicles (avoid adding only some objects from the list)
  const GameArrayType &array = oper2;
  if(array.Size()>=1)
  {
    if (!CheckType(state, array[0], GameObject)) return false;
    obj = GetObject(array[0]);
    if (obj) target = dyn_cast<EntityAI>(obj);
  }

  if (array.Size()>=2)
  {
    if (!CheckType(state, array[1], GameString)) return false;
    RString weaponName = array[1];
    
    // scan all muzzles
    fireContext._weapons->ForEachMuzzle([&selected, weaponName](const WeaponModePtr &ptr) -> bool
    {
      // check muzzle
      const MuzzleType *muzzle = ptr.GetMuzzleType();
      if (muzzle && stricmp(muzzle->GetName(), weaponName) == 0)
      {
        selected = ptr;
        return true; // done
      }
      return false; // continue
    });
  }
  else selected = fireContext._weapons->ValidatedCurrentWeapon();

  if (!selected.IsValid()) return false;

  vehicleIn->FireWeapon(fireContext, selected, target, true);

  return true;
}

GameValue AimedAtTarget(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  Object *obj = GetObject(oper1);
  if (!obj)   return 0.0f;
  EntityAIFull *vehicle = dyn_cast<EntityAIFull>(obj);
  if (!vehicle)   return 0.0f;
  AIBrain *brain = vehicle->CommanderUnit();
  if (!brain || !brain->GetVehicleIn())   return 0.0f;
  Transport *vehicleIn = brain->GetVehicleIn();

  TurretContextV fireContext;
  if(!vehicleIn->GetPrimaryGunnerTurret(unconst_cast(vehicleIn->FutureVisualState()), fireContext))   return 0.0f;

  EntityAI *target = NULL; 
  WeaponModePtr ptr;
  // check the right argument - array of vehicles (avoid adding only some objects from the list)
  const GameArrayType &array = oper2;
  if(array.Size()>=1)
  {
    if (!CheckType(state, array[0], GameObject))   return 0.0f;
    obj = GetObject(array[0]);
    if (!obj)   return 0.0f;
    target = dyn_cast<EntityAI>(obj);
  }

  if(array.Size()>=2)
  {
    if (!CheckType(state, array[1], GameString)) return false;
    RString weaponName = array[1];

    // scan all muzzles
    fireContext._weapons->ForEachMuzzle([&ptr, weaponName](const WeaponModePtr &p) -> bool
    {
      // check muzzle
      const MuzzleType *muzzle = p.GetMuzzleType();
      if (muzzle && stricmp(muzzle->GetName(), weaponName) == 0)
      {
        ptr = p;
        return true; // done
      }
      return false; // continue
    });
  }
  else ptr = fireContext._weapons->ValidatedCurrentWeapon();
  if (!ptr.IsValid() || !target) return 0.0f;

  Ref<TargetMinimal> targetTmp = new TargetMinimal(target);
  float aimed =  vehicleIn->GetAimed(fireContext, ptr, targetTmp);
  return aimed;
}

