GameValue CurrentZeroing(const GameState *state, GameValuePar oper1)
{  
  Object *obj = GetObject(oper1);
  Person *person = dyn_cast<Person>(obj);
  if(!person) return 0.0f;

  AIBrain *agent = person->Brain();
  if(!agent) return 0.0f;

  TurretContext context;
  EntityAIFull *vehicle = agent->GetVehicle();
  if(!vehicle) return 0.0f;

  if (!vehicle->FindTurret(agent->GetPerson(), context)) return 0.0f;

  WeaponModePtr ptr = context._weapons->ValidatedCurrentWeapon();
  if (!ptr.IsValid()) return 0.0f;

  if(agent->IsFreeSoldier() && agent->GetVehicle())
  {
    const OpticsInfo *opticsInfo = ptr.GetOpticsInfo();
    DoAssert(opticsInfo);

    float distance = 0;
    if (opticsInfo->_discreteDistance.Size() == 0)
    {
      distance= Interpolativ(agent->GetVehicle()->GetCameraFOV(), opticsInfo->_opticsZoomMin, opticsInfo->_opticsZoomMax,
        opticsInfo->_distanceZoomMin, opticsInfo->_distanceZoomMax);
    }
    else
    {
      return opticsInfo->_discreteDistance[std::min(ptr.GetDiscreteDistanceIndex(), opticsInfo->_discreteDistance.Size()-1)];
    }
  }
  else
  {
    const MuzzleType *muzzle = ptr.GetMuzzleType();

    if (muzzle && (muzzle->_ballisticsComputer == 1 ||  muzzle->_ballisticsComputer == 2)
      && context._turretType->_discreteDistance.Size()>0 && context._turret->_distanceIndex >=0) 
    {
      return  context._turretType->_discreteDistance[std::min(context._turret->_distanceIndex,context._turretType->_discreteDistance.Size()-1)];
    }
  }
  return 0.0f;
}

GameValue CurrentVisionMode(const GameState *state, GameValuePar oper1)
{
  Object *obj = GetObject(oper1);
  Person *person = dyn_cast<Person>(obj);
  if(!person) return 0.0f;

  AIBrain *agent = person->Brain();
  if(!agent) return 0.0f;

  if (GEngine->GetThermalVisionWanted()) return 2.0f;
  else 
    if (person->IsNVWanted()) return 1.0f;
    else return 0.0f;
}

