GameValue AddCamShake(const GameState *state, GameValuePar oper1)
{
  // Ge the array of arguments
  const GameArrayType &array = oper1;

  // Validate argument types
  if (!CheckSize(state, array, 3)) return NOTHING;
  if (!CheckType(state, array[0], GameScalar)) return NOTHING;
  if (!CheckType(state, array[1], GameScalar)) return NOTHING;
  if (!CheckType(state, array[2], GameScalar)) return NOTHING;

  GWorld->GetCameraShakeManager().AddSource(CameraShakeSource::CSNone, array[0], array[1],  array[2], 0);
  return NOTHING;
}

GameValue SetCamShakeParams(const GameState *state, GameValuePar oper1)
{
  // Ge the array of arguments
  const GameArrayType &array = oper1;

  if (array.Size() > 0)
  {
    if (!CheckType(state, array[0], GameScalar)) return NOTHING;
    CameraShakeManager::PosChangeCoef = array[0];
  }
  if (array.Size() > 1)
  {
    if (!CheckType(state, array[1], GameScalar)) return NOTHING;
    CameraShakeManager::RotXChangeCoef = array[1];
  }
  if (array.Size() > 2)
  {
    if (!CheckType(state, array[2], GameScalar)) return NOTHING;
    CameraShakeManager::RotYChangeCoef = array[2];
  }
  if (array.Size() > 3)
  {
    if (!CheckType(state, array[3], GameScalar)) return NOTHING;
    CameraShakeManager::RotZChangeCoef = array[3];
  }
  if (array.Size() > 4)
  {
    if (!CheckType(state, array[4], GameBool)) return NOTHING;
    CameraShakeManager::PerformLERP = array[4];
  }

  return NOTHING;
}

GameValue SetCamShakeDefParams(const GameState *state, GameValuePar oper1)
{
  // Ge the array of arguments
  const GameArrayType &array = oper1;

  if (array.Size() > 0)
  {
    if (!CheckType(state, array[0], GameScalar)) return NOTHING;
    CameraShakeManager::DefaultPower = array[0];
  }
  if (array.Size() > 1)
  {
    if (!CheckType(state, array[1], GameScalar)) return NOTHING;
    CameraShakeManager::DefaultDuration = array[1];
  }
  if (array.Size() > 2)
  {
    if (!CheckType(state, array[2], GameScalar)) return NOTHING;
    CameraShakeManager::DefaultMaxDistance = array[2];
  }
  if (array.Size() > 3)
  {
    if (!CheckType(state, array[3], GameScalar)) return NOTHING;
    CameraShakeManager::DefaultFrequency = array[3];
  }
  if (array.Size() > 4)
  {
    if (!CheckType(state, array[4], GameScalar)) return NOTHING;
    CameraShakeManager::DefaultMinSpeed = array[4];
  }
  if (array.Size() > 5)
  {
    if (!CheckType(state, array[5], GameScalar)) return NOTHING;
    CameraShakeManager::DefaultMinMass = array[5];
  }
  if (array.Size() > 6)
  {
    if (!CheckType(state, array[6], GameScalar)) return NOTHING;
    CameraShakeManager::DefaultCaliberCoefPlayerHit = array[6];
  }
  if (array.Size() > 7)
  {
    if (!CheckType(state, array[7], GameScalar)) return NOTHING;
    CameraShakeManager::DefaultCaliberCoefWeaponFire = array[7];
  }
  if (array.Size() > 8)
  {
    if (!CheckType(state, array[8], GameScalar)) return NOTHING;
    CameraShakeManager::DefaultPassingVehicleCoef = array[8];
  }

  return NOTHING;
}

