GameValue EntityInventoryTakeInHands(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  if (!GetNetworkManager().IsServerOwner())
  {
    state->AccessError("takeInHands");
    return false;
  }
  InventoryItem *item = dyn_cast<InventoryItem>(GetObject(oper2));
  if (!item) return false;

  Object *obj = GetObject(oper1);
  Person *person = dyn_cast<Person>(obj);
  if (person)
  {
    DoAssert(!person->GetInSlot(ISHands));
    person->PutInSlot(ISHands, item);
    person->TakeItemToHands(item);
	return true;
  }
  return false;
}

