GameValue ObjIsTouchingGround(const GameState *state, GameValuePar oper1)
{

  //expecting object
  if (!CheckType(state, oper1, GameObject)) return false;

  Object *obj = GetObject(oper1);
  Entity *entity = dyn_cast<Entity>(obj);
  if (!entity) return false;

  //staic entities are objects like crates, fences,...
  if (entity->Static())
  {
    Matrix4 trans = obj->WorldTransform(obj->FutureVisualState());
    entity->PlaceOnSurface(trans);
    float yOffset = entity->FutureVisualState().Position().Y()-trans.Position().Y();
    return yOffset < 0.01;
  }
  //vehicles, units
  else
    return entity->IsLandContact();

}

