/*!
\patch 5139 Date 3/13/2007 by Jirka
- Fixed: function setMousePosition is working correctly again (broken when HW cursors was introduced)
*/

#ifdef _WIN32
#include <El/Interfaces/iAppInfo.hpp>
extern WINDOW_HANDLE hwndApp;
#include <Es/Common/win.h>
#endif

GameValue SetMousePosition(const GameState *state, GameValuePar oper1)
{
  const GameArrayType &array = oper1;
  if (!CheckSize(state, array, 2)) return NOTHING;
  if (!CheckType(state, array[0], GameScalar)) return NOTHING;
  if (!CheckType(state, array[1], GameScalar)) return NOTHING;
  float x = array[0];
  float y = array[1];
  
  // software cursor position
  GInput.cursorX = 2.0f * x - 1.0f;
  GInput.cursorY = 2.0f * y - 1.0f;
  
#if defined(_WIN32) 
  // hardware cursor position
  // convert from UI area to client coordinates
  AspectSettings as;
  GEngine->GetAspectSettings(as);
  int clientX = toInt(GEngine->Width() * (as.uiTopLeftX + x * (as.uiBottomRightX - as.uiTopLeftX)));
  int clientY = toInt(GEngine->Height() * (as.uiTopLeftY + y * (as.uiBottomRightY - as.uiTopLeftY)));
  // convert from client coordinates to virtual desktop
  if (!GEngine->IsWindowed())
  {
    int offsetX, offsetY;
    GEngine->MonitorOffset(offsetX, offsetY);
    SetCursorPos(clientX + offsetX, clientY + offsetY);
    GEngine->UpdateCursorPos(clientX + offsetX, clientY + offsetY);
  }
  else
  {
    POINT screenPoint; screenPoint.x = clientX; screenPoint.y = clientY;
    ClientToScreen((HWND)hwndApp, &screenPoint);
    SetCursorPos(screenPoint.x, screenPoint.y);
  }
#endif
  return NOTHING;
}

