/*!
\patch 5124 Date 1/29/2007 by Jirka
- Fixed: When the script change the player using "selectPlayer" function from the dead one, game info about the mission state is changed as well.
*/

GameValue SelectPlayer(const GameState *state, GameValuePar oper1)
{
  //RptF("*** SelectPlayer START");
  Object *obj = GetObject(oper1);
  EntityAI *veh = dyn_cast<EntityAI>(obj);
  if (!veh) 
  {
#if _VBS3
    GWorld->SwitchCameraTo(NULL, GWorld->GetCameraType(), true);
    GWorld->SwitchPlayerTo(NULL);
    GWorld->SetRealPlayer(NULL);
#endif
    return NOTHING;
  }

  if (GetNetworkManager().IsMultiplayer())
  {
    RptF("Access to a local player not possible with client-server");
    return NOTHING;
  }

  //NetworkId mid = veh->GetNetworkId();
  //RptF(" %d:%" OID_FORMAT" LastSimulationTime = %.3f (%.3f)", mid.creator.CreatorInt(), mid.id, veh->GetLastSimulationTime().toFloat(), veh->GetSimSkip());

  AIBrain *unit = veh->CommanderUnit();
  if (!unit) return NOTHING;

  Glob.header.playerSide = veh->GetTargetSide();
  if (GWorld->GetMode() == GModeIntro)
  {
    GWorld->SwitchCameraTo(unit->GetVehicle(), CamExternal, true);
  }
  else
  {
    GWorld->SwitchCameraTo(unit->GetVehicle(), (GInput.perspective==1) ? CamInternal : CamExternal, true);

    GStats._playerInfo.unit = unit;

    // keep rank and exp. from editor
    if (GWorld->GetMode() == GModeNetware)
    {
      PlayerInfo().rank = unit->GetPerson()->GetInfo()._rank;
      PlayerInfo().experience = unit->GetPerson()->GetExperience();
    }

    Person *personNew = unit->GetPerson();

    GWorld->SetPlayerManual(true);
    GWorld->SwitchPlayerTo(personNew);
    GWorld->SetRealPlayer(personNew);

    GetNetworkManager().SendSelectPlayer( GetNetworkManager().GetPlayer(), unit->GetPerson() );
    if (GWorld->GetEEndMode() == EMKilled) GWorld->SetEndMode(CAST_TO_ENUM(EEndMode, EMContinue));
  }

  //RptF("*** SelectPlayer END");
  return NOTHING;
}

GameValue SelectNoPlayer(const GameState *state)
{
  //! There should be always some player inside MP as it could break the mission logic otherwise
  if (GWorld->GetMode() != GModeNetware)
  {
  GWorld->SwitchCameraTo(NULL, GWorld->GetCameraType(), true);
  GWorld->SwitchPlayerTo(NULL);
  GWorld->SetRealPlayer(NULL);
  }
  return NOTHING;
}

GameValue ObjSelectPlayer(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  if (!GetNetworkManager().IsServer())
  {
    if (!GetNetworkManager().IsServerOwner())
    {
      state->AccessError("id selectPlayer obj");
      return NOTHING;
    }
    else
    {
      // for singleplayer, redirect to original selectPlayer
      SelectPlayer(state, oper2);
      return NOTHING;
    }
  }

  int clientId = toInt(safe_cast<float>(oper1));

  Object *obj = GetObject(oper2);
  Person *veh = dyn_cast<Person>(obj);
  if (!veh) return NOTHING;

  AIBrain *unit = veh->CommanderUnit();
  if (!unit) return NOTHING;

  const PlayerIdentity *identity = GetNetworkManager().FindIdentityByPlayerId(clientId);
  if (!identity) return NOTHING;

  int dpnid = identity->dpnid;

  GetNetworkManager().ServerSelectPlayer(dpnid,veh);

  if (dpnid==GetNetworkManager().GetPlayer())
  {
    // when executed for the bot client, we need to set local camera as well
    GWorld->SwitchCameraTo(unit->GetVehicle(), (GInput.perspective==1) ? CamInternal : CamExternal, true);

    GWorld->SetPlayerManual(true);
    GWorld->SwitchPlayerTo(veh);
    GWorld->SetRealPlayer(veh);
    if (GWorld->GetEEndMode() == EMKilled) GWorld->SetEndMode(CAST_TO_ENUM(EEndMode, EMContinue));
  }

  return NOTHING;
}


