GameValue StringLoad(const GameState *state, GameValuePar oper1)
{
  if (!GetNetworkManager().IsServerOwner())
  {
    state->AccessError("loadFile");
    return RString();
  }
  QIFStreamB in;
  if (OpenScript(in,oper1))
  {
    HandleUnicode handleUnicode(in);
    QIStream &inputData = handleUnicode(); 

    AutoArray<char> buf;
    WriteAutoArrayChar writeBuf(buf);
    inputData.Process(writeBuf);
    
    return RString(buf.Data(),buf.Size());
  }
  return RString();
}

GameValue StringPreprocess(const GameState *state, GameValuePar oper1)
{
  /*
  if (!GetNetworkManager().IsServerOwner())
  {
    state->AccessError("preprocessFile");
    return RString();
  }
  */
  RString filename = FindScript(oper1);
  if (filename.GetLength() == 0) return RString();

  FilePreprocessor preproc;
  QOStrStream processed;
  if (preproc.Process(&processed,filename))
  {
    return RString(processed.str(),processed.pcount());
  }
  return RString();
}

GameValue StringPreprocessLineNumbers(const GameState *state, GameValuePar oper1)
{
  /*
  if (!GetNetworkManager().IsServerOwner())
  {
    state->AccessError("preprocessFileLineNumbers");
    return RString();
  }
  */
  RString filename = FindScript(oper1);
  if (filename.GetLength() == 0) return RString();

  FilePreprocessor preproc(true);
  QOStrStream processed;
  if (preproc.Process(&processed, filename))
  {
    return RString(processed.str(), processed.pcount());
  }
  return RString();
}

