static GameValue VMSleep(const GameState *state, GameValuePar oper1)
{
#if USE_PRECOMPILATION
  float delay = oper1;
  VMContext *context = state->GetVMContext();
  // 1 operand is over bottom of stack
  CallStackItem *level = new CallStackItemSleep(
    context->GetCallStack(), context->GetVariables(), context->_stack.Size() - 1, state, 
    delay, context->IsSerializationEnabled());
  context->AddLevel(level);
  return NOTHING;
#else
  return NOTHING;
#endif
}

static GameValue UISleep(const GameState *state, GameValuePar oper1)
{
#if USE_PRECOMPILATION
  float delay = oper1;
  VMContext *context = state->GetVMContext();
  // 1 operand is over bottom of stack
  CallStackItem *level = new CallStackItemUISleep(
    context->GetCallStack(), context->GetVariables(), context->_stack.Size() - 1, state, 
    delay, context->IsSerializationEnabled());
  context->AddLevel(level);
  return NOTHING;
#else
  return NOTHING;
#endif
}

