GameValue TxtText(const GameState *state, GameValuePar oper1)
{
  GameTextType text = CreateTextASCII(NULL, oper1);
  return GameValueExt(text,GameValExtINode);
}

GameValue TxtCompose(const GameState *state, GameValuePar oper1)
{
  // check types of array items
  const GameArrayType &array = oper1;
  int n = array.Size();
  GameType type = GameString | GameText;
  for (int i=0; i<n; i++)
  {
    if (!(array[i].GetType() & type))
    {
      state->TypeError(type, array[i].GetType());
      return TEXT_NULL;
    }
  }

  GameTextType text = CreateTextStructured(NULL);
  for (int i=0; i<n; i++)
  {
    GameTextType subtext = GetTextValue(array[i]);
    if (subtext) text->Add(subtext);
  }

  return GameValueExt(text,GameValExtINode);
}

GameValue TxtParse(const GameState *state, GameValuePar oper1)
{
  GameTextType text = CreateTextStructured(NULL, oper1);
  return GameValueExt(text,GameValExtINode);
}

INode *FormatText(const char *format, RefR<INode> *args, int nArgs, bool structured)
{
  INode *result = CreateTextStructured(NULL);
  char c;
  char buffer[2048];
  char *dst = buffer;

  while ((c = *format) != 0)
  {
    if (c == '%')
    {
      format++;
      if (*format != '%')
      {
        int index = 0;
        while (isdigit(*format))
        {
          index *= 10;
          index += *format - '0';
          format++;
        }
        if (index < 1 || index > nArgs) continue;

        // add text
        *dst = 0;
        if (structured) CreateTextStructured(result, buffer);
        else CreateTextASCII(result, buffer);
        dst = buffer;

        // add parameter
        if (args[index - 1]) result->Add(args[index - 1]);
        continue;
      }
    }
    // %% or not % char
    *dst = c;
    format++;
    dst++;
  }
  if (dst != buffer)
  {
    // remaining text
    *dst = 0;
    if (structured) CreateTextStructured(result, buffer);
    else CreateTextASCII(result, buffer);
  }
  return result;
}

GameValue TxtFormat(const GameState *state, GameValuePar oper1)
{
  // check types of array items
  const GameArrayType &array = oper1;
  int n = array.Size();
  if (n < 1)
  {
    state->SetError(EvalDim, array.Size(), 2);
    return TEXT_NULL;
  }
  if (!CheckType(state, array[0], GameString)) return NOTHING;

  AUTO_STATIC_ARRAY(RefR<INode>, args, 32);
  for (int i=1; i<array.Size(); i++)
  {
    if (!array[i].GetNil() && array[i].GetType() == GameText)
    {
      GameTextType text = static_cast<GameDataText *>(array[i].GetData())->GetValue();
      args.Add(text);
    }
    else if (array[i].GetType() == GameString)
    {
      args.Add(CreateTextASCII(NULL, array[i]));
    }
    else
    {
      args.Add(CreateTextASCII(NULL, array[i].GetText()));
    }
  }

  RString format = array[0];
  GameTextType result = FormatText(format, args.Data(), args.Size(), false);
  return GameValueExt(result,GameValExtINode);
}

GameValue TxtSetAttributes(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  GameTextType text = GetTextValue(oper1);
  if (!text) return TEXT_NULL;
  const GameArrayType &array = oper2;
  int n = array.Size();
  if (n % 2 != 0)
  {
    state->SetError(EvalDim, array.Size(), 2);
    return TEXT_NULL;
  }
  for (int i=0; i<n; i++)
    if (!CheckType(state, array[i], GameString)) return NOTHING;

  for (int i=0; i<n; i++)
  {
    RString name = array[i++];
    RString value = array[i];

    SetTextAttribute(text, name, value);
  }
  return GameValueExt(text,GameValExtINode);
}

