{
  return oper1.IsEqualTo(oper2);
}

GameValue TextCmpNE(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  return !oper1.IsEqualTo(oper2);
}

bool ParseUserParams(ParamFile &cfg, GameDataNamespace *globals);
void SaveUserParams(ParamFile &cfg);

GameValue KeyActivate(const GameState *state, GameValuePar oper1)
{
  RString key = oper1;
  GameDataNamespace globals(NULL, RString(), false); // save - no global namespace
  ParamFile cfg;
  if (ParseUserParams(cfg, &globals))
  {
    ParamEntryPtr array = cfg.FindEntry("activeKeys");
    if (array)
    {
      for (int i=0; i<array->GetSize(); i++)
      {
        RString value = (*array)[i];
        if (stricmp(value, key) == 0) return NOTHING;
      }
    }
    else
    {
      array = cfg.AddArray("activeKeys");
    }
    array->AddValue(key);
    SaveUserParams(cfg);
  }
  return NOTHING;
}

GameValue IsKeyActive(const GameState *state, GameValuePar oper1)
{
  RString key = oper1;
  GameDataNamespace globals(NULL, RString(), false); // save - no global namespace
  ParamFile cfg;
  if (ParseUserParams(cfg, &globals))
  {
    ParamEntryPtr array = cfg.FindEntry("activeKeys");
    if (array)
    {
      for (int i=0; i<array->GetSize(); i++)
      {
        RString value = (*array)[i];
        if (stricmp(value, key) == 0) return true;
      }
    }
  }
  return false;
}

GameValue KeyDeActivate(const GameState *state, GameValuePar oper1)
{
  RString key = oper1;
  GameDataNamespace globals(NULL, RString(), false); // save - no global namespace
  ParamFile cfg;
  if (ParseUserParams(cfg, &globals))
  {
    ParamEntryPtr array = cfg.FindEntry("activeKeys");
    if (array)
    {
      for (int i=0; i<array->GetSize(); i++)
      {
        RString value = (*array)[i];
        if (stricmp(value, key) == 0) 
        { //key found, deactivate it (delete)
          array->DeleteValue(i);
          SaveUserParams(cfg);
          break;
        }
      }
    }
  }
  return NOTHING;
}

GameValue StrIsLocalized(const GameState *state, GameValuePar oper1)
{
  GameStringType name = oper1;
  if (name.GetLength() == 0) return false;
  if (name[0] == '@')
  {
    RString result = TryLocalizeString((const char *)name + 1);
    if (result.GetLength() > 0) return true;
  }
  else
  {
    return IsLocalized(name);
  }
  return false;
}

GameValue GetArmoryPoints(const GameState *state)
{
  GameDataNamespace globals(NULL, RString(), false); // save - no global namespace
  ParamFile cfg;
  if (!ParseUserParams(cfg, &globals)) return 0.0f;

  ConstParamEntryPtr entry = cfg.FindEntry("armoryPoints");
  if (!entry) return 0.0f;

  float armoryPoints = *entry;
  return armoryPoints;
}

GameValue SetArmoryPoints(const GameState *state, GameValuePar oper1)
{
  GameDataNamespace globals(NULL, RString(), false); // save - no global namespace
  ParamFile cfg;
  if (ParseUserParams(cfg, &globals))
  {
    float armoryPoints = oper1;
    cfg.Add("armoryPoints", armoryPoints);
    SaveUserParams(cfg);
  }
  return NOTHING;
}

GameValue ObjGetVectorUp(const GameState *state, GameValuePar oper1)
{
  Object *obj = GetObject(oper1);

  GameValue value = state->CreateGameValue(GameArray);
  GameArrayType &array = value;
  array.Resize(3);
  if (obj)
  {
    Vector3Val up = obj->FutureVisualState().DirectionUp();
    array[0] = up.X();
    array[1] = up.Z();
    array[2] = up.Y();
  }
  else
  {
    array[0] = 0.0f; array[1] = 0.0f; array[2] = 0.0f;
  }
  return value;
}

