GameValue AgentMoveTo(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  Object *obj = GetObject(oper1);
  EntityAI *veh = dyn_cast<EntityAI>(obj);
  if (!veh) return NOTHING;
  AIBrain *agent = veh->PilotUnit();
  if (!agent) return NOTHING;

  Vector3 pos;
  if (!GetPosATL(state, pos, oper2)) return NOTHING;

  if (agent->GetState() == AIBrain::Completed) agent->SetState(AIBrain::Wait);
  // TODO: accept precision as an optional argument
  float precision = 0;
  agent->SetWantedPosition(PlanPosition(pos,false), precision, AIBrain::LeaderPlanned, true);
  return NOTHING;
}

