GameValue EntitySynchronizeVariable(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  if (!GetNetworkManager().IsServerOwner()) return NOTHING;
  Object *obj = GetObject(oper1);
  EntityAI *veh = dyn_cast<EntityAI>(obj);
  if (!veh) return NOTHING;

  // [name, importance]
  const GameArrayType &array = oper2;
  GameDataCode code;
  if (array.Size()==3)
  {
    if (!CheckType(state, array[2], GameCode)) return NOTHING;
    code = *static_cast<GameDataCode *>(array[2].GetData());
  }
  else
  {
    if (!CheckSize(state, array, 2)) return NOTHING;
  }
  // name
  if (!CheckType(state, array[0], GameString)) return NOTHING;
  RString name = array[0];
  // importance
  if (!CheckType(state, array[1], GameScalar)) return NOTHING;
  float coef = array[1];

  veh->SynchronizeVariable(name, coef, code);
  return NOTHING;
}

