GameValue SetVehicleTiPars(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  if (oper2.GetType() != GameArray)
  {
    state->TypeError(GameArray, oper2.GetType());
    return NOTHING;
  }

  const GameArrayType &array = oper2;

  if (array.Size() != 3) 
  {
    state->SetError(EvalDim, array.Size(), 3);
    return NOTHING;
  }

  Transport *veh = dyn_cast<Transport>(GetObject(oper1));
  if (veh)
  {
    float alive = array[0];
    float movement = array[1];
    float metabolism = array[2];

    saturate(alive, 0.0f, 1.0f);
    saturate(movement, 0.0f, 1.0f);
    saturate(metabolism, 0.0f, 1.0f);

    veh->SetAliveFactor(alive);
    veh->SetMovementFactor(movement);
    veh->SetMetabolismFactor(metabolism);
  }

  return NOTHING;
}

GameValue SetAperture(const GameState *state, GameValuePar oper1)
{
  // convert from aperture diameter to linear values
  if (GWorld)
  {
    float invDiameter = oper1;
    if (invDiameter<=0)
    {
      GWorld->SetEyeAccom(-1);
    }
    else
    {
      float apertureArea = Square(1/invDiameter);
      GWorld->SetEyeAccom(apertureArea);
    }
  }
  return NOTHING;
}

