GameValue GetNearObjectsReady(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  // until not found opposite, expect all is ready
  bool ready = true;

  // read the parameters
  Vector3 pos;
  if (!GetPos(state, pos, oper1)) return true;
  float radius = oper2;

  // decide the x, z range objects need to be checked in
  int xMin, xMax, zMin, zMax;
  ObjRadiusRectangle(xMin, xMax, zMin, zMax, pos, pos, radius);
  for (int z = zMin; z <= zMax; z++)
    for (int x = xMin; x <= xMax; x++)
    {
      Landscape::PreloadResult result = GLandscape->PreloadObjects(FileRequestPriority(10), x, z);
      if (result == Landscape::PreloadRequested) ready = false; // give a change to other fields to preload
    }
  return ready;
}

GameValue GetNearObjects(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  GameValue value = state->CreateGameValue(GameArray);
  GameArrayType &array = value;

  Vector3 pos;
  if (!GetPos(state, pos, oper1)) return value;

  Ref<EntityType> type;
  float radius;
  if (oper2.GetType() == GameArray)
  {
    const GameArrayType &array = oper2;
    if (!CheckSize(state, array, 2)) return value;
    if (!CheckType(state, array[0], GameString)) return value;
    if (!CheckType(state, array[1], GameScalar)) return value;
  
    RString typeName = array[0];
    type = VehicleTypes.New(typeName);
    if (!type) return value;

    radius = array[1];
  }
  else
  {
    DoAssert(oper2.GetType() == GameScalar);
    radius = oper2;
  }

  int xMin, xMax, zMin, zMax;
  ObjRadiusRectangle(xMin, xMax, zMin, zMax, pos, pos, radius);
  for (int x=xMin; x<=xMax; x++) for (int z=zMin; z<=zMax; z++)
  {
    const ObjectListUsed &list = GLandscape->UseObjects(x, z);
    int n = list.Size();
    for (int i=0; i<n; i++)
    {
      ObjectTyped *obj = dyn_cast<ObjectTyped>(list[i]);
      if (!obj) continue;

      float dist2 = obj->FutureVisualState().Position().Distance2(pos);
      if (dist2 > Square(radius)) continue;
      if (type && !(obj->Type() && obj->Type()->IsKindOf(type))) continue;

      array.Add(GameValueExt(obj));
    }
  }
  array.Compact();
  return value;
}

