class ScanNearEntitiesQuery: public World::ObjectQuery
{
protected:
  GameArrayType &_results;
  const Array< Ref<EntityType> > &_types;

public:
  ScanNearEntitiesQuery(GameArrayType &results, const Array< Ref<EntityType> > &types)
    : _results(results), _types(types)
  {
  }

  bool Check(Object* obj) const
  {
    EntityAI* entity = dynamic_cast<EntityAI*>(obj);
    if(!entity) return false;
    if (entity->IsDamageDestroyed()) return false;
    if (entity->GetType()->IsSlow()) return false; // static object or inventory item
    return true;
  }
  bool operator()(Object* obj) const
  {
    Entity* veh = static_cast<EntityAI*>(obj);

    if (_types.Size() > 0)
    {
      if (veh->Type())
      {
        for (int i=0; i<_types.Size(); i++)
        {
          if (veh->Type()->IsKindOf(_types[i]))
          {
            _results.Add(GameValueExt(veh));
            break;
          }
        }
      }
    }
    else
    {
      _results.Add(GameValueExt(veh));
    }
    return true;
  }
};

GameValue GetNearEntities(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  GameValue value = state->CreateGameValue(GameArray);
  GameArrayType &array = value;

  // read arguments

  // position
  Vector3 pos;
  if (!GetPos(state, pos, oper1)) return value;
  RefArray< EntityType, MemAllocLocal<Ref<EntityType>, 32> > types;
  float radius;

  if (oper2.GetType() == GameArray)
  {
    // type(s)
    const GameArrayType &array = oper2;
    if (!CheckSize(state, array, 2)) return value;
    if (array[0].GetType() == GameString)
    {
      RString typeName = array[0];
      Ref<EntityType> type = VehicleTypes.New(typeName);
      if (type) types.Add(type);
    }
    else if (array[0].GetType() == GameArray)
    {
      const GameArrayType &subarray = array[0];
      for (int i=0; i<subarray.Size(); i++)
      {
        RString typeName = subarray[i];
        Ref<EntityType> type = VehicleTypes.New(typeName);
        if (type) types.Add(type);
      }
    }
    else
    {
      state->TypeError(GameArray, array[0].GetType());
    }
    if (types.Size() == 0) return value;

    // radius
    if (!CheckType(state, array[1], GameScalar)) return value;
    radius = array[1];
  }
  else
  {
    // radius
    DoAssert(oper2.GetType() == GameScalar);
    radius = oper2;
  }

  ScanNearEntitiesQuery query(array, types);
  GWorld->QueryObjects(query, pos, radius, World::QF_DYNAMIC|World::QF_ORIGIN_DISTANCE);
  /*
  //test for compare results
  GameValue value2 = state->CreateGameValue(GameArray);
  GameArrayType &array2 = value2;

  ScanNearEntities func(array2, types, pos, radius);
  GWorld->ForEachVehicle(func);
  if(array2.Size() != array.Size())
  {
    ScanNearEntitiesQuery query(array, types);
    GWorld->QueryObjects(query, pos, radius, World::QF_DYNAMIC|World::QF_ORIGIN_DISTANCE);
  }
  */
  return value;
}

GameValue GetNearRoads(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  GameValue value = state->CreateGameValue(GameArray);
  GameArrayType &array = value;

  // check the parameters
  Vector3 pos;
  if (!GetPos(state, pos, oper1)) return value;
  float radius = oper2;

  int xMin, xMax, zMin, zMax;
  ObjRadiusRectangle(xMin, xMax, zMin, zMax, pos, pos, radius);
  for (int x=xMin; x<=xMax; x++) for (int z=zMin; z<=zMax; z++)
  {
    const ObjectListUsed &list = GLandscape->UseObjects(x, z);
    int n = list.Size();
    for (int i=0; i<n; i++)
    {
      // filter roads only
      Object *obj = list[i];
      if (!obj || obj->GetType() != Network) continue;

      // check the distance
      float dist2 = obj->FutureVisualState().Position().Distance2(pos);
      if (dist2 > Square(radius)) continue;

      // found
      array.Add(GameValueExt(obj));
    }
  }
  array.Compact();
  return value;
}

GameValue GetConnectedRoads(const GameState *state, GameValuePar oper1)
{
  GameValue value = state->CreateGameValue(GameArray);
  GameArrayType &array = value;

  // check the parameters
  Object *obj = GetObject(oper1);
  if (!obj) return value;

  // find the corresponding RoadLink object
  const RoadLink *road = NULL;
  Vector3 pos = obj->WorldPosition(obj->FutureVisualState());
  int xx = toIntFloor(pos.X() * InvLandGrid);
  int zz = toIntFloor(pos.Z() * InvLandGrid);
  const RoadList &list = GLandscape->GetRoadNet()->GetRoadList(xx, zz);
  for (int i=0; i<list.Size(); i++)
  {
    const RoadLink *link = list[i];
    if (link && link->GetObject() == obj)
    {
      road = link;
      break;
    }
  }
  if (!road)
  {
    RptF("Warning: roadsConnectedTo did not found the input road segment");
    // TODO: recover if needed (search a bit around)
    return value;
  }

  for (int i=0; i<road->NConnections(); i++)
  {
    const RoadLink *link = road->Connections()[i];
    if (!link) continue;
    Object *obj = link->GetObject();
    array.Add(GameValueExt(obj));
  }
  return value;
}

GameValue ObjGetSelectionPosition(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  Object *obj = GetObject(oper1);
  RString name = oper2;

  GameValue value = state->CreateGameValue(GameArray);
  GameArrayType &array = value;
  array.Resize(3);
  array[0] = 0.0f; array[1] = 0.0f; array[2] = 0.0f;
  
  if (!obj) return value;
  LODShape *lodShape = obj->GetShape();
  if (!lodShape) return value;
  
  // first check the memory level
  int levels[] =
  {
    lodShape->FindMemoryLevel(),
    lodShape->FindGeometryLevel(),
    lodShape->FindFireGeometryLevel(),
    lodShape->FindLandContactLevel(),
    lodShape->FindHitpoints(),
  };

  for (int i=0; i<lenof(levels); i++)
  {
    int level = levels[i];
    if (level < 0) continue;

    const Shape *shape = lodShape->GetLevelLocked(level);
    if (shape)
    {
      int index = lodShape->PointIndex(shape, name);
      if (index < 0) return value;
      Vector3 pos = obj->AnimatePoint(obj->RenderVisualState(),level, index);
      array[0] = pos.X(); array[1] = pos.Z(); array[2] = pos.Y();
      return value;
    }
  }
  // not found
  return value;
}

GameValue ObjModelToWorld(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  GameValue value = state->CreateGameValue(GameArray);
  GameArrayType &array = value;
  array.Resize(3);
  array[0] = 0.0f; array[1] = 0.0f; array[2] = 0.0f;

  Object *obj = GetObject(oper1);
  if (!obj) return value;
  Vector3 modelPos;
  if (!GetRelPos(state, modelPos, oper2)) return value;

  Vector3 worldPos = obj->FutureVisualState().PositionModelToWorld(modelPos);
  array[0] = worldPos.X();
  array[1] = worldPos.Z();
  array[2] = worldPos.Y() - GLandscape->SurfaceYAboveWater(worldPos.X(), worldPos.Z());
  return value;
}

GameValue ObjWorldToModel(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  GameValue value = state->CreateGameValue(GameArray);
  GameArrayType &array = value;
  array.Resize(3);
  array[0] = 0.0f; array[1] = 0.0f; array[2] = 0.0f;

  Object *obj = GetObject(oper1);
  if (!obj) return value;
  Vector3 worldPos;
  if (!GetPos(state, worldPos, oper2)) return value;

  Vector3 modelPos(VFastTransform, obj->FutureVisualState().GetInvTransform(), worldPos);
  array[0] = modelPos.X(); array[1] = modelPos.Z(); array[2] = modelPos.Y();
  return value;
}

GameValue ObjLimitSpeed(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  Object *obj = GetObject(oper1);
  EntityAI *entity = dyn_cast<EntityAI>(obj);
  if (!entity) return NOTHING;
  
  float speed = oper2;
  entity->LimitSpeedForced((1.0f / 3.6f) * speed); // convert to m/s
  return NOTHING;
}

GameValue ObjSetVariable(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  Object *obj = GetObject(oper1);
  if (!obj) return NOTHING;

  const GameArrayType &array = oper2;
  if (!CheckSize(state, array, 2)) return NOTHING;

  if (!CheckType(state, array[0], GameString)) return NOTHING;

  RString name = array[0];

  obj->SetVariable(name,array[1]);

  return NOTHING;
}

GameValue ObjGetVariable(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  Object *obj = GetObject(oper1);
  if (!obj) return NOTHING;

  if (oper2.GetType() == GameString)
  {
    RString name = oper2;
    GameVarSpace *vars = obj->GetVars();
    if (vars)
    {
      name.Lower();
      GameValue var;
      if (vars->VarGet(name, var)) return var;
    }
    return NOTHING;
  }
  else if (oper2.GetType() == GameArray)
  {
    const GameArrayType &array = oper2;
    if (!CheckSize(state, array, 2)) return NOTHING;
    if (!CheckType(state, array[0], GameString)) return NOTHING;
    RString name = array[0];
    GameVarSpace *vars = obj->GetVars();
    if (vars)
    {
      name.Lower();
      GameValue var;
      if (vars->VarGet(name, var)) return var;
    }
    return  array[1];
  }
  return NOTHING;
}

GameValue VehGetExpectedDestination(const GameState *state, GameValuePar oper1)
{
  GameValue value = state->CreateGameValue(GameArray);
  GameArrayType &array = value;

  Object *obj = GetObject(oper1);
  EntityAI *veh = dyn_cast<EntityAI>(obj);
  if (veh)
  {
    AIBrain *unit = veh->PilotUnit();
    if (unit)
    {
      PlanPosition position;
      AIBrain::PlanningMode planningMode;
      bool forceReplan;
      float precision;
      unit->GetExpectedDestination(position, precision, planningMode, forceReplan);
      
      array.Realloc(3);
      array.Resize(3);
      
      array[0] = state->CreateGameValue(GameArray);
      GameArrayType &posArray = array[0];
      posArray.Realloc(3);
      posArray.Resize(3);
      posArray[0] = position.X();
      posArray[1] = position.Z();
      posArray[2] = position.Y() - GLandscape->SurfaceYAboveWater(position.X(), position.Z());

      RString mode = FindEnumName(planningMode);
      array[1] = mode;

      array[2] = forceReplan;
    }
  }

  return value;
}

GameValue VehSetDestination(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  Object *obj = GetObject(oper1);
  EntityAI *veh = dyn_cast<EntityAI>(obj);
  if (!veh) return NOTHING;
  
  const GameArrayType &array = oper2;
  if (!CheckSize(state, array, 3)) return NOTHING;
  Vector3 position;
  if (!GetPos(state, position, array[0])) return NOTHING;
  if (!CheckType(state, array[1], GameString)) return NOTHING;
  RString mode = array[1];

  int modeInt = GetEnumValue<AIBrain::PlanningMode>(cc_cast(mode));
  if (modeInt==INT_MIN)
  {
    LogF("%s: setDestination: wrong planning mode '%s'",cc_cast(obj->GetDebugName()),cc_cast(mode));
    modeInt = AIBrain::DoNotPlan;
  }
      
  AIBrain::PlanningMode planningMode = (AIBrain::PlanningMode)modeInt;

  if (!CheckType(state, array[2], GameBool)) return NOTHING;
  bool forceReplan = array[2];

  AIBrain *brain = veh->PilotUnit();
  if (!brain) return NOTHING;
  //AIUnit *unit = brain->GetUnit();
  //if (unit && unit->IsSubgroupLeaderVehicle()) return NOTHING;

  brain->SetWantedDestination(PlanPosition(position,false), planningMode, forceReplan);

  return NOTHING;
}

