GameValue VehFindNearestEnemy(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  Object *obj = GetObject(oper1);
  if (!obj) return OBJECT_NULL;
  EntityAIFull *ai=dyn_cast<EntityAIFull>(obj);
  if( !ai ) return OBJECT_NULL;

  Vector3 pos;
  if (!GetPos(state, pos, oper2)) return OBJECT_NULL;

  Target *target = ai->FindNearestEnemy(pos);
  if (target) return GameValueExt(target->idExact, GameValExtObject);
  return OBJECT_NULL;
}

static void CopyPos2Array(GameArrayType &array, Vector3Par pos)
{
  array[0] = pos.X();
  array[1] = pos.Z();
  array[2] = pos.Y() - GLandscape->SurfaceYAboveWater(pos.X(), pos.Z());
}

GameValue VehGetHideFrom(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  GameValue value = state->CreateGameValue(GameArray);
  GameArrayType &array = value;
  array.Resize(3);
  do {
    Object *obj = GetObject(oper1);
    if (!obj) break;
    EntityAIFull *ai=dyn_cast<EntityAIFull>(obj);
    if( !ai ) break;
    Object *enemy = GetObject(oper2);
    if (!enemy) 
    { // if not, we hide in formation direction
      float radius = ai->GetType()->GetMaxSpeedMs() * 20;
      saturate(radius, 20, 500);
      Vector3 hidePos = ai->FutureVisualState().Position() + ai->FutureVisualState().Direction() * radius;
      CopyPos2Array(array, hidePos);
      return value;
    }
    // what position do we hide from
    // if there is explicit hide target, we hide from it
    AIBrain *agent = ai->CommanderUnit();
    if (!agent) break;
    EntityAI *enemyAI = dyn_cast<EntityAI>(enemy);
    if (!enemyAI) break;
    Target *hideTarget = agent->FindTarget(enemyAI);
    if (hideTarget)
    {
      Vector3 hidePos = hideTarget->AimingPosition();
      CopyPos2Array(array, hidePos);
      return value;
    }
  } while (false);
  array[0] = 0.0f; array[1] = 0.0f; array[2] = 0.0f;
  return value;
}

GameValue VehFindCover(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  Object *obj = GetObject(oper1);
  EntityAIFull *veh = dyn_cast<EntityAIFull>(obj);
  if (!veh) return OBJECT_NULL;

  const GameArrayType &array = oper2;
  if (array.Size() < 3)
  {
    state->SetError(EvalDim, array.Size(), 3);
    return OBJECT_NULL;
  }
  if (!CheckType(state, array[0], GameArray) && !CheckType(state, array[0], GameObject)) return OBJECT_NULL;
  Vector3 pos; GetPos(state, pos, array[0]);
  if (!CheckType(state, array[1], GameArray) && !CheckType(state, array[1], GameObject)) return OBJECT_NULL;
  Vector3 hidePos; GetPos(state, hidePos, array[1]);

  // optional parameters - position to have visibility to
  Vector3 watchPos = VZero; Object *ignore = NULL;
  if (array.Size() > 4)
  {
    if (!CheckType(state, array[4], GameArray)) return OBJECT_NULL;
    GetPos(state, watchPos, array[4]);  
    if (array.Size() > 5)
    {
      ignore = GetObject(array[5]);
      if (!ignore) return OBJECT_NULL;
    }
  }

  //TODO: it should be decided whether to get radius as another oper2 array parameter
  float radius=veh->GetType()->GetMaxSpeedMs()*20;
  saturate(radius,20,500);

  if (!CheckType(state, array[2], GameScalar)) return OBJECT_NULL;
  float maxDist = array[2];
  if (maxDist <= 0) maxDist = radius*0.25f;
  float minDist = 0;
  if (array.Size() == 4)
  {
    if (!CheckType(state, array[3], GameScalar)) return OBJECT_NULL;
    minDist = array[3];
    if (minDist < 0) minDist = 0;
  }
  
  RptF("MicroAI: Command findCover not implemented (%s)",cc_cast(veh->GetDebugName()));
  return OBJECT_NULL;
  // return CreateGameObject(veh->FindCover(pos, pos, hidePos, radius, maxDist, minDist, watchPos, ignore));
}

GameValue VehSuppressFor(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  Object *obj = GetObject(oper1);
  EntityAIFull *veh = dyn_cast<EntityAIFull>(obj);
  if (!veh) return NOTHING;
  // if the unit is a soldier commanding a vehicle, set the vehicle flag instead
  if (veh->CommanderUnit())
  {
    EntityAIFull *inVeh = veh->CommanderUnit()->GetVehicle();
    if (inVeh) veh = inVeh;
  }
  // suppress
  veh->SuppressUntil(Glob.time+oper2);
  return NOTHING;
}

