GameValue LibraryCredits(const GameState *state)
{
  GameValue value = state->CreateGameValue(GameArray);
  GameArrayType &array = value;

  int nCredits = CountCredits();  
  array.Realloc(nCredits);
  array.Resize(nCredits);
  for (int i=0; i<nCredits; i++)
  {
    GameValue itemValue = state->CreateGameValue(GameArray);
    GameArrayType &itemArray = itemValue;
    itemArray.Realloc(2);
    itemArray.Resize(2);
    const CreditsInfo &credits = GetCredits(i);
    itemArray[0] = GameStringType(credits.name);
    itemArray[1] = GameStringType(credits.copyright);
    array[i] = itemValue;
  }
  return value;
}

GameValue LibraryDisclaimers(const GameState *state)
{
  FindArray<RString> disclaimers;
  int nCredits = CountCredits();  
  for (int i=0; i<nCredits; i++)
  {
    const CreditsInfo &credits = GetCredits(i);
    RString disclaimer = credits.disclaimer;
    if (disclaimer.IsEmpty()) continue;
    disclaimers.AddUnique(disclaimer);
  }

  GameValue value = state->CreateGameValue(GameArray);
  GameArrayType &array = value;

  array.Realloc(disclaimers.Size());
  array.Resize(disclaimers.Size());
  for (int i=0; i<disclaimers.Size(); i++)
  {
    array[i] = GameStringType(disclaimers[i]);
  }
  return value;
}


