GameValue ConfigGetBase(const GameState *state, GameValuePar oper1)
{
  GameConfigType const *parent = GetConfig(oper1);
  GameConfigType result;
  if (parent && parent->entry && parent->entry->IsClass())
  {
    ConstParamEntryPtr base = parent->entry->FindBase();
    if (base)
    {
      result.entry = base;
      result.path.Resize(0);
      do
      {
        result.path.Insert(0, base->GetName());
        base = base->FindParent();
      } while(base);
      result.path.Compact();
    }
  }
  return GameValueExt(result);
}

GameValue ConfigCount(const GameState *state, GameValuePar oper1)
{
  GameConfigType const *parent = GetConfig(oper1);
  if (parent && parent->entry && parent->entry->IsClass()) return (float)parent->entry->GetEntryCount();
  else return 0.0f;
}

GameValue ConfigSelect(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  GameConfigType const *parent = GetConfig(oper1);
  GameConfigType result;
  if (parent && parent->entry && parent->entry->IsClass())
  {
    int index = toInt(safe_cast<float>(oper2));
    if (index >= 0 && index < parent->entry->GetEntryCount())
    {
      result.entry = &parent->entry->GetEntry(index);
      int n = parent->path.Size();
      result.path.Realloc(n + 1);
      result.path.Resize(n + 1);
      for (int i=0; i<n; i++) result.path[i] = parent->path[i];
      result.path[n] = result.entry->GetName();
    }
    else
    {
      // run time error
      state->SetError(EvalGen);
    }
  }
  return GameValueExt(result);
}

