static void ExtractArray(const GameState *state, GameArrayType &array, const IParamArrayValue &entry)
{
  int n = entry.GetItemCount();
  array.Realloc(n);
  array.Resize(n);
  for (int i=0; i<n; i++)
  {
    const IParamArrayValue &value = entry[i];
    if (value.IsTextValue())
      array[i] = value.GetValue();
    else if (value.IsFloatValue() || value.IsIntValue())
      array[i] = value.GetFloat();
    else if (value.IsArrayValue())
    {
      array[i] = state->CreateGameValue(GameArray);
      ExtractArray(state, array[i], value);
    }
  }
}

static void ExtractArray(const GameState *state, GameArrayType &array, ConstParamEntryPtr entry)
{
  int n = entry->GetSize();
  array.Realloc(n);
  array.Resize(n);
  for (int i=0; i<n; i++)
  {
    const IParamArrayValue &value = (*entry)[i];
    if (value.IsTextValue())
      array[i] = value.GetValue();
    else if (value.IsFloatValue() || value.IsIntValue())
      array[i] = value.GetFloat();
    else if (value.IsArrayValue())
    {
      array[i] = state->CreateGameValue(GameArray);
      ExtractArray(state, array[i], value);
    }
  }
}

GameValue ConfigGetArray(const GameState *state, GameValuePar oper1)
{
  GameValue value = state->CreateGameValue(GameArray);
  GameArrayType &array = value;

  GameConfigType const *parent = GetConfig(oper1);
  if (parent && parent->entry && parent->entry->IsArray())
    ExtractArray(state, array, parent->entry);

  return value;
}

