GameValue KBAddTopic(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
#if _ENABLE_CONVERSATION
  // check parameters
  Object *obj = GetObject(oper1);
  RString name, filename, taskType;
  // executed when player is addressed
  GameValue eventHandler;

  const GameArrayType &array = oper2;
  switch (array.Size())
  {
  case 4:
    if (array[3].GetType() != GameString && array[3].GetType() != GameCode)
    {
      state->TypeError(GameString | GameCode, array[3].GetType());
      return NOTHING;
    }
    eventHandler = array[3];
    // continue[
  case 3:
    if (!CheckType(state, array[2], GameString)) return NOTHING;
    taskType = array[2];
    // continue
  case 2:
    if (!CheckType(state, array[0], GameString)) return NOTHING;
    name = array[0];
    if (!CheckType(state, array[1], GameString)) return NOTHING;
    filename = array[1];
    break;
  default:
    state->SetError(EvalDim, array.Size(), 4);
    return NOTHING;
  }
  
  Person *person = dyn_cast<Person>(obj);
  if (!person) return NOTHING;
  AIBrain *unit = person->Brain();
  if (!unit) return NOTHING;

  RString path = FindScript(filename);
  if (path.GetLength() == 0) return NOTHING; 

  unit->AddKBTopic(name, path, taskType, eventHandler);
#endif

  return NOTHING;
}

GameValue KBRemoveTopic(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
#if _ENABLE_CONVERSATION
  // check parameters
  Object *obj = GetObject(oper1);
  Person *person = dyn_cast<Person>(obj);
  if (!person) return NOTHING;
  AIBrain *unit = person->Brain();
  if (!unit) return NOTHING;

  unit->RemoveKBTopic(oper2);
#endif

  return NOTHING;
}

GameValue KBReact(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
#if _ENABLE_CONVERSATION
  // check parameters
  Object *senderObj = GetObject(oper1);

  const GameArrayType &array = oper2;
  if (array.Size() < 3)
  {
    state->SetError(EvalDim, array.Size(), 3);
    return NOTHING;
  }

  Object *receiverObj = GetObject(array[0]);
  if (!CheckType(state, array[1], GameString)) return NOTHING;
  if (array[2].GetType() == GameString)
  {

  }
  else if (array[2].GetType() == GameArray)
  {
    const GameArrayType &subarray = array[2];
    if (!CheckSize(state, subarray, 3)) return NOTHING;
    // sentence id
    if (!CheckType(state, subarray[0], GameString)) return NOTHING;
    // sentence text
    if (!CheckType(state, subarray[1], GameString)) return NOTHING;
    // sentence speech
    if (!CheckType(state, subarray[2], GameArray)) return NOTHING;
    const GameArrayType &speech = subarray[2];
    for (int j=0; j<speech.Size(); j++)
    {
      if (!CheckType(state, speech[j], GameString)) return NOTHING;
    }
  }
  else
  {
    state->TypeError(GameString, array[2].GetType());
    return NOTHING;
  }
  for (int i=3; i<array.Size(); i++)
  {
    // arguments check
    if (!CheckType(state, array[i], GameArray)) return NOTHING;
    const GameArrayType &subarray = array[i];
    switch (subarray.Size())
    {
    case 4:
      // argument text
      if (!CheckType(state, subarray[2], GameString)) return NOTHING;
      // argument speech
      if (!CheckType(state, subarray[3], GameArray)) return NOTHING;
      {
        const GameArrayType &speech = subarray[3];
        for (int j=0; j<speech.Size(); j++)
        {
          if (!CheckType(state, speech[j], GameString)) return NOTHING;
        }
      }
      // continue
    case 2:
      // argument name
      if (!CheckType(state, subarray[0], GameString)) return NOTHING;
      // argument value
      break;
    default:
      state->SetError(EvalDim, array.Size(), 4);
      return NOTHING;
    }
  }

  Person *senderPerson = dyn_cast<Person>(senderObj);
  if (!senderPerson) return NOTHING;
  AIBrain *sender = senderPerson->Brain();
  if (!sender) return NOTHING;

  Person *receiverPerson = dyn_cast<Person>(receiverObj);
  AIBrain *receiver = receiverPerson ? receiverPerson->Brain() : NULL;
  if (!receiver) return NOTHING;

  if (!receiver->IsLocal())
  {
    RptF("Conversation - reacting person need to be local");
    return NOTHING;
  }

  // create a message
  Ref<KBMessageInfo> message = sender->CreateKBMessage(array[1], array[2]);
  if (!message) return NOTHING;

  // set parameters
  for (int i=3; i<array.Size(); i++)
    sender->SetKBMessageArgument(message, array[i]);
  
  // tell the message
  receiver->KBReact(sender,message);
#endif

  return NOTHING;
}


GameValue KBWasSaid(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
#if _ENABLE_CONVERSATION && _ENABLE_IDENTITIES
  // check parameters
  Object *senderObj = GetObject(oper1);

  // [receiver, topic, sentence id, max. age]
  const GameArrayType &array = oper2;
  if (array.Size() !=4)
  {
    state->SetError(EvalDim, array.Size(), 4);
    return false;
  }

  Object *receiverObj = GetObject(array[0]);
  if (!CheckType(state, array[1], GameString)) return false;
  if (!CheckType(state, array[2], GameString)) return false;
  if (!CheckType(state, array[3], GameScalar)) return false;

  Person *senderPerson = dyn_cast<Person>(senderObj);
  if (!senderPerson) return false;
  //AIBrain *sender = senderPerson->Brain();
  //if (!sender) return false;

  Person *receiverPerson = dyn_cast<Person>(receiverObj);
  if (!receiverPerson) return false;

  AIBrain *receiver = receiverPerson->Brain();
  return senderPerson->GetIdentity().WasSaid(receiver,array[1],array[2],array[3]);

#else

  return false;
#endif
}

GameValue KBTell(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
#if _ENABLE_CONVERSATION
  // check parameters
  Object *senderObj = GetObject(oper1);

  const GameArrayType &array = oper2;
  if (array.Size() < 3)
  {
    state->SetError(EvalDim, array.Size(), 3);
    return NOTHING;
  }

  Object *receiverObj = GetObject(array[0]);
  if (!CheckType(state, array[1], GameString)) return NOTHING;
  if (array[2].GetType() == GameString)
  {
  }
  else if (array[2].GetType() == GameArray)
  {
    const GameArrayType &subarray = array[2];
    if (!CheckSize(state, subarray, 3)) return NOTHING;
    // sentence id
    if (!CheckType(state, subarray[0], GameString)) return NOTHING;
    // sentence text
    if (!CheckType(state, subarray[1], GameString)) return NOTHING;
    // sentence speech
    if (!CheckType(state, subarray[2], GameArray)) return NOTHING;
    const GameArrayType &speech = subarray[2];
    for (int j=0; j<speech.Size(); j++)
    {
      if (!CheckType(state, speech[j], GameString)) return NOTHING;
    }
  }
  else
  {
    state->TypeError(GameString, array[2].GetType());
    return NOTHING;
  }

  // check the last argument, bool value can mean to force radio, scalar value CustomRadioChannel, string value the channel name
  int n = array.Size();
  bool forceRadio = false;
  ChatChannel chan = CCNone;
  if (n > 3)
  {
    if (array[n - 1].GetType() == GameBool)
    {
      forceRadio = array[n - 1];
      n--; // exclude from the list of parameters
    }
    else if (array[n - 1].GetType() == GameScalar)
    {
      forceRadio = true;
      chan = (ChatChannel)(toInt((float)array[n-1])+CCCustom1-1); //1==Custom1
      n--; // exclude from the list of parameters
    }
    else if (array[n - 1].GetType() == GameString)
    {
      forceRadio = true;
      RString chanName = array[n-1];
      chan = (ChatChannel)GetEnumValue(GetEnumNames(chan), cc_cast(chanName));
      if (chan<CCNone) chan=CCNone;
      n--; // exclude from the list of parameters
    }
  }

  for (int i=3; i<n; i++)
  {
    // arguments check
    if (!CheckType(state, array[i], GameArray)) return NOTHING;
    const GameArrayType &subarray = array[i];
    switch (subarray.Size())
    {
    case 4:
      // argument text
      if (!CheckType(state, subarray[2], GameString)) return NOTHING;
      // argument speech
      if (!CheckType(state, subarray[3], GameArray)) return NOTHING;
      {
        const GameArrayType &speech = subarray[3];
        for (int j=0; j<speech.Size(); j++)
        {
          if (!CheckType(state, speech[j], GameString)) return NOTHING;
        }
      }
      // continue
    case 2:
      // argument name
      if (!CheckType(state, subarray[0], GameString)) return NOTHING;
      // argument value
      break;
    default:
      state->SetError(EvalDim, subarray.Size(), 4);
      return NOTHING;
    }
  }

  Person *senderPerson = dyn_cast<Person>(senderObj);
  if (!senderPerson) return NOTHING;
  AIBrain *sender = senderPerson->Brain();
  if (!sender) return NOTHING;

  if (!sender->IsLocal())
  {
    RptF("Conversation - need to be initiated by the speaker owner");
    return NOTHING;
  }

  Person *receiverPerson = dyn_cast<Person>(receiverObj);
  AIBrain *receiver = receiverPerson ? receiverPerson->Brain() : NULL;

  // create a message
  Ref<KBMessageInfo> message = sender->CreateKBMessage(array[1], array[2]);
  if (!message) return NOTHING;

  // set parameters
  for (int i=3; i<n; i++)
    sender->SetKBMessageArgument(message, array[i]);
  
  // tell the message
  sender->KBTell(receiver, message, forceRadio, chan);
#endif

  return NOTHING;
}

GameValue KBHasTopic(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
#if _ENABLE_CONVERSATION
  // check parameters
  Object *obj = GetObject(oper1);
  Person *person = dyn_cast<Person>(obj);
  if (!person) return false;
  AIBrain *unit = person->Brain();
  if (!unit) return false;

  return unit->HasKBTopic(oper2);
#else
  return false;
#endif
}

bool GetColor(const GameState *state, PackedColor &color, GameValuePar value)
{
  const GameArrayType &array = value;
  if (array.Size() != 4)
  {
    state->SetError(EvalDim, array.Size(), 4);
    return false;
  }
  for (int i=0; i<4; i++)
  {
    if (array[i].GetType() != GameScalar)
    {
      state->TypeError(GameScalar, array[i].GetType());
      return false;
    }
  }
  color = PackedColor(Color(array[0], array[1], array[2], array[3]));
  return true;
}

RString GetVehicleIcon(RString name);

IControl *GetControl(GameValuePar oper)
{
  if (oper.GetNil()) return NULL;
  if (oper.GetType() != GameControl) return NULL;
  return static_cast<GameDataControl *>(oper.GetData())->GetControl();
}

