GameValue MapDrawEllipse(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  CStaticMap *map = dynamic_cast<CStaticMap *>(GetControl(oper1));
  if (!map) return NOTHING;

  const GameArrayType &array = oper2;
  int n = array.Size();
  if (n < 5 || n > 6)
  {
    state->SetError(EvalDim, array.Size(), 6);
    return NOTHING;
  }
  RString fill;
  if (n == 6)
  {
    if (array[5].GetType() != GameString)
    {
      state->TypeError(GameString, array[5].GetType());
      return NOTHING;
    }
    fill = array[5];
  }
  PackedColor color;
  if (!GetColor(state, color, array[4])) return NOTHING;
  if (array[3].GetType() != GameScalar)
  {
    state->TypeError(GameScalar, array[3].GetType());
    return NOTHING;
  }
  float angle = array[3];
  if (array[2].GetType() != GameScalar)
  {
    state->TypeError(GameScalar, array[2].GetType());
    return NOTHING;
  }
  float b = array[2];
  if (array[1].GetType() != GameScalar)
  {
    state->TypeError(GameScalar, array[1].GetType());
    return NOTHING;
  }
  float a = array[1];
  Vector3 pos;
  if (!GetPos(state, pos, array[0])) return NOTHING;

  if (fill.GetLength() == 0)
    map->DrawEllipse(pos, a, b, angle * (H_PI / 180.0), color);
  else
  {
    Ref<Texture> texture = GlobLoadTexture(GetPictureName(fill));
    map->FillEllipse(pos, a, b, angle * (H_PI / 180.0), color, texture);
  }
  return NOTHING;
}

