GameValue MapPosScreenToWorld(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  GameValue value = state->CreateGameValue(GameArray);
  GameArrayType &result = value;
  result.Realloc(3);
  result.Resize(3);
  result[0] = 0.0f;
  result[1] = 0.0f;
  result[2] = 0.0f;

  CStaticMap *map = dynamic_cast<CStaticMap *>(GetControl(oper1));
  if (!map) return result;

  const GameArrayType &array = oper2;
  if (!CheckSize(state, array, 2)) return result;
  if (!CheckType(state, array[0], GameScalar)) return result;
  if (!CheckType(state, array[1], GameScalar)) return result;

  Point2DFloat in(array[0], array[1]);
  Vector3 out = map->ScreenToWorld(in);
  
  result[0] = out.X();
  result[1] = out.Z();

  return result;
}

GameValue MapPosWorldToScreen(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  GameValue value = state->CreateGameValue(GameArray);
  GameArrayType &result = value;
  result.Realloc(2);
  result.Resize(2);
  result[0] = 0.0f;
  result[1] = 0.0f;

  CStaticMap *map = dynamic_cast<CStaticMap *>(GetControl(oper1));
  if (!map) return result;

  Vector3 in;
  if (!GetPos(state, in, oper2)) return result;

  Point2DFloat out = map->WorldToScreen(in);

  result[0] = out.x;
  result[1] = out.y;

  return result;
}

GameValue UIMapMouseOver(const GameState *state, GameValuePar oper1)
{
  // create the return value
  GameValue value = state->CreateGameValue(GameArray);
#ifdef _WIN32
  GameArrayType &array = value;

  // get map control
  IControl *ctrl = GetControl(oper1);
  CStaticMap *map = dynamic_cast<CStaticMap *>(ctrl);
  if (!map) return value;

  const SignInfo &info = map->_infoMove;
  switch (info._type)
  {
  case signNone:
    break;
  case signUnit:
    array.Add("unit");
    if (info._unit) array.Add(GameValueExt(info._unit->GetVehicle()));
    break;
  case signVehicle:
    /// vehicle as listed in the center target list
    array.Add("vehicle");
    array.Add(GameValueExt(info._id));
    break;
  case signVehicleGroup:
    /// vehicle as listed in the group target list
    array.Add("vehicleGroup");
    array.Add(GameValueExt(info._id));
    break;
  case signStatic:
    /// static object
    array.Add("object");
    array.Add(GameValueExt(info._id));
    break;
  case signArcadeUnit:
    // mission editor
    break;
  case signArcadeMarker:
    array.Add("marker");
    if (info._index >= 0 && info._index < markersMap.Size())
      array.Add(markersMap[info._index].name);
    break;
#if _ENABLE_EDITOR2
  case signEditorObject:
    // mission editor
    break;
#endif
#if _ENABLE_IDENTITIES
  case signTask:
    array.Add("task");
    if (info._unit)
    {
      Task *task = info._unit->GetPerson()->GetIdentity().FindTask(info._index);
      array.Add(CreateGameTask(task));
    }
    break;
  case signCustomMark:
    array.Add("customMark");
    break;
#endif
  }
#endif
  return value;
}

GameValue WorldToScreen(const GameState *state, GameValuePar oper1)
{
  // create the return value
  GameValue value = state->CreateGameValue(GameArray);

  // input - 3D position in world space
  Vector3 pos;
  if (!GetPos(pos, oper1)) return value;

  const Camera *camera = GScene->GetCamera();
  if (!camera) return value;

  // convert position to the camera space
  Matrix4Val camInvTransform = camera->GetInvTransform();
  Vector3Val dirCam = camInvTransform.Rotate(pos - camera->Position());

  if (dirCam.Z() <= 0) return value; // object behind the camera

  // convert to the screen space
  float invZ = 1.0f / dirCam.Z();
  float xScreen = 0.5f * (1.0f + dirCam.X() * invZ * camera->InvLeft());
  float yScreen = 0.5f * (1.0f - dirCam.Y() * invZ * camera->InvTop());

  AspectSettings asp;
  GEngine->GetAspectSettings(asp);

  GameArrayType &array = value;
  array.Realloc(2);
  // convert to the UI space
  array.Add((xScreen - asp.uiTopLeftX) / (asp.uiBottomRightX - asp.uiTopLeftX));
  array.Add((yScreen - asp.uiTopLeftY) / (asp.uiBottomRightY - asp.uiTopLeftY));
  return value;
}

GameValue ScreenToWorld(const GameState *state, GameValuePar oper1)
{
  // create the return value
  GameValue value = state->CreateGameValue(GameArray);

  // input - 2D position in UI space
  const GameArrayType &array = oper1;
  if (!CheckSize(state, array, 2)) return value;
  if (!CheckType(state, array[0], GameScalar)) return value;
  if (!CheckType(state, array[1], GameScalar)) return value;
  float x = array[0];
  float y = array[1];

  AspectSettings asp;
  GEngine->GetAspectSettings(asp);

  // convert to screen space
  float xScreen = x * (asp.uiBottomRightX - asp.uiTopLeftX) + asp.uiTopLeftX;
  float yScreen = y * (asp.uiBottomRightY - asp.uiTopLeftY) + asp.uiTopLeftY;

  const Camera *camera = GScene->GetCamera();
  if (!camera) return value;

  // convert to the camera space
  Vector3 dirCam((2.0f * xScreen - 1.0f) * camera->Left(), -(2.0f * yScreen - 1.0f) * camera->Top(), 1.0f);
  dirCam.Normalize();
  
  // convert to the world space
  Vector3 dir = camera->DirectionModelToWorld(dirCam);

  // find the intersection with landscape
  Vector3 pos = GLandscape->IntersectWithGroundOrSea(camera->Position(), dir);

  GameArrayType &result = value;
  result.Realloc(3);
  result.Add(pos.X());
  result.Add(pos.Z());
  result.Add(0.0f); // point on ground

  return value;
}

