GameValue UICtrlGetPosition(const GameState *state, GameValuePar oper1)
{
  GameValue value = state->CreateGameValue(GameArray);
  GameArrayType &array = value;
  array.Realloc(4);
  array.Resize(4);
  array[0] = 0.0f; array[1] = 0.0f; array[2] = 0.0f; array[3] = 0.0f;

  IControl *ictrl = GetControl(oper1);
  Control *ctrl = dynamic_cast<Control *>(ictrl);
  if (ctrl)
  {
    array[0] = ctrl->X(); array[1] = ctrl->Y();
    array[2] = ctrl->W(); array[3] = ctrl->H();
  }
  else
  {
    ControlObject *obj = dynamic_cast<ControlObject *>(ictrl);
    if (obj)
    {
      Vector3 pos = obj->GetPosition2D();
      
      array.Realloc(3);
      array.Resize(3);
      array[0] = pos[0]; array[1] = pos[1]; array[2] = pos[2];
    }
  }
  return array;
}

