GameValue UICtrlSetPosition(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  IControl *ictrl = GetControl(oper1);
  Control *ctrl = dynamic_cast<Control *>(ictrl);
  if (ctrl)
  {
    const GameArrayType &array = oper2;
    if (array.Size() != 2 && array.Size() != 4) return NOTHING;
    if (!CheckType(state, array[0], GameScalar)) return NOTHING;
    if (!CheckType(state, array[1], GameScalar)) return NOTHING;
    float w = ctrl->W();
    float h = ctrl->H();
    if (array.Size() == 4)
    {
      if (!CheckType(state, array[2], GameScalar)) return NOTHING;
      if (!CheckType(state, array[3], GameScalar)) return NOTHING;
      w = array[2];
      h = array[3];
    }
    ctrl->AnimPos(array[0], array[1], w, h);
  }
  return NOTHING;
}

