GameValue UIButtonGetAction(const GameState *state, GameValuePar oper1)
{
  IControl *ctrl = GetControl(oper1);
  if (!ctrl) return RString();

  int type = ctrl->GetType();
  switch (type)
  {
  case CT_BUTTON:
    {
      CButton *s = static_cast<CButton *>(ctrl);
      return s ? s->GetAction() : RString();
    }
  case CT_XBUTTON:
    {
      CXButton *s = static_cast<CXButton *>(ctrl);
      return s ? s->GetAction() : RString();
    }
  case CT_ACTIVETEXT:
    {
      CActiveText *s = static_cast<CActiveText *>(ctrl);
      return s ? s->GetAction() : RString();
    }
  case CT_SHORTCUTBUTTON:
    {
      CShortcutButton *s = static_cast<CShortcutButton *>(ctrl);
      return s ? s->GetAction() : RString();
    }
  default:
    return RString();
  }
}

GameValue UIButtonSetAction(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  IControl *ctrl = GetControl(oper1);
  if (!ctrl) return NOTHING;

  RString text = oper2;

  int type = ctrl->GetType();
  switch (type)
  {
  case CT_BUTTON:
    {
      CButton *s = static_cast<CButton *>(ctrl);
      s->SetAction(text);
      break;
    }
  case CT_XBUTTON:
    {
      CXButton *s = static_cast<CXButton *>(ctrl);
      s->SetAction(text);
      break;
    }
  case CT_ACTIVETEXT:
    {
      CActiveText *s = static_cast<CActiveText *>(ctrl);
      s->SetAction(text);
      break;
    }
  case CT_SHORTCUTBUTTON:
    {
      CShortcutButton *s = static_cast<CShortcutButton *>(ctrl);
      s->SetAction(text);
      break;
    }
  default:
    break;
  }
  return NOTHING;
}

