GameValue UIGetCtrlTextHeight(const GameState *state, GameValuePar oper1)
{
  IControl *ctrl = GetControl(oper1);
  if(!ctrl) return 0.0f;

  float h = 0;
  switch (ctrl->GetType())
  {
  case CT_STATIC:
    {
      CStatic *text = dynamic_cast<CStatic *>(ctrl);
      if(!text) return 0.0f;
      h = text->GetTextHeight();
      break;
    }
  case CT_STRUCTURED_TEXT:
    {
      CStructuredText *text = dynamic_cast<CStructuredText *>(ctrl);
      if(!text) return 0.0f;
      h = text->GetTextHeight();
      break;
    }
  }

  return h;
}

GameValue UISliderSetSpeed(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  const GameArrayType &array = oper2;
  float step = 0;
  switch (array.Size())
  {
  case 3:
    if (!CheckType(state, array[2], GameScalar)) return NOTHING;
    step = array[2];
  case 2:
    if (!CheckType(state, array[0], GameScalar)) return NOTHING;
    if (!CheckType(state, array[1], GameScalar)) return NOTHING;
    break;
  default:
    state->SetError(EvalDim, array.Size(), 3);
    return NOTHING;
  }

  IControl *ctrl = GetControl(oper1);
  CSliderContainer *slider = GetSliderContainer(ctrl);
  if (slider) slider->SetSpeed(array[0], array[1], step);
  return NOTHING;
}

