GameValue TeamMemberGetMembers(const GameState *state, GameValuePar oper1)
{
  GameValue value = state->CreateGameValue(GameArray);
  GameArrayType &array = value;

  AITeamMember *teamMember = GetTeamMember(oper1);
  if (!teamMember) return value; // empty array

  AITeam *team = teamMember->GetTeam();
  if (!team) return value; // empty array

  for (int i=0; i<team->NTeamMembers(); i++)
  {
    AITeamMember *member = team->GetTeamMember(i);
    if (!member) continue;
    array.Add(CreateGameTeamMember(member));
  }
  array.Compact();
  return value;
}

