class BuildAgentList
{
  GameArrayType &_agents;
public:
  BuildAgentList(GameArrayType &array):_agents(array){}
  __forceinline bool operator () (Entity *veh) const
  {
    Person *person = dyn_cast<Person>(veh);
    if (person)
    {
      AIBrain *brain = person->Brain();
      if (brain)
        _agents.Add(CreateGameTeamMember(brain->GetTeamMember()));
    }
    return false;
  }
};

GameValue TeamMemberGetAgents(const GameState *state)
{
  GameValue value = state->CreateGameValue(GameArray);
  GameArrayType &array = value;

  BuildAgentList build(array);
  GWorld->ForEachVehicle(build);
  GWorld->ForEachOutVehicle(build);

  array.Compact();
  return value;
}

GameValue TeamMemberCmpE( const GameState *state, GameValuePar oper1, GameValuePar oper2 )
{
  AITeamMember *teamMember1 = GetTeamMember(oper1);
  AITeamMember *teamMember2 = GetTeamMember(oper2);
  if (!teamMember1 || !teamMember2) return false;
  return teamMember1 == teamMember2;
}

GameValue TeamMemberCmpNE( const GameState *state, GameValuePar oper1, GameValuePar oper2 )
{
  AITeamMember *teamMember1 = GetTeamMember(oper1);
  AITeamMember *teamMember2 = GetTeamMember(oper2);
  if (!teamMember1 || !teamMember2) return true;
  return teamMember1 != teamMember2;
}

