GameValue TeamMemberSetVariable(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  AITeamMember *teamMember = GetTeamMember(oper1);
  if (!teamMember) return NOTHING;

  const GameArrayType &array = oper2;

  if (array.Size() < 2 || array.Size() > 3)
  {
    if (state) state->SetError(EvalDim,array.Size(),2);
    return NOTHING;
  }
  if (!CheckType(state, array[0], GameString)) return NOTHING;

  RString name = array[0];
  name.Lower();
  teamMember->GetVars()->VarSet(name, array[1]);

  // pass across network?
  if (array.Size() == 3)
  {
    if (!CheckType(state, array[2], GameBool)) return NOTHING;
  }

  return NOTHING;
}

GameValue TeamMemberGetVariable(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  AITeamMember *teamMember = GetTeamMember(oper1);
  if (!teamMember) return NOTHING;

  if (oper2.GetType() == GameString)
  {
    RString name = oper2;
    GameValue var;
    name.Lower();
    if (teamMember->GetVars()->VarGet(name, var)) return var;
  }
  else if (oper2.GetType() == GameArray)
  {
    const GameArrayType &array = oper2;
    if (!CheckSize(state, array, 2)) return NOTHING;
    if (!CheckType(state, array[0], GameString)) return NOTHING;
    RString name = array[0];
    GameValue var;
    name.Lower();
    if (teamMember->GetVars()->VarGet(name, var)) return var;
    else return  array[1];
  }
  return NOTHING;

}

