static void CollectMembers(GameArrayType &list, AITeam *team, bool collectTeams, bool collectAgents)
{
  for (int i=0; i<team->NTeamMembers(); i++)
  {
    AITeamMember *member = team->GetTeamMember(i);
    if (!member) continue;
    AITeam *memberTeam = member->GetTeam();
    if (memberTeam)
    {
      if (collectTeams) list.Add(GameValueExt(memberTeam));
      CollectMembers(list, memberTeam, collectTeams, collectAgents);
    }
    else if (collectAgents)
    {
      AIAgent *memberAgent = member->GetAgent();
      if (memberAgent) list.Add(GameValueExt(memberAgent));
    }
  }
}

GameValue TeamForEachMember(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
#if USE_PRECOMPILATION
  // read the parameters
  GameDataCode *code = static_cast<GameDataCode *>(oper1.GetData());
  AITeamMember *teamMember = GetTeamMember(oper2);
  if (!teamMember) return NOTHING;
  AITeam *team = teamMember->GetTeam();
  if (!team) return NOTHING;

  // list all members
  Ref<GameDataArray> array = new GameDataArray();
  GameArrayType &list = array->GetArray();
  CollectMembers(list, team, true, true);

  // invoke forEach
  VMContext *context = state->GetVMContext();
  // 2 operands are over bottom of stack 
  CallStackItem *level = new CallStackItemArrayForEach(
    context->GetCallStack(), context->GetVariables(), context->_stack.Size() - 2, state,
    code, array, context->IsSerializationEnabled());
  context->AddLevel(level);
#endif
  return NOTHING;
}

