GameValue SafeZoneX(const GameState *state)
{//returns safe-zone in final 4:3 screen UI coordinate system  
  if(!GEngine || GEngine->Width2D()<=0) return -1.0f;
  float ratio =(float)GEngine->WidthBB()/GEngine->Width2D();

  AspectSettings asp;
  GEngine->GetAspectSettings(asp);
  if(!asp.tripleHead)
  {
    return (-asp.uiTopLeftX) * ratio;
  }
  else
  {
    return (-asp.uiTopLeftX) * ratio + (1 + 2*(asp.uiTopLeftX) * ratio)/3.0f;;
  }
}

GameValue SafeZoneY(const GameState *state)
{//returns safe-zone in final 4:3 screen UI coordinate system  
  if(!GEngine || GEngine->Height2D()<=0) return -1.0f;
  float ratio =(float)GEngine->HeightBB()/GEngine->Height2D();

  AspectSettings asp;
  GEngine->GetAspectSettings(asp);
  return (-asp.uiTopLeftY) * ratio;
}

