GameValue SendUDPMessage(const GameState *state, GameValuePar oper1)
{
#if defined _WIN32 && _ENABLE_SEND_UDP_MESSAGE

  const GameArrayType &array = oper1;
  if(array.Size()!= 3) 
  { 
    state->SetError(EvalDim,array.Size(),3);
    return false;
  }

  //if (CheckType(state, array[0], GameString)) return false;
  //if (CheckType(state, array[1], GameScalar)) return false;
  //if (CheckType(state, array[2], GameString)) return false;

  RString ip = array[0];
  int port = toInt((float)array[1]);
  RString message = array[2];


  //use sockets
  Socket socketSend;
  if (!socketSend)
  {
    socketSend.Create(SOCK_DGRAM);
    if (!socketSend) return false;      

    sockaddr_in serverInfo;
    int len = sizeof(serverInfo);
    serverInfo.sin_family = AF_INET;
    serverInfo.sin_addr.s_addr = inet_addr(ip.Data());
    serverInfo.sin_port = htons(port);

    char buffer[1024];
    ZeroMemory(buffer, sizeof(buffer));
    sprintf(buffer,"%s", message.Data());

    if (sendto(socketSend, buffer, sizeof(buffer), 0, (sockaddr*)&serverInfo, len) != SOCKET_ERROR)
    {
      socketSend.Close();
      return true;
    }
    else
    {
      socketSend.Close();
      return false;
    }
  } 
#endif   
  return false;
}

//Return all units in array that are below passed height.
GameValue UnitsBelowHeight (const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  const GameArrayType &units = oper1;
  const float height = oper2;

  GameValue unitsBelowHeight = state->CreateGameValue(GameArray);
  GameArrayType &unitsBelowHeightArray = unitsBelowHeight;

  for (int count = 0;count < units.Size();count = count + 1)
  {
    if (units[count].GetType() == GameObject)
    {
      Object *object = GetObject(units[count]);

      if (object)
      {
        Vector3Val position = object->WorldPosition(object->FutureVisualState());
        Matrix4 transform = object->WorldTransform(object->FutureVisualState());

        if ((transform.FastTransform(object->PlacingPoint()).Y() - GLandscape->SurfaceY(position)) < height)
        {
          unitsBelowHeightArray.Add(GameValueExt(object));
        }
      }
    }
  }

  return unitsBelowHeightArray;
}

static int CmpCollisionObjs(const CollisionInfo *i1, const CollisionInfo *i2)
{
  DoAssert(i1 && i2);
  if (!i1) return -1;
  if (!i2) return 1;

  float diff = i2->under - i1->under;
  return sign(diff);
}

GameValue ObjectCollisionLineInt(const GameState *state, GameValuePar oper1, bool fast, ObjIntersect iType )
{
  if (!CheckType(state, oper1, GameArray)) return NOTHING;
  const GameArrayType &array = oper1;

  if (array.Size() < 2) 
  {
    state->SetError(EvalDim, array.Size(), 2);
    return NOTHING;
  }

  Landscape *landscape = GScene->GetLandscape();
  if (!landscape) return NOTHING;

  Vector3 begPos(VZero), endPos(VZero);
  if (!GetVector(state, begPos, array[0])) return NOTHING;
  if (!GetVector(state, endPos, array[1])) return NOTHING;

  // collision with ground
  static float MaxDist = 1000.0f;
  Vector3 dir = endPos - begPos;
  float maxDist = floatMin(MaxDist, dir.Size());
  dir.Normalize();
  float t = landscape->IntersectWithGroundOrSea(NULL, begPos, dir, 0, maxDist);
  if (t < maxDist)
    endPos = begPos + dir * floatMin(t, maxDist);

  Object *with = NULL;
  Object *ignore = NULL;
  bool sorted = false;
  if (array.Size()>=3)
  {
    if (!CheckType(state, array[2], GameObject)) return NOTHING;

    with = GetObject(array[2]);
    if (array.Size()>=4)
    {
      if (!CheckType(state, array[3], GameObject)) return NOTHING;

      ignore = GetObject(array[3]);
      if (array.Size()>=5)
      {
        if (!CheckType(state, array[4], GameBool)) return NOTHING;
        sorted = GameBoolType(array[4]);
        if (array.Size()>=6)
        {
          if (!CheckType(state, array[5], GameString)) return NOTHING;
          RString type = array[5];
          ObjIntersect iTypeS = GetEnumValue<ObjIntersect>(cc_cast(type));
          if (iTypeS!=INT_MIN) iType = iTypeS;
        }
      }
    }
    
  }

  CollisionBuffer colResult;
  landscape->ObjectCollisionLine(0, colResult, Landscape::FilterIgnoreTwo(with, ignore), begPos, endPos, 0, iType, ObjIntersectNone, fast ? CF_FIRST_CONTACT : 0);

  if (fast)
    return GameValue(colResult.Size() != 0);
  else
  {
    GameValue valueTmp = state->CreateGameValue(GameArray);
    GameArrayType &resultTmp = valueTmp;

    if (colResult.Size() > 0)
    {
      if (sorted)
        QSort(colResult.Data(), colResult.Size(), CmpCollisionObjs);

      RefArray<Object> objColRefs;
      objColRefs.Realloc(colResult.Size());

      for (int i = 0; i < colResult.Size(); i++)
        objColRefs.AddUnique(colResult[i].object);

      for (int i = 0; i < objColRefs.Size(); i++)
        resultTmp.Add(GameValueExt(objColRefs[i], GameValExtObject));
    }

    return valueTmp;
  }
}

GameValue LineIntersects(const GameState *state, GameValuePar oper1)
{
  return ObjectCollisionLineInt(state, oper1, true, ObjIntersectView);
}

GameValue LineIntersectsWith(const GameState *state, GameValuePar oper1)
{
  return ObjectCollisionLineInt(state, oper1, false, ObjIntersectView);
}

GameValue LineHit(const GameState *state, GameValuePar oper1)
{
  if (!CheckType(state, oper1, GameArray)) return NOTHING;
  const GameArrayType &array = oper1;

  if (array.Size() < 2) 
  {
    state->SetError(EvalDim, array.Size(), 2);
    return NOTHING;
  }

  Landscape *landscape = GScene->GetLandscape();
  if (!landscape) return NOTHING;

  // begPos, endPos, geometryType, withObj, ignoreObj
  Vector3 begPos(VZero), endPos(VZero);
  if (!GetVector(state, begPos, array[0])) return NOTHING;
  if (!GetVector(state, endPos, array[1])) return NOTHING;

  // collision with ground
  static float MaxDist = 1000.0f;
  Vector3 dir = endPos - begPos;
  float maxDist = floatMin(MaxDist, dir.Size());
  dir.Normalize();
  float t = landscape->IntersectWithGroundOrSea(NULL, begPos, dir, 0, maxDist);
  if (t < maxDist)
    endPos = begPos + dir * floatMin(t, maxDist);

  Object *with = NULL;
  Object *ignore = NULL;
  ObjIntersect iType = ObjIntersectFire;
  float radius = 0;
  if (array.Size()>2)
  {
    if (!CheckType(state, array[2], GameString)) return NOTHING;
    RString type = array[2];
    ObjIntersect iTypeS = GetEnumValue<ObjIntersect>(cc_cast(type));
    if (iTypeS!=INT_MIN) iType = iTypeS;

    if (array.Size()>3)
    {
      if (!CheckType(state, array[3], GameObject)) return NOTHING;

      with = GetObject(array[3]);
      if (array.Size()>4)
      {
        if (!CheckType(state, array[4], GameObject)) return NOTHING;

        ignore = GetObject(array[4]);
        if (array.Size()>5)
        {
          if (!CheckType(state, array[5], GameScalar)) return NOTHING;

          radius = array[5];
        }
      }
    }

  }

  CollisionBuffer colResult;
  landscape->ObjectCollisionLine(0, colResult, Landscape::FilterIgnoreTwo(with, ignore), begPos, endPos, radius, iType, ObjIntersectNone, CF_NEAREST_CONTACT);

  // find a first hit

  GameValue valueTmp = state->CreateGameValue(GameArray);
  GameArrayType &resultTmp = valueTmp;

  if (colResult.Size() > 0)
  {
    const auto &colRes = colResult[0];
    Object *obj = colRes.object;

    // object, selection and world space position
    resultTmp.Add(GameValueExt(obj,GameValExtObject));
    int component = obj->GetShape()->GetConvexComponents(colRes.geomLevel)->Get(colRes.component)->GetNameIndex();
    resultTmp.Add(ToGameValue<float>::Do(component));
    resultTmp.Add(ToGameValue<Vector3>::Do(colRes.pos));
  }

  return valueTmp;
}

GameValue TerrainIntersect(const GameState *state, GameValuePar oper1)
{
  if (!CheckType(state, oper1, GameArray)) return NOTHING;
  const GameArrayType &array = oper1;

  if (!CheckSize(state, array, 2)) return NOTHING;

  Landscape *landscape = GScene->GetLandscape();
  if (!landscape) return NOTHING;

  Vector3 pos1, pos2;
  if (GetPos(pos1, array[0]) && GetPos(pos2, array[1]))
  {    
    float maxDist = pos1.Distance(pos2);
    Vector3 dir = (pos2 - pos1).Normalized();

    Vector3 intersect;

    float t = landscape->IntersectWithGroundOrSea(&intersect, pos1, dir, 0.5f, maxDist);
    return t < maxDist;
  }

  return NOTHING;
}

GameValue TerrainIntersectASL(const GameState *state, GameValuePar oper1)
{
  if (!CheckType(state, oper1, GameArray)) return NOTHING;
  const GameArrayType &array = oper1;

  if (!CheckSize(state, array, 2)) return NOTHING;

  Landscape *landscape = GScene->GetLandscape();
  if (!landscape) return NOTHING;

  Vector3 pos1, pos2;
  if (GetVector(state, pos1, array[0]) && GetVector(state, pos2, array[1]))
  {    
    float maxDist = pos1.Distance(pos2);
    Vector3 dir = (pos2 - pos1).Normalized();

    Vector3 intersect;

    float t = landscape->IntersectWithGroundOrSea(&intersect, pos1, dir, 0.5f, maxDist);
    return t < maxDist;
  }

  return NOTHING;
}


