GameValue GetWindRTD(const GameState *state)
{
  GameValue value = state->CreateGameValue(GameArray);

#if _HELISIM_ROTORLIB && !_DUMMY_ROTORLIB

  WorldRTD *rtdWorld = GWorld->GetRTDWorld();
  if(!rtdWorld) return value;
  const smVec3r wind = rtdWorld->GetWindSpeed();

  GameArrayType &result = value;
  result.Realloc(3);
  result.Resize(3);
  result[0] = wind[0];
  result[1] = wind[1]; 
  result[2] = wind[2]; 

#endif
  return value;
}

