GameValue GetAirDensityCurveRTD(const GameState *state)
{
  GameValue value = state->CreateGameValue(GameArray);

#if _HELISIM_ROTORLIB && !_DUMMY_ROTORLIB

  RTD::World *rtdWorld = GWorld->GetRTDWorld();
  if(!rtdWorld) return value;
  const smGraph2D densityGraph = rtdWorld->getAirDensityCurve();
  GameArrayType &result = value;

  for (int i=0; i<  densityGraph.getNumPoints(); i++)
  {
    GameValue valueTmp = state->CreateGameValue(GameArray);
    GameArrayType &resultTmp = valueTmp;
    const smGraphPoint densityPoint = densityGraph.getPoint(i);

    resultTmp.Add(densityPoint.x);
    resultTmp.Add(densityPoint.y);
    resultTmp.Add(densityPoint.z);
    result.Add(resultTmp);
  }

#endif
  return value;
}

