#define SIMUL_WEATHER_COMMAND(CommandName, ClassName, InitFromKeyframes) \
  GameValue Simul##CommandName (const GameState *state, GameValuePar oper1) \
{\
  if (!CheckType(state, oper1, GameScalar)) return NOTHING; \
  if (GLandscape && GLandscape->GetSimulWeather() && GLandscape->GetSimulWeather()->ClassName) \
{\
  float param = oper1;\
  GLandscape->GetSimulWeather()->ClassName->CommandName(param); \
}\
  if (InitFromKeyframes && GLandscape && GLandscape->GetSimulWeather() && GLandscape->GetSimulWeather()->GetCloudRenderer()->GetCloudInterface()) \
  GLandscape->GetSimulWeather()->GetCloudRenderer()->GetCloudKeyframer()->InitKeyframesFromClouds(); \
  return NOTHING; \
}\

#define SIMUL_WEATHER_COMMAND_2(CommandName, ClassName, InitFromKeyframes) \
  GameValue Simul##CommandName (const GameState *state, GameValuePar oper1) \
{\
  if (!CheckType(state, oper1, GameArray)) return NOTHING; \
  const GameArrayType &array = oper1;\
  if (!CheckSize(state, array, 2)) return NOTHING;\
  if (!CheckType(state, array[0], GameScalar)) return NOTHING;\
  if (!CheckType(state, array[1], GameScalar)) return NOTHING;\
  float param1=array[0];\
  float param2=array[1];\
  if (GLandscape && GLandscape->GetSimulWeather() && GLandscape->GetSimulWeather()->ClassName) \
{\
  GLandscape->GetSimulWeather()->ClassName->CommandName(param1, param2); \
}\
  if (InitFromKeyframes && GLandscape && GLandscape->GetSimulWeather() && GLandscape->GetSimulWeather()->GetCloudRenderer()->GetCloudInterface()) \
  GLandscape->GetSimulWeather()->GetCloudRenderer()->GetCloudKeyframer()->InitKeyframesFromClouds(); \
  return NOTHING; \
}\

#define SIMUL_WEATHER_COMMAND_BOOL(CommandName, ClassName, InitFromKeyframes) \
  GameValue Simul##CommandName (const GameState *state, GameValuePar oper1) \
{\
  if (!CheckType(state, oper1, GameBool)) return NOTHING; \
  if (GLandscape && GLandscape->GetSimulWeather() && GLandscape->GetSimulWeather()->ClassName) \
{\
  GLandscape->GetSimulWeather()->ClassName->CommandName(oper1); \
}\
  if (InitFromKeyframes && GLandscape && GLandscape->GetSimulWeather() && GLandscape->GetSimulWeather()->GetCloudRenderer()->GetCloudInterface()) \
  GLandscape->GetSimulWeather()->GetCloudRenderer()->GetCloudKeyframer()->InitKeyframesFromClouds(); \
  return NOTHING; \
}\

