GameValue EnableSimulWeather( const GameState *state, GameValuePar oper1 )
{
  if (!CheckType(state, oper1, GameBool)) return NOTHING;
  if (GLandscape)
    GLandscape->EnableSimulWeather(oper1);
  return NOTHING;
}

GameValue ReloadSimulWeather(const GameState *state, GameValuePar oper)
{
  RString fileName = oper;

  if (!QFBankQueryFunctions::FileExists(fileName))
  {
    RptF("Cannot find file \"%s\"", cc_cast(fileName));
    return NOTHING;
  }

  // parse file
  GameDataNamespace parsingNamespace(NULL, "parsing_sw", false);
  ParamFile tmpPars;
  tmpPars.Parse(fileName, new ParamClassOwnerNoUnload("",fileName), NULL, &parsingNamespace); // parsing namespace (persistent namespace needed for persistent ParamFile)

  // find out which skeleton sources we should update
  ParamEntryVal cfg = tmpPars >> "SimulWeather";
  if (!cfg.IsClass())
  {       
    // no CfgRagDollSkeletons found
    RptF("Cannot find entry for \"SimulWeather\"");
    return NOTHING;
  }

  if (GLandscape)
  {
    // clear sequencer file cache, so that fresh files are loaded
    SimulWeatherUtils::GetSequencerFileCache().Clear();
    GLandscape->LoadSimulWeather(tmpPars, true);
  }

  return GameValue();
}

GameValue SimulInClouds(const GameState *state, GameValuePar oper)
{
  if (!CheckType(state, oper, GameArray)) return NOTHING;
  const GameArrayType &array = oper;
  if (!CheckSize(state, array, 3)) return NOTHING;
  for (int i=0; i<3; ++i)
    if (!CheckType(state, array[i], GameScalar)) return NOTHING;

  if (!GLandscape || !GLandscape->GetSimulWeather())
    return false;

  /// note -> position Z and Y is switched for script commands
  Vector3 position(array[0], array[2], array[1]);
  return (GLandscape->GetSimulWeather()->GetCloudDensity(position) > 0.0f);
}

GameValue SimulCloudDensity(const GameState *state, GameValuePar oper)
{
  if (!CheckType(state, oper, GameArray)) return NOTHING;
  const GameArrayType &array = oper;
  if (!CheckSize(state, array, 3)) return NOTHING;
  for (int i=0; i<3; ++i)
    if (!CheckType(state, array[i], GameScalar)) return NOTHING;

  if (!GLandscape || !GLandscape->GetSimulWeather())
    return false;

  /// note -> position Z and Y is switched for script commands
  Vector3 position(array[0], array[2], array[1]);
  return (GLandscape->GetSimulWeather()->GetCloudDensity(position));
}

GameValue SimulCloudOcclusion(const GameState *state, GameValuePar oper)
{
  if (!CheckType(state, oper, GameArray)) return NOTHING;
  const GameArrayType &array0 = oper;
  if (!CheckSize(state, array0, 2)) return NOTHING;
  if (!CheckType(state, array0[0], GameArray)) return NOTHING;
  if (!CheckType(state, array0[1], GameArray)) return NOTHING;

  const GameArrayType &array1 = array0[0];
  if (!CheckSize(state, array1, 3)) return NOTHING;
  for (int i=0; i<3; ++i)
    if (!CheckType(state, array1[i], GameScalar)) return NOTHING;

  const GameArrayType &array2 = array0[1];
  if (!CheckSize(state, array2, 3)) return NOTHING;
  for (int i=0; i<3; ++i)
    if (!CheckType(state, array2[i], GameScalar)) return NOTHING;

  if (!GLandscape || !GLandscape->GetSimulWeather())
    return false;

  Vector3 position1(array1[0], array1[2], array1[1]);
  Vector3 position2(array2[0], array2[2], array2[1]);

  /// note -> position Z and Y is switched for script commands
  return (GLandscape->GetSimulWeather()->GetCloudOcclusion(position1, position2));
}

GameValue SetSimulWeatherRenderMode( const GameState *state, GameValuePar oper1 )
{
  if (!CheckType(state, oper1, GameScalar)) return NOTHING;
  if (GLandscape && GLandscape->GetSimulWeather())
  {
    float renderModeFloat = oper1;
    int renderMode = (int)renderModeFloat;
    GLandscape->GetSimulWeather()->SetRenderMode((SimulCloudRendererBase::RenderMode)renderMode);
  }
  return NOTHING;
}

GameValue SimulLoadSeq( const GameState *state, GameValuePar oper1 )
{
  if (!CheckType(state, oper1, GameString)) return NOTHING;
  if (GLandscape && GLandscape->GetSimulWeather())
  {
    const GameStringType &fileName = oper1;
    GLandscape->GetSimulWeather()->LoadSequencerFile(fileName);
  }
  return NOTHING;
}

