GameValue LoadJClass(const GameState *state, GameValuePar oper1)
{
  if (!IsJavaVMInitialized())
    return NOTHING;
  RString name = oper1;
  return GameValue(new GameDataJavaClass(name));
}

GameValue ExecJFSM(const GameState *state, GameValuePar oper1)
{
  if (!IsJavaVMInitialized())
    return NOTHING;
  JVMFSM *fsm = new JVMFSM(oper1);
  GWorld->AddJVMFSM(fsm);
  return NOTHING;
}

GameValue ExecJFSM(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  if (!IsJavaVMInitialized())
    return NOTHING;
  const GameArrayType &args = oper2;
  JVMFSM *fsm = new JVMFSM(oper1, &args);
  GWorld->AddJVMFSM(fsm);
  return NOTHING;
}

GameValue CallJMethod(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  if (!IsJavaVMInitialized())
    return NOTHING;
  // check and convert parameters
  if (oper1.GetType() != GameJavaClass) return NOTHING;
  GameDataJavaClass *cls = static_cast<GameDataJavaClass *>(oper1.GetData());
  if (cls == NULL) return NOTHING;
  
  const GameArrayType &array = oper2;
  if (!CheckSize(state, array, 2)) return NOTHING;
  if (!CheckType(state, array[0], GameString)) return NOTHING;
  if (!CheckType(state, array[1], GameArray)) return NOTHING;
  RString name = array[0];
  const GameArrayType &args = array[1];

  // call the method
  return cls->Call(name, args);
}

GameValue AddJPanel(const GameState *state, GameValuePar oper1, GameValuePar oper2)
{
  const GameArrayType &array = oper2;
  if (!CheckSize(state, array, 4)) return NOTHING;
  if (!CheckType(state, array[0], GameScalar)) return NOTHING;
  if (!CheckType(state, array[1], GameScalar)) return NOTHING;
  if (!CheckType(state, array[2], GameScalar)) return NOTHING;
  if (!CheckType(state, array[3], GameScalar)) return NOTHING;

#ifdef _WIN32
  JVMUI *jUI = GWorld->GetJVMUI();
  if (jUI)
  {
    float x = array[0], y = array[1], width = array[2], height = array[3];
    jUI->AddPanel(oper1, toInt(x), toInt(y), toInt(width), toInt(height));
  }
#endif
  return NOTHING;
}

GameValue RemoveJPanel(const GameState *state)
{
#ifdef _WIN32
  JVMUI *jUI = GWorld->GetJVMUI();
  if (jUI)
  {
    jUI->RemovePanel();
  }
#endif
  return NOTHING;
}

GameValue MoveJPanel(const GameState *state, GameValuePar oper1)
{
  const GameArrayType &array = oper1;
  if (!CheckSize(state, array, 2)) return NOTHING;
  if (!CheckType(state, array[0], GameScalar)) return NOTHING;
  if (!CheckType(state, array[1], GameScalar)) return NOTHING;

#ifdef _WIN32
  JVMUI *jUI = GWorld->GetJVMUI();
  if (jUI)
  {
    float x = array[0], y = array[1];
    jUI->MovePanel(toInt(x), toInt(y));
  }
#endif
  return NOTHING;
}

